//! Compile-only analysis of CEL expressions on a dedicated large-stack thread.

use std::fmt;

use crate::limits::{MAX_EXPR_CHARS, MAX_EXPR_NESTING, precheck};

/// Stack size of the analysis thread. The ANTLR-generated CEL parser recurses per
/// nesting level and overflows a 1 MiB Windows stack at around ten levels in debug
/// builds; the thread, not the caller, therefore owns every recursion.
const ANALYZE_STACK_BYTES: usize = 32 << 20;

/// Why an expression could not be analyzed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ExprError {
    TooLong {
        chars: usize,
    },
    TooDeep {
        depth: usize,
    },
    /// The CEL parser's own recursion limit was reached (long unparenthesized
    /// chains such as nested `? :`), which the nesting precheck does not count.
    ParserLimit,
    /// 1-based position relative to the expression text.
    Syntax {
        line: usize,
        column: usize,
        message: String,
    },
    /// Thread spawn failure or a panic inside the compiler or the caller closure.
    Internal,
}

impl fmt::Display for ExprError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::TooLong { chars } => write!(
                f,
                "expression has {chars} characters, the limit is {MAX_EXPR_CHARS}"
            ),
            Self::TooDeep { depth } => write!(
                f,
                "expression nesting reaches {depth} levels, the limit is {MAX_EXPR_NESTING}"
            ),
            Self::Syntax {
                line,
                column,
                message,
            } => write!(f, "syntax error at {line}:{column}: {message}"),
            Self::ParserLimit => f.write_str(
                "expression nests too deeply for the CEL parser; split it into several conditions",
            ),
            Self::Internal => f.write_str("internal error while analyzing expression"),
        }
    }
}

impl std::error::Error for ExprError {}

/// Compiles `src` (never evaluates it) and runs `f` on the compiled program.
///
/// Length and nesting are prechecked first. Compilation and `f` both run on one
/// scoped 32 MiB thread, so the program never leaves it and `f` may recurse over the
/// AST safely. A panic in either becomes [`ExprError::Internal`].
pub fn analyze<R, F>(src: &str, f: F) -> Result<R, ExprError>
where
    F: FnOnce(&cel::Program) -> R + Send,
    R: Send,
{
    precheck(src)?;
    std::thread::scope(|scope| {
        std::thread::Builder::new()
            .stack_size(ANALYZE_STACK_BYTES)
            .spawn_scoped(scope, || compile_and_run(src, f))
            .map_err(|_| ExprError::Internal)?
            .join()
            .map_err(|_| ExprError::Internal)?
    })
}

fn compile_and_run<R>(src: &str, f: impl FnOnce(&cel::Program) -> R) -> Result<R, ExprError> {
    match cel::Program::compile(src) {
        Ok(program) => Ok(f(&program)),
        // `cel` 0.15 reports its recursion limit as a debug-formatted
        // `OtherError(ParseError { .. })`, sometimes after follow-on errors such as
        // "Incomplete `ExprContext`" (WR-08).
        Err(errors)
            if errors
                .errors
                .iter()
                .any(|e| e.msg.contains("Recursion limit of")) =>
        {
            Err(ExprError::ParserLimit)
        }
        Err(errors) => Err(errors.errors.first().map_or_else(
            || ExprError::Syntax {
                line: 1,
                column: 1,
                message: "syntax error".to_owned(),
            },
            |e| ExprError::Syntax {
                line: usize::try_from(e.pos.0).unwrap_or(1),
                column: usize::try_from(e.pos.1).unwrap_or(1),
                message: e.msg.clone(),
            },
        )),
    }
}

//! Static checks of submission criteria (ONT-V13, D-09).
//!
//! `cel` has no declarative variable typing, so the checks are ours: every free
//! variable must be `params`, `user` or `objects` and resolve against the action's
//! parameters and the ontology. All AST recursion happens inside the
//! [`analyze`](crate::analyze()) closure; this module only handles flat result lists.

use std::collections::HashSet;

use ontoforge_schema::diag::{Diagnostic, SourceLocation, codes, did_you_mean};
use ontoforge_schema::ir::{ActionType, Ontology, ParamType, ParameterName, PropertyName};
use ontoforge_schema::loader::SourceMap;
use ontoforge_schema::loader::sourcemap::{DefKey, DefKind, Part, Seg};

use crate::infer::{TypeEnv, type_issues};
use crate::walk::{MemberPath, member_paths};
use crate::{ExprError, analyze};

const ROOTS: &str = "`params`, `user` and `objects`";
const USER_FIELDS: [&str; 2] = ["id", "groups"];

/// Checks every submission criterion of every action type; each problem is an
/// `ONT-V13` error located at the criterion's `condition` value.
#[must_use]
pub fn check_ontology(ontology: &Ontology, sources: &SourceMap) -> Vec<Diagnostic> {
    let mut out = Vec::new();
    for (name, action) in &ontology.action_types {
        let def = DefKey {
            kind: DefKind::ActionType,
            api_name: name.as_str().to_owned(),
        };
        let env = TypeEnv::for_action(action, ontology);
        for (i, criterion) in action.submission_criteria.iter().enumerate() {
            let path = [
                Seg::Key("submissionCriteria".into()),
                Seg::Index(i),
                Seg::Key("condition".into()),
            ];
            let at = sources.locate(&def, &path, Part::Value);
            out.extend(
                check_condition(&criterion.condition, ontology, action, &env)
                    .into_iter()
                    .map(|p| p.into_diagnostic(&at)),
            );
        }
    }
    out
}

/// One finding about a condition, positioned inside the expression text.
struct Problem {
    message: String,
    help: Option<String>,
    /// 1-based `(line, column)` inside the expression.
    pos: Option<(usize, usize)>,
}

impl Problem {
    fn new(message: String, help: impl Into<Option<String>>, pos: Option<(usize, usize)>) -> Self {
        Self {
            message,
            help: help.into(),
            pos,
        }
    }

    fn into_diagnostic(self, at: &SourceLocation) -> Diagnostic {
        let message = match self.pos {
            Some((line, column)) => {
                format!("{} (at {line}:{column} in expression)", self.message)
            }
            None => self.message,
        };
        let diagnostic = Diagnostic::error(codes::V13, message, at);
        match self.help {
            Some(help) => diagnostic.with_help(help),
            None => diagnostic,
        }
    }
}

fn check_condition(
    src: &str,
    ontology: &Ontology,
    action: &ActionType,
    env: &TypeEnv,
) -> Vec<Problem> {
    // Both walks recurse per AST level, so they run inside the analyzer thread.
    let analyzed = analyze(src, |program| {
        (member_paths(program, src), type_issues(program, src, env))
    });
    match analyzed {
        Ok((paths, issues)) => {
            let mut problems = reference_problems(&paths, ontology, action);
            problems.extend(
                issues
                    .into_iter()
                    .map(|i| Problem::new(i.message, None, i.pos)),
            );
            problems
        }
        Err(error) => vec![analyzer_problem(&error)],
    }
}

fn analyzer_problem(error: &ExprError) -> Problem {
    match error {
        ExprError::Syntax {
            line,
            column,
            message,
        } => Problem::new(
            format!("invalid CEL expression: {message}"),
            None,
            Some((*line, *column)),
        ),
        other => Problem::new(format!("invalid CEL expression: {other}"), None, None),
    }
}

/// One problem per distinct message, at its first occurrence.
fn reference_problems(
    paths: &[MemberPath],
    ontology: &Ontology,
    action: &ActionType,
) -> Vec<Problem> {
    let mut seen = HashSet::new();
    paths
        .iter()
        .filter_map(|path| path_problem(path, ontology, action))
        .filter(|problem| seen.insert(problem.message.clone()))
        .collect()
}

fn path_problem(path: &MemberPath, ontology: &Ontology, action: &ActionType) -> Option<Problem> {
    name_problem(path, ontology, action).or_else(|| dynamic_problem(path))
}

/// A non-literal index where a parameter, property or user field name belongs
/// (`params[x]`, `objects.flight[x]`) cannot be checked (WR-02).
fn dynamic_problem(path: &MemberPath) -> Option<Problem> {
    let [root, rest @ ..] = path.segments.as_slice() else {
        return None;
    };
    let names_needed = match root.as_str() {
        "params" | "user" => 1,
        "objects" => 2,
        _ => 0,
    };
    if !path.dynamic || rest.len() >= names_needed {
        return None;
    }
    let shown = path.segments.join(".");
    Some(Problem::new(
        format!("dynamic index on `{shown}` cannot be checked"),
        format!("name the member directly, such as `{shown}.<name>` or `{shown}['<name>']`"),
        path.pos,
    ))
}

fn name_problem(path: &MemberPath, ontology: &Ontology, action: &ActionType) -> Option<Problem> {
    let [root, rest @ ..] = path.segments.as_slice() else {
        return None;
    };
    let pos = path.pos;
    match (root.as_str(), rest) {
        ("params", [name, ..]) => {
            if action.parameters.contains_key(name.as_str()) {
                return None;
            }
            let declared: Vec<&str> = action
                .parameters
                .keys()
                .map(ParameterName::as_str)
                .collect();
            Some(Problem::new(
                format!("unknown parameter `{name}` in `params.{name}`"),
                suggest(name, &declared, "declared parameters"),
                pos,
            ))
        }
        ("objects", [name, tail @ ..]) => object_problem(name, tail.first(), ontology, action, pos),
        ("user", [field, ..]) => {
            if USER_FIELDS.contains(&field.as_str()) {
                return None;
            }
            Some(Problem::new(
                format!("unknown user field `{field}`"),
                suggest(field, &USER_FIELDS, "user fields"),
                pos,
            ))
        }
        ("params" | "objects" | "user", []) => None,
        (other, _) => Some(Problem::new(
            format!("unknown variable `{other}`"),
            format!("expressions can only use {ROOTS}"),
            pos,
        )),
    }
}

/// `objects.<name>` and `objects.<name>.<property>`.
fn object_problem(
    name: &str,
    property: Option<&String>,
    ontology: &Ontology,
    action: &ActionType,
    pos: Option<(usize, usize)>,
) -> Option<Problem> {
    let references: Vec<&str> = action
        .parameters
        .iter()
        .filter(|(_, def)| matches!(def.param_type, ParamType::ObjectReference(_)))
        .map(|(key, _)| key.as_str())
        .collect();
    let Some(def) = action.parameters.get(name) else {
        return Some(Problem::new(
            format!("unknown parameter `{name}` in `objects.{name}`"),
            suggest(name, &references, "objectReference parameters"),
            pos,
        ));
    };
    let ParamType::ObjectReference(target) = &def.param_type else {
        return Some(Problem::new(
            format!("`objects.{name}` needs an objectReference parameter, but `{name}` is not one"),
            suggest(name, &references, "objectReference parameters"),
            pos,
        ));
    };
    let property = property?;
    // A missing target type is reported by validate (V09) before this runs.
    let object_type = ontology.object_types.get(target.as_str())?;
    if object_type.properties.contains_key(property.as_str()) {
        return None;
    }
    let known: Vec<&str> = object_type
        .properties
        .keys()
        .map(PropertyName::as_str)
        .collect();
    Some(Problem::new(
        format!(
            "object type `{target}` has no property `{property}` in `objects.{name}.{property}`"
        ),
        suggest(property, &known, &format!("properties of `{target}`")),
        pos,
    ))
}

/// A "did you mean" hint, or the list of valid names when nothing is close.
fn suggest(name: &str, candidates: &[&str], what: &str) -> String {
    match did_you_mean(name, candidates.iter().copied()) {
        Some(close) => format!("did you mean `{close}`?"),
        None if candidates.is_empty() => format!("there are no {what}"),
        None => format!("{what}: {}", candidates.join(", ")),
    }
}

//! Conservative type inference over the CEL AST (RESEARCH A7).
//!
//! `cel` has no declarative typing, so this is a small inference of our own: only
//! bool, int, double, string and lists take part in compatibility checks. Everything
//! else (decimal, date, timestamp, geopoint, object references, unknown functions,
//! unresolved references) is [`Ty::Any`], which is compatible with every type and
//! never produces an error.
//!
//! The walk recurses once per AST level: call [`type_issues`] only from inside the
//! [`analyze`](crate::analyze()) closure, which runs on the large-stack thread and
//! only ever sees prechecked input.

use std::collections::HashMap;
use std::fmt;

use cel::common::ast::operators as op;
use cel::common::ast::{CallExpr, Expr, IdedExpr, LiteralValue, SourceInfo};
use ontoforge_schema::ir::{ActionType, BaseType, Ontology, ParamType};

use crate::walk::char_pos;

/// An inferred type.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Ty {
    Bool,
    Int,
    Double,
    String,
    List(Box<Ty>),
    /// Not inferable; compatible with everything.
    Any,
}

impl fmt::Display for Ty {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Bool => "bool",
            Self::Int => "int",
            Self::Double => "double",
            Self::String => "string",
            Self::List(_) => "list",
            Self::Any => "any",
        })
    }
}

impl Ty {
    fn is_numeric(&self) -> bool {
        matches!(self, Self::Int | Self::Double)
    }

    /// Whether values of the two types may be compared. Int and double mix.
    fn compatible(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::Any, _) | (_, Self::Any) => true,
            (Self::List(a), Self::List(b)) => a.compatible(b),
            (a, b) => a == b || (a.is_numeric() && b.is_numeric()),
        }
    }
}

fn base_ty(base: BaseType, items: Option<BaseType>) -> Ty {
    match base {
        BaseType::Byte | BaseType::Short | BaseType::Integer | BaseType::Long => Ty::Int,
        BaseType::Float | BaseType::Double => Ty::Double,
        BaseType::String => Ty::String,
        BaseType::Boolean => Ty::Bool,
        BaseType::Array => Ty::List(Box::new(items.map_or(Ty::Any, |i| base_ty(i, None)))),
        BaseType::Decimal | BaseType::Date | BaseType::Timestamp | BaseType::Geopoint => Ty::Any,
    }
}

/// The types of the variables one action's conditions can see.
#[derive(Debug, Default)]
pub struct TypeEnv {
    params: HashMap<String, Ty>,
    /// `objectReference` parameter name to the property types of its object type.
    objects: HashMap<String, HashMap<String, Ty>>,
}

impl TypeEnv {
    #[must_use]
    pub fn for_action(action: &ActionType, ontology: &Ontology) -> Self {
        let mut env = Self::default();
        for (name, def) in &action.parameters {
            let ty = def
                .param_type
                .base_type()
                .map_or(Ty::Any, |base| base_ty(base, def.items));
            env.params.insert(name.as_str().to_owned(), ty);
            if let ParamType::ObjectReference(target) = &def.param_type
                && let Some(object_type) = ontology.object_types.get(target.as_str())
            {
                let props = object_type
                    .properties
                    .iter()
                    .map(|(prop, p)| (prop.as_str().to_owned(), base_ty(p.base_type, p.items)))
                    .collect();
                env.objects.insert(name.as_str().to_owned(), props);
            }
        }
        env
    }

    /// Type of a member path rooted at a free variable; unknown paths are `Any`.
    fn lookup(&self, segments: &[&str]) -> Ty {
        match segments {
            ["params", name] => self.params.get(*name).cloned(),
            ["objects", name, prop] => self.objects.get(*name).and_then(|p| p.get(*prop)).cloned(),
            ["user", "id"] => Some(Ty::String),
            ["user", "groups"] => Some(Ty::List(Box::new(Ty::String))),
            _ => None,
        }
        .unwrap_or(Ty::Any)
    }
}

/// A type problem, positioned inside the expression.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TypeIssue {
    pub message: String,
    /// 1-based `(line, column)` inside the expression.
    pub pos: Option<(usize, usize)>,
}

/// Incompatible comparisons, and a top-level result that is inferably not bool.
/// `src` must be the text `program` was compiled from.
#[must_use]
pub fn type_issues(program: &cel::Program, src: &str, env: &TypeEnv) -> Vec<TypeIssue> {
    let mut inferer = Inferer {
        info: program.source_info(),
        src,
        env,
        scope: Vec::new(),
        issues: Vec::new(),
    };
    let root = program.expression();
    let ty = inferer.infer(root);
    if !matches!(ty, Ty::Bool | Ty::Any) {
        inferer.issue(
            root.id,
            format!("condition must evaluate to bool, found {ty}"),
        );
    }
    inferer.issues
}

struct Inferer<'a> {
    info: &'a SourceInfo,
    src: &'a str,
    env: &'a TypeEnv,
    /// Comprehension variables currently in scope, innermost last.
    scope: Vec<(&'a str, Ty)>,
    issues: Vec<TypeIssue>,
}

impl<'a> Inferer<'a> {
    fn issue(&mut self, id: u64, message: String) {
        let pos = self
            .info
            .offset_for(id)
            .map(|(start, _)| char_pos(self.src, start as usize));
        self.issues.push(TypeIssue { message, pos });
    }

    fn scoped(&self, name: &str) -> Option<&Ty> {
        self.scope
            .iter()
            .rev()
            .find(|(n, _)| *n == name)
            .map(|(_, t)| t)
    }

    fn infer(&mut self, e: &'a IdedExpr) -> Ty {
        match &e.expr {
            Expr::Unspecified => Ty::Any,
            Expr::Literal(lit) => match lit {
                LiteralValue::Boolean(_) => Ty::Bool,
                LiteralValue::Int(_) => Ty::Int,
                LiteralValue::Double(_) => Ty::Double,
                LiteralValue::String(_) => Ty::String,
                LiteralValue::Bytes(_) | LiteralValue::UInt(_) | LiteralValue::Null => Ty::Any,
            },
            Expr::Ident(name) => self.scoped(name).cloned().unwrap_or(Ty::Any),
            Expr::Select(_) => self.select(e),
            Expr::Call(call) => self.call(e.id, call),
            Expr::List(list) => {
                let tys: Vec<Ty> = list.elements.iter().map(|el| self.infer(el)).collect();
                let element = match tys.split_first() {
                    Some((first, rest)) if rest.iter().all(|t| t == first) => first.clone(),
                    _ => Ty::Any,
                };
                Ty::List(Box::new(element))
            }
            Expr::Map(map) => {
                self.entries(&map.entries);
                Ty::Any
            }
            Expr::Struct(s) => {
                self.entries(&s.entries);
                Ty::Any
            }
            Expr::Comprehension(c) => {
                let range = self.infer(&c.iter_range);
                let accu = self.infer(&c.accu_init);
                let element = match range {
                    Ty::List(inner) => *inner,
                    _ => Ty::Any,
                };
                let mark = self.scope.len();
                self.scope.push((&c.iter_var, element));
                if let Some(second) = &c.iter_var2 {
                    self.scope.push((second, Ty::Any));
                }
                self.scope.push((&c.accu_var, accu));
                self.infer(&c.loop_cond);
                self.infer(&c.loop_step);
                let result = self.infer(&c.result);
                self.scope.truncate(mark);
                result
            }
        }
    }

    fn entries(&mut self, entries: &'a [cel::common::ast::IdedEntryExpr]) {
        use cel::common::ast::EntryExpr;
        for entry in entries {
            match &entry.expr {
                EntryExpr::MapEntry(m) => {
                    self.infer(&m.key);
                    self.infer(&m.value);
                }
                EntryExpr::StructField(f) => {
                    self.infer(&f.value);
                }
            }
        }
    }

    /// A field selection: a member path rooted at a free variable is looked up in the
    /// environment; any other shape is walked for its comparisons and is `Any`.
    fn select(&mut self, e: &'a IdedExpr) -> Ty {
        let mut fields = Vec::new();
        let mut node = e;
        while let Expr::Select(sel) = &node.expr {
            if sel.test {
                // A `has()` test is a bool and ends the path.
                if std::ptr::eq(node, e) {
                    self.infer(&sel.operand);
                    return Ty::Bool;
                }
                break;
            }
            fields.push(sel.field.as_str());
            node = &sel.operand;
        }
        match &node.expr {
            Expr::Ident(root) if self.scoped(root).is_none() => {
                let segments: Vec<&str> = std::iter::once(root.as_str())
                    .chain(fields.iter().rev().copied())
                    .collect();
                self.env.lookup(&segments)
            }
            _ => {
                self.infer(node);
                Ty::Any
            }
        }
    }

    fn call(&mut self, id: u64, call: &'a CallExpr) -> Ty {
        if let Some(target) = &call.target {
            self.infer(target);
        }
        let args: Vec<Ty> = call.args.iter().map(|a| self.infer(a)).collect();
        match call.func_name.as_str() {
            op::LOGICAL_AND
            | op::LOGICAL_OR
            | op::LOGICAL_NOT
            | op::IN
            | op::NOT_STRICTLY_FALSE => Ty::Bool,
            op::EQUALS
            | op::NOT_EQUALS
            | op::LESS
            | op::LESS_EQUALS
            | op::GREATER
            | op::GREATER_EQUALS => {
                if let [left, right] = args.as_slice()
                    && !left.compatible(right)
                {
                    self.issue(id, format!("cannot compare {left} with {right}"));
                }
                Ty::Bool
            }
            op::ADD | op::SUBSTRACT | op::MULTIPLY | op::DIVIDE | op::MODULO => {
                match args.as_slice() {
                    [Ty::String, Ty::String] if call.func_name == op::ADD => Ty::String,
                    [left, right] => arithmetic(left, right).unwrap_or_else(|()| {
                        let symbol = call.func_name.trim_matches('_');
                        self.issue(
                            id,
                            format!(
                                "cannot apply {symbol} to {left} and {right}; convert one side with int(...) or double(...)"
                            ),
                        );
                        Ty::Any
                    }),
                    _ => Ty::Any,
                }
            }
            op::NEGATE => match args.as_slice() {
                [only] if only.is_numeric() => only.clone(),
                _ => Ty::Any,
            },
            op::CONDITIONAL => match args.as_slice() {
                [_, then, otherwise] if then == otherwise => then.clone(),
                _ => Ty::Any,
            },
            "size" => Ty::Int,
            op::HAS | "matches" | "startsWith" | "endsWith" | "contains" => Ty::Bool,
            _ => Ty::Any,
        }
    }
}

/// Result type of an arithmetic operator. `cel` evaluates `+ - * / %` only when both
/// operands have the same numeric type (WR-01), so int with double is an error
/// (comparisons do mix, see [`Ty::compatible`]).
fn arithmetic(left: &Ty, right: &Ty) -> Result<Ty, ()> {
    match (left, right) {
        (Ty::Int, Ty::Int) => Ok(Ty::Int),
        (Ty::Double, Ty::Double) => Ok(Ty::Double),
        (l, r) if l.is_numeric() && r.is_numeric() => Err(()),
        _ => Ok(Ty::Any),
    }
}

