//! Lexical precheck run before any expression reaches the CEL compiler.
//!
//! The scan mirrors the lexer rules of `cel` 0.15 (`src/parser/gen/CEL.g4`) closely
//! enough that bracket nesting is never undercounted: string literals (single, double
//! and triple quoted, with `r` / `b` / `br` prefixes), `//` comments and numbers are
//! skipped the way the real lexer skips them. Anything the real lexer would reject
//! (unterminated string, invalid escape) is rejected here too, so no input whose
//! tokenization we could get wrong ever reaches the compiler.

use crate::analyze::ExprError;

/// Maximum expression length, counted in `char`s.
pub const MAX_EXPR_CHARS: usize = 4096;
/// Maximum bracket nesting depth (`(`, `[`, `{`).
pub const MAX_EXPR_NESTING: usize = 32;

/// Checks length, bracket nesting and string literal termination.
pub fn precheck(src: &str) -> Result<(), ExprError> {
    let chars = src.chars().count();
    if chars > MAX_EXPR_CHARS {
        return Err(ExprError::TooLong { chars });
    }
    let mut scan = Scanner::new(src);
    let mut depth = 0usize;
    while let Some(c) = scan.peek(0) {
        match c {
            '(' | '[' | '{' => {
                depth += 1;
                if depth > MAX_EXPR_NESTING {
                    return Err(ExprError::TooDeep { depth });
                }
                scan.bump();
            }
            ')' | ']' | '}' => {
                depth = depth.saturating_sub(1);
                scan.bump();
            }
            '/' if scan.peek(1) == Some('/') => {
                while scan.peek(0).is_some_and(|c| c != '\n') {
                    scan.bump();
                }
            }
            '\'' | '"' => scan.string(false)?,
            c if c.is_ascii_alphabetic() || c == '_' => scan.identifier_or_prefixed_string()?,
            c if c.is_ascii_digit() => scan.number(),
            _ => scan.bump(),
        }
    }
    Ok(())
}

struct Scanner {
    chars: Vec<char>,
    index: usize,
    line: usize,
    column: usize,
}

impl Scanner {
    fn new(src: &str) -> Self {
        Self {
            chars: src.chars().collect(),
            index: 0,
            line: 1,
            column: 1,
        }
    }

    fn peek(&self, ahead: usize) -> Option<char> {
        self.chars.get(self.index + ahead).copied()
    }

    fn bump(&mut self) {
        if let Some(c) = self.peek(0) {
            self.index += 1;
            if c == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
        }
    }

    fn bump_n(&mut self, n: usize) {
        for _ in 0..n {
            self.bump();
        }
    }

    fn syntax(line: usize, column: usize, message: &str) -> ExprError {
        ExprError::Syntax {
            line,
            column,
            message: message.to_owned(),
        }
    }

    /// Consumes a whole identifier; when a quote follows directly, consumes the string
    /// literal as well (raw when the identifier is `r` or `br`, any case).
    fn identifier_or_prefixed_string(&mut self) -> Result<(), ExprError> {
        let start = self.index;
        while self
            .peek(0)
            .is_some_and(|c| c.is_ascii_alphanumeric() || c == '_')
        {
            self.bump();
        }
        if !matches!(self.peek(0), Some('\'' | '"')) {
            return Ok(());
        }
        let ident: String = self.chars[start..self.index].iter().collect();
        // `b'..'` is an ordinary bytes literal and any other identifier is followed by
        // an ordinary string, so only `r` and `br` switch escapes off.
        self.string(ident.eq_ignore_ascii_case("r") || ident.eq_ignore_ascii_case("br"))
    }

    /// Skips a numeric literal so a following `r'...'` is seen at a token boundary.
    fn number(&mut self) {
        let is_hex = |c: Option<char>| c.is_some_and(|c| c.is_ascii_hexdigit());
        let is_digit = |c: Option<char>| c.is_some_and(|c| c.is_ascii_digit());
        if self.peek(0) == Some('0') && self.peek(1) == Some('x') && is_hex(self.peek(2)) {
            self.bump_n(2);
            while is_hex(self.peek(0)) {
                self.bump();
            }
            return;
        }
        while is_digit(self.peek(0)) {
            self.bump();
        }
        if self.peek(0) == Some('.') && is_digit(self.peek(1)) {
            self.bump();
            while is_digit(self.peek(0)) {
                self.bump();
            }
        }
        if matches!(self.peek(0), Some('e' | 'E')) {
            let sign = usize::from(matches!(self.peek(1), Some('+' | '-')));
            if is_digit(self.peek(1 + sign)) {
                self.bump_n(1 + sign);
                while is_digit(self.peek(0)) {
                    self.bump();
                }
            }
        }
    }

    /// Consumes one string literal starting at the opening quote.
    fn string(&mut self, raw: bool) -> Result<(), ExprError> {
        let (line, column) = (self.line, self.column);
        let unterminated = || Self::syntax(line, column, "unterminated string literal");
        let Some(quote) = self.peek(0) else {
            return Ok(());
        };
        let triple = self.peek(1) == Some(quote) && self.peek(2) == Some(quote);
        self.bump_n(if triple { 3 } else { 1 });
        loop {
            let Some(c) = self.peek(0) else {
                return Err(unterminated());
            };
            if triple {
                if c == quote && self.peek(1) == Some(quote) && self.peek(2) == Some(quote) {
                    self.bump_n(3);
                    return Ok(());
                }
            } else if c == '\n' || c == '\r' {
                return Err(unterminated());
            } else if c == quote {
                self.bump();
                return Ok(());
            }
            if c == '\\' && !raw {
                self.escape()?;
            } else {
                self.bump();
            }
        }
    }

    /// Consumes one escape sequence (cursor on the backslash); same set as `ESC_SEQ`.
    fn escape(&mut self) -> Result<(), ExprError> {
        let (line, column) = (self.line, self.column);
        let hex = |scan: &Self, from: usize, n: usize| {
            (from..from + n).all(|i| scan.peek(i).is_some_and(|c| c.is_ascii_hexdigit()))
        };
        let octal = |scan: &Self, i: usize| scan.peek(i).is_some_and(|c| ('0'..='7').contains(&c));
        let len = match self.peek(1) {
            None => {
                return Err(Self::syntax(line, column, "unterminated string literal"));
            }
            Some('a' | 'b' | 'f' | 'n' | 'r' | 't' | 'v' | '"' | '\'' | '\\' | '?' | '`') => 2,
            Some('0'..='3') if octal(self, 2) && octal(self, 3) => 4,
            Some('x' | 'X') if hex(self, 2, 2) => 4,
            Some('u') if hex(self, 2, 4) => 6,
            Some('U') if hex(self, 2, 8) => 10,
            Some(_) => return Err(Self::syntax(line, column, "invalid escape sequence")),
        };
        self.bump_n(len);
        Ok(())
    }
}

//! Single-row evaluation of a [`Pred`] with SQL three-valued (Kleene) logic (D-06).

use std::collections::BTreeMap;

use ontoforge_schema::ir::PropertyName;

use std::cmp::Ordering;

use super::ir::{CmpOp, ListSource, MatchKind, Operand, Pred};
use super::value::{AttrValue, Attrs, Scalar};

/// A truth value that can be unknown. Only [`Tri::True`] makes a row visible.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tri {
    True,
    False,
    Unknown,
}

impl From<bool> for Tri {
    fn from(b: bool) -> Self {
        if b { Self::True } else { Self::False }
    }
}

impl Tri {
    /// Kleene conjunction: false wins over unknown.
    #[must_use]
    pub fn and(self, other: Tri) -> Tri {
        match (self, other) {
            (Self::False, _) | (_, Self::False) => Self::False,
            (Self::True, Self::True) => Self::True,
            _ => Self::Unknown,
        }
    }

    /// Kleene disjunction: true wins over unknown.
    #[must_use]
    pub fn or(self, other: Tri) -> Tri {
        match (self, other) {
            (Self::True, _) | (_, Self::True) => Self::True,
            (Self::False, Self::False) => Self::False,
            _ => Self::Unknown,
        }
    }

    #[must_use]
    #[allow(clippy::should_implement_trait)] // the plan 03-05 interface names it `not`
    pub fn not(self) -> Tri {
        match self {
            Self::True => Self::False,
            Self::False => Self::True,
            Self::Unknown => Self::Unknown,
        }
    }

    /// Unknown is invisible (D-06).
    #[must_use]
    pub fn is_true(self) -> bool {
        self == Self::True
    }
}

/// The property values of one row. A property that is absent is [`Scalar::Null`].
pub trait RowValues {
    fn value(&self, property: &PropertyName) -> Scalar;
}

impl RowValues for BTreeMap<PropertyName, Scalar> {
    fn value(&self, property: &PropertyName) -> Scalar {
        self.get(property).cloned().unwrap_or(Scalar::Null)
    }
}

/// Evaluates `pred` against one row and the caller's principal attributes.
pub fn eval(pred: &Pred, row: &impl RowValues, attrs: &Attrs) -> Tri {
    match pred {
        Pred::Const(b) => Tri::from(*b),
        Pred::And(a, b) => match eval(a, row, attrs) {
            Tri::False => Tri::False,
            left => left.and(eval(b, row, attrs)),
        },
        Pred::Or(a, b) => match eval(a, row, attrs) {
            Tri::True => Tri::True,
            left => left.or(eval(b, row, attrs)),
        },
        Pred::Not(p) => eval(p, row, attrs).not(),
        Pred::Cmp { left, op, right } => {
            compare(&scalar(left, row, attrs), *op, &scalar(right, row, attrs))
        }
        Pred::IsNull { operand, negated } => {
            let is_null = scalar(operand, row, attrs) == Scalar::Null;
            Tri::from(is_null != *negated)
        }
        Pred::InList { operand, list } => {
            let x = scalar(operand, row, attrs);
            match list {
                ListSource::Literal(items) => in_items(&x, items),
                ListSource::Attr(name) => match attrs.get(name) {
                    AttrValue::List(items) => in_items(&x, items),
                    // A missing list attribute is Null (D-05): unknown, not empty.
                    AttrValue::Null | AttrValue::Scalar(_) => Tri::Unknown,
                },
            }
        }
        Pred::StrMatch {
            column,
            needle,
            kind,
        } => match (row.value(column), scalar(needle, row, attrs)) {
            // Byte-wise on UTF-8, case-sensitive, no wildcards (ADR-0025 rule 3).
            (Scalar::String(haystack), Scalar::String(needle)) => Tri::from(match kind {
                MatchKind::StartsWith => haystack.starts_with(&needle),
                MatchKind::EndsWith => haystack.ends_with(&needle),
                MatchKind::Contains => haystack.contains(&needle),
            }),
            _ => Tri::Unknown,
        },
    }
}

/// SQL `x IN (items)` (ADR-0025 rule 1): an empty list is false even for a Null `x`;
/// otherwise a match is true, and an unknown comparison (Null `x` or Null element)
/// leaves the result unknown.
fn in_items(x: &Scalar, items: &[Scalar]) -> Tri {
    if items.is_empty() {
        return Tri::False;
    }
    let mut result = Tri::False;
    for item in items {
        result = result.or(compare(x, CmpOp::Eq, item));
        if result == Tri::True {
            break;
        }
    }
    result
}

/// The value of an operand. A principal attribute that is missing, or a list where a
/// scalar is expected, is Null (D-05).
fn scalar(operand: &Operand, row: &impl RowValues, attrs: &Attrs) -> Scalar {
    match operand {
        Operand::Column(c) => row.value(c),
        Operand::Lit(s) => s.clone(),
        Operand::Attr(name) => match attrs.get(name) {
            AttrValue::Scalar(s) => s.clone(),
            AttrValue::Null | AttrValue::List(_) => Scalar::Null,
        },
    }
}

/// Order of two non-null values of the same family; `None` when either side is Null,
/// the families differ, or a double is NaN.
fn ordering(a: &Scalar, b: &Scalar) -> Option<Ordering> {
    match (a, b) {
        (Scalar::Bool(a), Scalar::Bool(b)) => Some(a.cmp(b)),
        (Scalar::Int(a), Scalar::Int(b)) => Some(a.cmp(b)),
        (Scalar::Double(a), Scalar::Double(b)) => a.partial_cmp(b),
        // Byte order of UTF-8 equals code point order: SQLite BINARY, PG `COLLATE "C"`.
        (Scalar::String(a), Scalar::String(b)) => Some(a.as_bytes().cmp(b.as_bytes())),
        _ => None,
    }
}

fn compare(a: &Scalar, op: CmpOp, b: &Scalar) -> Tri {
    let Some(ord) = ordering(a, b) else {
        return Tri::Unknown;
    };
    Tri::from(match op {
        CmpOp::Eq => ord == Ordering::Equal,
        CmpOp::Ne => ord != Ordering::Equal,
        CmpOp::Lt => ord == Ordering::Less,
        CmpOp::Le => ord != Ordering::Greater,
        CmpOp::Gt => ord == Ordering::Greater,
        CmpOp::Ge => ord != Ordering::Less,
    })
}

//! The row predicate IR: what a `rowFilter` looks like after parsing (D-07).
//!
//! `Pred` is the only form a predicate takes after [`compile_row_filter`]
//! (`super::compile_row_filter`). The Rust evaluator and the SQL lowering (plan 03-11)
//! both start from it, never from the `cel` AST or the `cel` runtime.

use std::collections::BTreeSet;
use std::fmt;

use ontoforge_schema::ir::PropertyName;

use super::value::Scalar;

/// A row predicate.
#[derive(Debug, Clone, PartialEq)]
pub enum Pred {
    Const(bool),
    Cmp {
        left: Operand,
        op: CmpOp,
        right: Operand,
    },
    /// `operand == null` (`negated: false`) or `operand != null` (`negated: true`).
    /// Always two-valued.
    IsNull {
        operand: Operand,
        negated: bool,
    },
    InList {
        operand: Operand,
        list: ListSource,
    },
    StrMatch {
        column: PropertyName,
        needle: Operand,
        kind: MatchKind,
    },
    And(Box<Pred>, Box<Pred>),
    Or(Box<Pred>, Box<Pred>),
    Not(Box<Pred>),
}

/// One side of a comparison.
#[derive(Debug, Clone, PartialEq)]
pub enum Operand {
    /// `object.<property>`.
    Column(PropertyName),
    Lit(Scalar),
    /// `principal.attrs.<name>`, resolved at evaluation (or SQL compilation) time.
    Attr(String),
}

/// Right-hand side of `in`.
#[derive(Debug, Clone, PartialEq)]
pub enum ListSource {
    /// A list literal. Never holds [`Scalar::Null`].
    Literal(Vec<Scalar>),
    /// A list-typed `principal.attrs.<name>`.
    Attr(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CmpOp {
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
}

impl CmpOp {
    fn symbol(self) -> &'static str {
        match self {
            Self::Eq => "==",
            Self::Ne => "!=",
            Self::Lt => "<",
            Self::Le => "<=",
            Self::Gt => ">",
            Self::Ge => ">=",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MatchKind {
    StartsWith,
    EndsWith,
    Contains,
}

impl MatchKind {
    fn method(self) -> &'static str {
        match self {
            Self::StartsWith => "startsWith",
            Self::EndsWith => "endsWith",
            Self::Contains => "contains",
        }
    }
}

impl Pred {
    /// Every `object.<property>` the predicate reads.
    #[must_use]
    pub fn referenced_properties(&self) -> BTreeSet<PropertyName> {
        let mut out = BTreeSet::new();
        self.collect(
            &mut |c| {
                out.insert(c.clone());
            },
            &mut |_| {},
        );
        out
    }

    /// Every `principal.attrs.<name>` the predicate reads.
    #[must_use]
    pub fn referenced_attrs(&self) -> BTreeSet<String> {
        let mut out = BTreeSet::new();
        self.collect(&mut |_| {}, &mut |a| {
            out.insert(a.to_owned());
        });
        out
    }

    fn collect(&self, column: &mut dyn FnMut(&PropertyName), attr: &mut dyn FnMut(&str)) {
        fn operand(o: &Operand, column: &mut dyn FnMut(&PropertyName), attr: &mut dyn FnMut(&str)) {
            match o {
                Operand::Column(c) => column(c),
                Operand::Attr(a) => attr(a),
                Operand::Lit(_) => {}
            }
        }
        match self {
            Self::Const(_) => {}
            Self::Cmp { left, right, .. } => {
                operand(left, column, attr);
                operand(right, column, attr);
            }
            Self::IsNull { operand: o, .. } => operand(o, column, attr),
            Self::InList { operand: o, list } => {
                operand(o, column, attr);
                if let ListSource::Attr(a) = list {
                    attr(a);
                }
            }
            Self::StrMatch {
                column: c, needle, ..
            } => {
                column(c);
                operand(needle, column, attr);
            }
            Self::And(a, b) | Self::Or(a, b) => {
                a.collect(column, attr);
                b.collect(column, attr);
            }
            Self::Not(p) => p.collect(column, attr),
        }
    }
}

/// Canonical CEL text of a scalar literal.
fn write_scalar(f: &mut fmt::Formatter<'_>, s: &Scalar) -> fmt::Result {
    match s {
        Scalar::Null => f.write_str("null"),
        Scalar::Bool(b) => write!(f, "{b}"),
        Scalar::Int(i) => write!(f, "{i}"),
        // `{:?}` always keeps a `.` or an exponent, so the text stays a double.
        Scalar::Double(d) => write!(f, "{d:?}"),
        Scalar::String(s) => {
            f.write_str("'")?;
            for c in s.chars() {
                match c {
                    '\\' => f.write_str("\\\\")?,
                    '\'' => f.write_str("\\'")?,
                    '\n' => f.write_str("\\n")?,
                    '\r' => f.write_str("\\r")?,
                    '\t' => f.write_str("\\t")?,
                    c if c.is_control() => write!(f, "\\u{:04x}", u32::from(c))?,
                    c => write!(f, "{c}")?,
                }
            }
            f.write_str("'")
        }
    }
}

impl fmt::Display for Operand {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Column(c) => write!(f, "object.{c}"),
            Self::Attr(a) => write!(f, "principal.attrs.{a}"),
            Self::Lit(s) => write_scalar(f, s),
        }
    }
}

impl fmt::Display for ListSource {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Attr(a) => write!(f, "principal.attrs.{a}"),
            Self::Literal(items) => {
                f.write_str("[")?;
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        f.write_str(", ")?;
                    }
                    write_scalar(f, item)?;
                }
                f.write_str("]")
            }
        }
    }
}

/// Canonical CEL text that [`compile_row_filter`](super::compile_row_filter) parses
/// back to an equal `Pred`: every binary form is parenthesized and `Not` keeps a
/// parenthesis between two `!` (the CEL grammar folds a bare run of them).
impl fmt::Display for Pred {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Const(b) => write!(f, "{b}"),
            Self::Cmp { left, op, right } => write!(f, "({left} {} {right})", op.symbol()),
            Self::IsNull { operand, negated } => {
                write!(f, "({operand} {} null)", if *negated { "!=" } else { "==" })
            }
            Self::InList { operand, list } => write!(f, "({operand} in {list})"),
            Self::StrMatch {
                column,
                needle,
                kind,
            } => write!(f, "object.{column}.{}({needle})", kind.method()),
            Self::And(a, b) => write!(f, "({a} && {b})"),
            Self::Or(a, b) => write!(f, "({a} || {b})"),
            Self::Not(p) => match **p {
                Self::Not(_) => write!(f, "!({p})"),
                _ => write!(f, "!{p}"),
            },
        }
    }
}

//! CEL row predicates: parsed with `cel` into an own `Pred` IR and evaluated with
//! Kleene three-valued logic (D-06, ADR-0025). This module never uses the `cel`
//! runtime to evaluate: its `null == 'a'` is false and `null != 'a'` is true, the
//! opposite of D-06.

pub mod eval;
pub mod ir;
pub mod parse;
pub mod value;

pub use eval::{RowValues, Tri, eval};
pub use ir::{CmpOp, ListSource, MatchKind, Operand, Pred};
pub use parse::{PredContext, PredIssue, compile_row_filter};
pub use value::{AttrValue, AttrValueError, Attrs, Scalar};

//! CEL text to [`Pred`]: parse with `cel`, lower to the own IR, same-row and type checks.
//!
//! The `cel` program never leaves the [`analyze`](crate::analyze()) closure: the AST
//! is lowered there into an owned [`Pred`]. Evaluation never goes through `cel`.

use std::collections::BTreeMap;

use cel::common::ast::operators as op;
use cel::common::ast::{CallExpr, Expr, IdedExpr, LiteralValue, SourceInfo};
use ontoforge_schema::ir::{AttrType, BaseType, ObjectType};

use super::ir::{CmpOp, ListSource, MatchKind, Operand, Pred};
use super::value::Scalar;
use crate::analyze::{ExprError, analyze};
use crate::walk::char_pos;

/// What a row filter may refer to.
pub struct PredContext<'a> {
    /// The object type whose rows the filter selects.
    pub object_type: &'a ObjectType,
    /// The declared principal attributes (`[auth.principal_attrs]`, D-05).
    pub attrs: &'a BTreeMap<String, AttrType>,
}

/// A row filter problem, positioned inside the expression.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PredIssue {
    pub message: String,
    /// 1-based `(line, column)` inside the expression.
    pub pos: Option<(usize, usize)>,
}

/// Compiles `src` into a [`Pred`].
///
/// # Errors
///
/// Every problem found, positioned inside the expression.
pub fn compile_row_filter(src: &str, cx: &PredContext<'_>) -> Result<Pred, Vec<PredIssue>> {
    let lowered = analyze(src, |program| {
        let mut lowerer = Lowerer {
            info: program.source_info(),
            src,
            cx,
            issues: Vec::new(),
        };
        let pred = lowerer.pred(program.expression());
        (pred, lowerer.issues)
    });
    match lowered {
        Ok((Some(pred), issues)) if issues.is_empty() => Ok(pred),
        Ok((_, issues)) if !issues.is_empty() => Err(issues),
        Ok(_) => Err(vec![PredIssue {
            message: "internal error while lowering the row filter".to_owned(),
            pos: None,
        }]),
        Err(e) => Err(vec![expr_issue(&e)]),
    }
}

fn expr_issue(e: &ExprError) -> PredIssue {
    match e {
        ExprError::Syntax {
            line,
            column,
            message,
        } => PredIssue {
            message: format!("syntax error: {message}"),
            pos: Some((*line, *column)),
        },
        other => PredIssue {
            message: other.to_string(),
            pos: None,
        },
    }
}

/// Value family of an operand. Comparisons need both sides in the same family; `int`
/// and `double` do not mix (Rust and SQL would otherwise disagree on the conversion).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Fam {
    Bool,
    Int,
    Double,
    Str,
}

impl Fam {
    fn name(self) -> &'static str {
        match self {
            Self::Bool => "bool",
            Self::Int => "int",
            Self::Double => "double",
            Self::Str => "string",
        }
    }

    fn ordered(self) -> bool {
        self != Self::Bool
    }
}

/// Static type of an operand.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Ty {
    Fam(Fam),
    /// A property type row filters cannot compare (date, timestamp, decimal, array,
    /// geopoint). Only `== null` / `!= null` may read it.
    Opaque(BaseType),
    /// A list-typed `principal.attrs.<name>`; only valid on the right of `in`.
    List(Fam),
    Null,
}

/// Friendly name of an operator or function in an "is not allowed" message.
fn describe(func: &str) -> String {
    match func {
        op::ADD | op::SUBSTRACT | op::MULTIPLY | op::DIVIDE | op::MODULO | op::NEGATE => {
            "arithmetic".to_owned()
        }
        op::CONDITIONAL => "the conditional operator `? :`".to_owned(),
        op::INDEX | op::OPT_INDEX => "indexing".to_owned(),
        "size" | "matches" => format!("`{func}()`"),
        _ => format!("`{func}`"),
    }
}

fn property_ty(base: BaseType) -> Ty {
    match base {
        BaseType::Byte | BaseType::Short | BaseType::Integer | BaseType::Long => Ty::Fam(Fam::Int),
        BaseType::Float | BaseType::Double => Ty::Fam(Fam::Double),
        BaseType::String => Ty::Fam(Fam::Str),
        BaseType::Boolean => Ty::Fam(Fam::Bool),
        other => Ty::Opaque(other),
    }
}

fn attr_ty(ty: AttrType) -> Ty {
    match ty {
        AttrType::String => Ty::Fam(Fam::Str),
        AttrType::Integer => Ty::Fam(Fam::Int),
        AttrType::Boolean => Ty::Fam(Fam::Bool),
        AttrType::StringList => Ty::List(Fam::Str),
        AttrType::IntegerList => Ty::List(Fam::Int),
    }
}

struct Lowerer<'a> {
    info: &'a SourceInfo,
    src: &'a str,
    cx: &'a PredContext<'a>,
    issues: Vec<PredIssue>,
}

impl Lowerer<'_> {
    fn issue(&mut self, id: u64, message: impl Into<String>) {
        let pos = self
            .info
            .offset_for(id)
            .map(|(start, _)| char_pos(self.src, start as usize));
        self.issues.push(PredIssue {
            message: message.into(),
            pos,
        });
    }

    /// Lowers a node in boolean position. `None` means an issue was recorded.
    fn pred(&mut self, e: &IdedExpr) -> Option<Pred> {
        match &e.expr {
            Expr::Literal(LiteralValue::Boolean(b)) => Some(Pred::Const(*b.inner())),
            Expr::Call(call) => self.call_pred(e, call),
            Expr::Comprehension(_) => {
                self.issue(
                    e.id,
                    "macros (all, exists, exists_one, map, filter) are not allowed in a row filter",
                );
                None
            }
            Expr::Select(sel) if sel.test => {
                self.issue(e.id, "has() is not allowed in a row filter");
                None
            }
            _ => {
                self.issue(
                    e.id,
                    "a row filter must be a comparison, `in`, startsWith/endsWith/contains, \
                     or a combination of them with && || !",
                );
                None
            }
        }
    }

    fn call_pred(&mut self, e: &IdedExpr, call: &CallExpr) -> Option<Pred> {
        match (call.func_name.as_str(), call.args.as_slice()) {
            (op::LOGICAL_AND, [a, b]) => {
                let (a, b) = (self.pred(a), self.pred(b));
                Some(Pred::And(Box::new(a?), Box::new(b?)))
            }
            (op::LOGICAL_OR, [a, b]) => {
                let (a, b) = (self.pred(a), self.pred(b));
                Some(Pred::Or(Box::new(a?), Box::new(b?)))
            }
            (op::LOGICAL_NOT, [a]) => Some(Pred::Not(Box::new(self.pred(a)?))),
            (op::EQUALS, [a, b]) => self.cmp(e.id, CmpOp::Eq, a, b),
            (op::NOT_EQUALS, [a, b]) => self.cmp(e.id, CmpOp::Ne, a, b),
            (op::LESS, [a, b]) => self.cmp(e.id, CmpOp::Lt, a, b),
            (op::LESS_EQUALS, [a, b]) => self.cmp(e.id, CmpOp::Le, a, b),
            (op::GREATER, [a, b]) => self.cmp(e.id, CmpOp::Gt, a, b),
            (op::GREATER_EQUALS, [a, b]) => self.cmp(e.id, CmpOp::Ge, a, b),
            (op::IN, [x, list]) => self.in_list(e.id, x, list),
            (name, args) => {
                let kind = match name {
                    "startsWith" => Some(MatchKind::StartsWith),
                    "endsWith" => Some(MatchKind::EndsWith),
                    "contains" => Some(MatchKind::Contains),
                    _ => None,
                };
                if let (Some(kind), Some(target), [needle]) = (kind, call.target.as_deref(), args) {
                    return self.str_match(kind, target, needle);
                }
                self.issue(
                    e.id,
                    format!("{} is not allowed in a row filter", describe(name)),
                );
                None
            }
        }
    }

    fn in_list(&mut self, id: u64, x: &IdedExpr, list: &IdedExpr) -> Option<Pred> {
        let (operand, list) = (self.operand(x), self.list_source(list));
        let ((operand, ty), (list, element)) = (operand?, list?);
        let fam = match ty {
            Ty::Fam(f) => f,
            Ty::Null => {
                self.issue(id, "`null` cannot be tested with `in`; use `== null`");
                return None;
            }
            Ty::Opaque(t) => {
                self.issue(
                    id,
                    format!("a {} property cannot be used with `in`", t.as_str()),
                );
                return None;
            }
            Ty::List(_) => {
                self.issue(
                    id,
                    "a list-typed principal attribute can only be used on the right of `in`",
                );
                return None;
            }
        };
        if let Some(element) = element
            && element != fam
        {
            self.issue(
                id,
                format!(
                    "cannot test a {} value against a list of {} values",
                    fam.name(),
                    element.name()
                ),
            );
            return None;
        }
        Some(Pred::InList { operand, list })
    }

    /// The right side of `in`: a list literal of non-null literals of one family, or a
    /// list-typed principal attribute. The family is `None` for `[]`.
    fn list_source(&mut self, e: &IdedExpr) -> Option<(ListSource, Option<Fam>)> {
        if let Expr::List(list) = &e.expr {
            let mut items = Vec::with_capacity(list.elements.len());
            let mut family: Option<Fam> = None;
            let mut ok = true;
            for element in &list.elements {
                let Some((operand, ty)) = self.operand(element) else {
                    ok = false;
                    continue;
                };
                match (operand, ty) {
                    (Operand::Lit(s), Ty::Fam(f)) => {
                        if family.is_some_and(|first| first != f) {
                            self.issue(element.id, "list elements must all have the same type");
                            ok = false;
                        }
                        family.get_or_insert(f);
                        items.push(s);
                    }
                    (_, Ty::Null) => {
                        self.issue(
                            element.id,
                            "a list in a row filter must not contain `null`; test it with `== null`",
                        );
                        ok = false;
                    }
                    _ => {
                        self.issue(element.id, "list elements must be literals");
                        ok = false;
                    }
                }
            }
            return ok.then_some((ListSource::Literal(items), family));
        }
        let (operand, ty) = self.operand(e)?;
        if let (Operand::Attr(name), Ty::List(f)) = (operand, ty) {
            return Some((ListSource::Attr(name), Some(f)));
        }
        self.issue(
            e.id,
            "the right side of `in` must be a list literal or a list-typed              `principal.attrs.<name>`",
        );
        None
    }

    fn str_match(&mut self, kind: MatchKind, target: &IdedExpr, needle: &IdedExpr) -> Option<Pred> {
        let (t, n) = (self.operand(target), self.operand(needle));
        let column = match t {
            Some((Operand::Column(c), Ty::Fam(Fam::Str))) => Some(c),
            Some(_) => {
                self.issue(
                    target.id,
                    "startsWith, endsWith and contains apply to an `object.<property>` of type string",
                );
                None
            }
            None => None,
        };
        let needle = match n {
            Some((o @ (Operand::Lit(Scalar::String(_)) | Operand::Attr(_)), Ty::Fam(Fam::Str))) => {
                Some(o)
            }
            Some(_) => {
                self.issue(
                    needle.id,
                    "the argument must be a string literal or a string `principal.attrs.<name>`",
                );
                None
            }
            None => None,
        };
        Some(Pred::StrMatch {
            column: column?,
            needle: needle?,
            kind,
        })
    }

    fn cmp(&mut self, id: u64, op: CmpOp, a: &IdedExpr, b: &IdedExpr) -> Option<Pred> {
        let (left, right) = (self.operand(a), self.operand(b));
        let ((left, lt), (right, rt)) = (left?, right?);
        match (lt, rt) {
            (Ty::Null, Ty::Null) => {
                self.issue(id, "`null` cannot be compared with `null`");
                None
            }
            (Ty::Null, _) | (_, Ty::Null) => {
                let (operand, ty) = if lt == Ty::Null {
                    (right, rt)
                } else {
                    (left, lt)
                };
                self.is_null(id, op, operand, ty)
            }
            (Ty::Fam(l), Ty::Fam(r)) if l == r => {
                if op != CmpOp::Eq && op != CmpOp::Ne && !l.ordered() {
                    self.issue(id, "bool values can only be compared with == and !=");
                    return None;
                }
                Some(Pred::Cmp { left, op, right })
            }
            (Ty::Fam(l), Ty::Fam(r)) => {
                self.issue(
                    id,
                    format!(
                        "cannot compare {} with {}: no implicit conversion between value families",
                        l.name(),
                        r.name()
                    ),
                );
                None
            }
            (Ty::Opaque(t), _) | (_, Ty::Opaque(t)) => {
                self.issue(
                    id,
                    format!(
                        "a {} property cannot be used in a comparison; it can only be compared \
                         with `null`",
                        t.as_str()
                    ),
                );
                None
            }
            (Ty::List(_), _) | (_, Ty::List(_)) => {
                self.issue(
                    id,
                    "a list-typed principal attribute can only be used on the right of `in`",
                );
                None
            }
        }
    }

    fn is_null(&mut self, id: u64, op: CmpOp, operand: Operand, ty: Ty) -> Option<Pred> {
        if op != CmpOp::Eq && op != CmpOp::Ne {
            self.issue(id, "`null` can only be compared with == and !=");
            return None;
        }
        if matches!(operand, Operand::Lit(_)) {
            self.issue(
                id,
                "`== null` needs an object property or a principal attribute",
            );
            return None;
        }
        match ty {
            Ty::Opaque(BaseType::Geopoint) => {
                self.issue(id, "a geopoint property cannot be used in a row filter");
                None
            }
            Ty::List(_) => {
                self.issue(
                    id,
                    "a list-typed principal attribute can only be used on the right of `in`",
                );
                None
            }
            _ => Some(Pred::IsNull {
                operand,
                negated: op == CmpOp::Ne,
            }),
        }
    }

    /// Lowers a node in operand position.
    fn operand(&mut self, e: &IdedExpr) -> Option<(Operand, Ty)> {
        match &e.expr {
            Expr::Literal(lit) => match lit {
                LiteralValue::Boolean(b) => {
                    Some((Operand::Lit(Scalar::Bool(*b.inner())), Ty::Fam(Fam::Bool)))
                }
                LiteralValue::Int(i) => {
                    Some((Operand::Lit(Scalar::Int(*i.inner())), Ty::Fam(Fam::Int)))
                }
                LiteralValue::Double(d) => Some((
                    Operand::Lit(Scalar::Double(*d.inner())),
                    Ty::Fam(Fam::Double),
                )),
                LiteralValue::String(s) => Some((
                    Operand::Lit(Scalar::String(s.inner().to_owned())),
                    Ty::Fam(Fam::Str),
                )),
                LiteralValue::Null => Some((Operand::Lit(Scalar::Null), Ty::Null)),
                LiteralValue::Bytes(_) | LiteralValue::UInt(_) => {
                    self.issue(
                        e.id,
                        "bytes and uint literals are not allowed in a row filter",
                    );
                    None
                }
            },
            Expr::Select(sel) if sel.test => {
                self.issue(e.id, "has() is not allowed in a row filter");
                None
            }
            Expr::Select(_) => self.path(e),
            Expr::Ident(name) => {
                self.root_issue(e.id, name);
                None
            }
            Expr::Comprehension(_) => {
                self.issue(
                    e.id,
                    "macros (all, exists, exists_one, map, filter) are not allowed in a row filter",
                );
                None
            }
            Expr::Call(call) => {
                self.issue(
                    e.id,
                    format!("`{}` is not allowed in a row filter", call.func_name),
                );
                None
            }
            _ => {
                self.issue(e.id, "this expression is not allowed in a row filter");
                None
            }
        }
    }

    fn root_issue(&mut self, id: u64, name: &str) {
        let message = match name {
            "object" | "principal" => format!(
                "`{name}` cannot be used on its own; write `object.<property>` or \
                 `principal.attrs.<name>`"
            ),
            _ => format!(
                "unknown variable `{name}`: a row filter can only use `object` and \
                 `principal.attrs`"
            ),
        };
        self.issue(id, message);
    }

    /// Resolves `object.<property>` or `principal.attrs.<name>`.
    fn path(&mut self, e: &IdedExpr) -> Option<(Operand, Ty)> {
        let mut fields = Vec::new();
        let mut node = e;
        while let Expr::Select(sel) = &node.expr {
            if sel.test {
                self.issue(e.id, "has() is not allowed in a row filter");
                return None;
            }
            fields.push(sel.field.as_str());
            node = &sel.operand;
        }
        fields.reverse();
        let Expr::Ident(root) = &node.expr else {
            self.issue(
                e.id,
                "only `object.<property>` and `principal.attrs.<name>` can be read",
            );
            return None;
        };
        let root_id = node.id;
        match (root.as_str(), fields.as_slice()) {
            ("object", [name]) => self.property(root_id, name),
            ("object", _) => {
                self.issue(
                    root_id,
                    "write `object.<property>` with exactly one property name",
                );
                None
            }
            ("principal", ["attrs", name]) => self.attr(root_id, name),
            ("principal", ["id" | "groups"]) => {
                self.issue(
                    root_id,
                    "`principal.id` and `principal.groups` are not available in a row filter; \
                     use `principal.attrs.<name>`",
                );
                None
            }
            ("principal", _) => {
                self.issue(root_id, "write `principal.attrs.<name>`");
                None
            }
            (other, _) => {
                self.root_issue(root_id, other);
                None
            }
        }
    }

    fn property(&mut self, id: u64, name: &str) -> Option<(Operand, Ty)> {
        let Some((key, def)) = self.cx.object_type.properties.get_key_value(name) else {
            self.issue(
                id,
                format!(
                    "object type `{}` has no property `{name}`",
                    self.cx.object_type.api_name
                ),
            );
            return None;
        };
        Some((Operand::Column(key.clone()), property_ty(def.base_type)))
    }

    fn attr(&mut self, id: u64, name: &str) -> Option<(Operand, Ty)> {
        let Some(ty) = self.cx.attrs.get(name) else {
            self.issue(
                id,
                format!(
                    "principal attribute `{name}` is not declared in `[auth.principal_attrs]` \
                     of ontoforge-server.toml"
                ),
            );
            return None;
        };
        Some((Operand::Attr(name.to_owned()), attr_ty(*ty)))
    }
}

//! Runtime values of principal attributes (D-05).

use std::collections::BTreeMap;
use std::fmt;

/// One non-list value.
///
/// `Null` is the SQL NULL of three-valued evaluation. It is only meaningful as
/// a row value or as a result; an attribute that is absent is [`AttrValue::Null`].
#[derive(Debug, Clone, PartialEq)]
pub enum Scalar {
    Null,
    Bool(bool),
    Int(i64),
    Double(f64),
    String(String),
}

/// The value of one principal attribute.
#[derive(Debug, Clone, PartialEq)]
pub enum AttrValue {
    /// Missing or not provided by the identity provider.
    Null,
    Scalar(Scalar),
    /// A list. It never holds [`Scalar::Null`] (`x in list` stays two-valued).
    List(Vec<Scalar>),
}

/// An attribute value that cannot be stored.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AttrValueError {
    /// A list element is NULL.
    NullInList,
    /// A scalar wraps NULL; use [`AttrValue::Null`] to express absence.
    NullScalar,
}

impl fmt::Display for AttrValueError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NullInList => f.write_str("a list attribute must not contain NULL"),
            Self::NullScalar => {
                f.write_str("a scalar attribute must not wrap NULL; use AttrValue::Null")
            }
        }
    }
}

impl std::error::Error for AttrValueError {}

static NULL: AttrValue = AttrValue::Null;

/// The attributes of one principal, by declared name.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Attrs(BTreeMap<String, AttrValue>);

impl Attrs {
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores `value` under `name`, replacing an earlier value.
    ///
    /// # Errors
    ///
    /// [`AttrValueError::NullInList`] when a list holds [`Scalar::Null`], and
    /// [`AttrValueError::NullScalar`] when a scalar wraps it.
    pub fn insert(
        &mut self,
        name: impl Into<String>,
        value: AttrValue,
    ) -> Result<(), AttrValueError> {
        match &value {
            AttrValue::List(items) if items.contains(&Scalar::Null) => {
                return Err(AttrValueError::NullInList);
            }
            AttrValue::Scalar(Scalar::Null) => return Err(AttrValueError::NullScalar),
            _ => {}
        }
        self.0.insert(name.into(), value);
        Ok(())
    }

    /// The value of `name`; [`AttrValue::Null`] when undeclared or absent (D-05).
    #[must_use]
    pub fn get(&self, name: &str) -> &AttrValue {
        self.0.get(name).unwrap_or(&NULL)
    }

    pub fn iter(&self) -> impl Iterator<Item = (&str, &AttrValue)> {
        self.0.iter().map(|(k, v)| (k.as_str(), v))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn attrs_missing_is_null() {
        let attrs = Attrs::new();
        assert_eq!(attrs.get("tenantId"), &AttrValue::Null);
    }

    #[test]
    fn attrs_list_rejects_null_element() {
        let mut attrs = Attrs::new();
        let bad = AttrValue::List(vec![Scalar::String("eu".into()), Scalar::Null]);
        assert!(attrs.insert("regions", bad).is_err());
        assert_eq!(attrs.get("regions"), &AttrValue::Null);
    }
}

//! Scope-aware walk over the CEL AST that collects member paths.
//!
//! `cel`'s own reference listing counts comprehension variables as free variables, so
//! the walk keeps its own scope stack. It recurses once per AST level: call it only
//! from inside the [`analyze`](crate::analyze()) closure, which runs on the large-stack
//! thread and only ever sees prechecked input.

use cel::common::ast::operators as op;
use cel::common::ast::{EntryExpr, Expr, IdedExpr, LiteralValue, SourceInfo};
use ontoforge_schema::diag::offset_to_line_col;

/// A member path rooted at a free variable, e.g. `params.items`. A string-literal
/// index is a segment like a field (`params['items']` is `params.items`, WR-02).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MemberPath {
    pub segments: Vec<String>,
    /// 1-based `(line, column)` inside the expression, column counted in chars.
    pub pos: Option<(usize, usize)>,
    /// The path is followed by an index that is not a string literal, so whatever
    /// it selects next cannot be checked.
    pub dynamic: bool,
}

/// One step of a member path: `.field`, `['field']` (`Some`), or an index that is
/// not a string literal (`None`), with the operand it applies to.
fn step(e: &IdedExpr) -> Option<(Option<&str>, &IdedExpr)> {
    match &e.expr {
        Expr::Select(sel) => Some((Some(sel.field.as_str()), &sel.operand)),
        Expr::Call(call) if call.func_name == op::INDEX && call.target.is_none() => {
            match call.args.as_slice() {
                [operand, key] => match &key.expr {
                    Expr::Literal(LiteralValue::String(s)) => Some((Some(&**s), operand)),
                    _ => Some((None, operand)),
                },
                _ => None,
            }
        }
        _ => None,
    }
}

/// Collects the member paths rooted at free variables of `program`, in source walk
/// order and without deduplication. `src` must be the text `program` was compiled from.
#[must_use]
pub fn member_paths(program: &cel::Program, src: &str) -> Vec<MemberPath> {
    let mut walker = Walker {
        info: program.source_info(),
        src,
        scope: Vec::new(),
        out: Vec::new(),
    };
    walker.visit(program.expression());
    walker.out
}

/// 1-based `(line, column)` of a `cel` source offset, column counted in chars.
/// `SourceInfo::offset_for` yields 0-based UTF-8 byte offsets (verified against 0.15.0
/// with a multi-byte literal), which is what `offset_to_line_col` takes.
pub(crate) fn char_pos(src: &str, offset: usize) -> (usize, usize) {
    let (line, column) = offset_to_line_col(src, offset);
    (line as usize, column as usize)
}

struct Walker<'a> {
    info: &'a SourceInfo,
    src: &'a str,
    /// Comprehension variables currently in scope (iteration and accumulator).
    scope: Vec<&'a str>,
    out: Vec<MemberPath>,
}

impl<'a> Walker<'a> {
    fn pos(&self, ids: &[u64]) -> Option<(usize, usize)> {
        ids.iter().find_map(|&id| {
            let (start, _) = self.info.offset_for(id)?;
            Some(char_pos(self.src, start as usize))
        })
    }

    fn in_scope(&self, name: &str) -> bool {
        self.scope.contains(&name)
    }

    fn visit(&mut self, e: &'a IdedExpr) {
        match &e.expr {
            Expr::Unspecified | Expr::Literal(_) => {}
            Expr::Ident(name) => {
                if !self.in_scope(name) {
                    let pos = self.pos(&[e.id]);
                    self.out.push(MemberPath {
                        segments: vec![name.clone()],
                        pos,
                        dynamic: false,
                    });
                }
            }
            Expr::Select(_) => self.select(e),
            Expr::Call(_) if step(e).is_some() => self.select(e),
            Expr::Call(call) => {
                if let Some(target) = &call.target {
                    self.visit(target);
                }
                call.args.iter().for_each(|a| self.visit(a));
            }
            Expr::List(list) => list.elements.iter().for_each(|a| self.visit(a)),
            Expr::Map(map) => map.entries.iter().for_each(|entry| match &entry.expr {
                EntryExpr::MapEntry(m) => {
                    self.visit(&m.key);
                    self.visit(&m.value);
                }
                EntryExpr::StructField(f) => self.visit(&f.value),
            }),
            Expr::Struct(s) => s.entries.iter().for_each(|entry| match &entry.expr {
                EntryExpr::StructField(f) => self.visit(&f.value),
                EntryExpr::MapEntry(m) => {
                    self.visit(&m.key);
                    self.visit(&m.value);
                }
            }),
            Expr::Comprehension(c) => {
                self.visit(&c.iter_range);
                self.visit(&c.accu_init);
                let mark = self.scope.len();
                self.scope.push(&c.iter_var);
                if let Some(second) = &c.iter_var2 {
                    self.scope.push(second);
                }
                self.scope.push(&c.accu_var);
                self.visit(&c.loop_cond);
                self.visit(&c.loop_step);
                self.visit(&c.result);
                self.scope.truncate(mark);
            }
        }
    }

    /// Handles a chain of field selections and indexes: descends through them (and
    /// the outermost `has()` test) to its root. A free identifier root yields the
    /// path; any other root is walked on its own. A non-literal index is walked on
    /// its own and cuts the path there: only the part below it can be checked.
    fn select(&mut self, outermost: &'a IdedExpr) {
        let mut fields = Vec::new();
        let mut dynamic = false;
        let mut node = outermost;
        while let Some((field, operand)) = step(node) {
            if let Some(field) = field {
                fields.push(field);
            } else {
                if let Expr::Call(call) = &node.expr {
                    call.args.iter().skip(1).for_each(|key| self.visit(key));
                }
                fields.clear();
                dynamic = true;
            }
            node = operand;
            if matches!(&node.expr, Expr::Select(inner) if inner.test) {
                break;
            }
        }
        match &node.expr {
            Expr::Ident(root) if !self.in_scope(root) => {
                let pos = self.pos(&[node.id, outermost.id]);
                let segments = std::iter::once(root.as_str())
                    .chain(fields.iter().rev().copied())
                    .map(str::to_owned)
                    .collect();
                self.out.push(MemberPath {
                    segments,
                    pos,
                    dynamic,
                });
            }
            Expr::Ident(_) => {}
            _ => self.visit(node),
        }
    }
}

use std::sync::atomic::{AtomicBool, Ordering};

use ontoforge_expr::{ExprError, MAX_EXPR_CHARS, analyze};

/// `n` layers of parentheses around `1`.
fn nested(n: usize) -> String {
    format!("{}1{}", "(".repeat(n), ")".repeat(n))
}

/// Runs `analyze` and reports whether the closure was invoked.
fn run(src: &str) -> (Result<(), ExprError>, bool) {
    let called = AtomicBool::new(false);
    let result = analyze(src, |_| called.store(true, Ordering::SeqCst));
    (result, called.load(Ordering::SeqCst))
}

#[test]
fn too_long_expression_is_rejected_without_compiling() {
    let (result, called) = run(&"a".repeat(MAX_EXPR_CHARS + 1));
    assert_eq!(
        result,
        Err(ExprError::TooLong {
            chars: MAX_EXPR_CHARS + 1
        })
    );
    assert!(!called);
}

#[test]
fn max_length_expression_is_accepted() {
    let (result, called) = run(&"a".repeat(MAX_EXPR_CHARS));
    assert_eq!(result, Ok(()));
    assert!(called);
}

#[test]
fn brackets_inside_strings_do_not_count() {
    let parens = "(".repeat(40);
    for src in [
        format!("'{parens}' == params.a"),
        format!("\"{parens}\" == params.a"),
    ] {
        let (result, called) = run(&src);
        assert_eq!(result, Ok(()), "{src}");
        assert!(called, "{src}");
    }
}

#[test]
fn triple_quoted_and_raw_strings_follow_cel_lexing() {
    let parens = "(".repeat(40);
    let triple = format!("'''it's {parens}''' == params.a");
    let (result, called) = run(&triple);
    assert_eq!(result, Ok(()), "{triple}");
    assert!(called);

    // Raw strings do not escape the closing quote, so `r'\'` is complete and the
    // 33 layers after it are real nesting.
    let raw = format!("r'\\' == {}", nested(33));
    let (result, called) = run(&raw);
    assert!(
        matches!(result, Err(ExprError::TooDeep { .. })),
        "{result:?}"
    );
    assert!(!called);

    let bytes_raw = format!("br'\\' == {}", nested(33));
    assert!(matches!(run(&bytes_raw).0, Err(ExprError::TooDeep { .. })));
}

#[test]
fn raw_prefix_requires_a_token_boundary() {
    // `ar'` is the identifier `ar` followed by an ordinary string, so `\'` escapes
    // the quote and the string swallows everything up to the final quote.
    let (result, _) = run(&format!("ar'\\' {} '", "(".repeat(40)));
    assert!(
        !matches!(result, Err(ExprError::TooDeep { .. })),
        "{result:?}"
    );

    // After a number a new token starts, so `r'\'` is raw again.
    let src = format!("1 r'\\' {}", nested(33));
    assert!(matches!(run(&src).0, Err(ExprError::TooDeep { .. })));
    let src = format!("1r'\\' {}", nested(33));
    assert!(matches!(run(&src).0, Err(ExprError::TooDeep { .. })));
}

#[test]
fn comments_do_not_open_strings() {
    let src = format!("// '''\n{}\n// '''", nested(33));
    let (result, called) = run(&src);
    assert!(
        matches!(result, Err(ExprError::TooDeep { .. })),
        "{result:?}"
    );
    assert!(!called);
}

#[test]
fn invalid_escape_is_rejected_without_compiling() {
    let (result, called) = run(&format!("'\\q{}'", "(".repeat(40)));
    assert!(
        matches!(
            result,
            Err(ExprError::Syntax {
                line: 1,
                column: 2,
                ..
            })
        ),
        "{result:?}"
    );
    assert!(!called);
}

#[test]
fn unterminated_string_is_rejected_without_compiling() {
    let (result, called) = run("params.a == 'abc");
    match result {
        Err(ExprError::Syntax {
            line,
            column,
            message,
        }) => {
            assert_eq!((line, column), (1, 13));
            assert!(message.contains("unterminated"), "{message}");
        }
        other => panic!("expected Syntax, got {other:?}"),
    }
    assert!(!called);
}

#[test]
fn deeply_nested_expression_is_rejected_not_crashing() {
    let handle = std::thread::Builder::new()
        .stack_size(1 << 20)
        .spawn(|| {
            let (too_deep, called_deep) = run(&nested(33));
            assert!(
                matches!(too_deep, Err(ExprError::TooDeep { .. })),
                "{too_deep:?}"
            );
            assert!(!called_deep);

            let (ok, called_ok) = run(&nested(31));
            assert_eq!(ok, Ok(()));
            assert!(called_ok);
        })
        .expect("spawn small-stack thread");
    handle
        .join()
        .expect("small-stack thread must not panic or overflow");
}

#[test]
fn syntax_error_has_expression_position() {
    let (result, called) = run("params.x +");
    match result {
        Err(ExprError::Syntax { line, column, .. }) => assert_eq!((line, column), (1, 11)),
        other => panic!("expected Syntax, got {other:?}"),
    }
    assert!(!called);
}

#[test]
fn closure_panic_becomes_internal() {
    let result: Result<(), ExprError> = analyze("1", |_| panic!("boom"));
    assert_eq!(result, Err(ExprError::Internal));
}

#[test]
fn flat_recursive_forms_do_not_crash_on_a_small_stack() {
    let handle = std::thread::Builder::new()
        .stack_size(1 << 20)
        .spawn(|| {
            // Neither form uses brackets, so only the compiler's own limits stop them.
            for src in [
                format!("{}true", "!".repeat(4000)),
                format!("{}1", "a ? b : ".repeat(500)),
                format!("1{}", " + 1".repeat(1000)),
            ] {
                let (result, _) = run(&src);
                assert!(
                    matches!(
                        result,
                        Ok(()) | Err(ExprError::Syntax { .. } | ExprError::ParserLimit)
                    ),
                    "{result:?}"
                );
            }
        })
        .expect("spawn small-stack thread");
    handle
        .join()
        .expect("small-stack thread must not panic or overflow");
}

mod walk {
    use ontoforge_expr::{analyze, member_paths};

    /// `(dotted path, position)` for each member path, via the isolated compile.
    fn paths(src: &str) -> Vec<(String, Option<(usize, usize)>)> {
        analyze(src, |p| member_paths(p, src))
            .expect("expression compiles")
            .into_iter()
            .map(|m| (m.segments.join("."), m.pos))
            .collect()
    }

    fn names(src: &str) -> Vec<String> {
        paths(src).into_iter().map(|(n, _)| n).collect()
    }

    #[test]
    fn comprehension_vars_are_scoped() {
        assert_eq!(names("params.items.all(i, i.qty > 0)"), ["params.items"]);
    }

    #[test]
    fn nested_comprehension_scopes() {
        assert_eq!(
            names("params.a.exists(x, params.b.all(y, x == y))"),
            ["params.a", "params.b"]
        );
    }

    #[test]
    fn has_macro_yields_member_path() {
        let found = paths("has(params.note)");
        assert_eq!(found.len(), 1);
        assert_eq!(found[0].0, "params.note");
        assert!(found[0].1.is_some());
    }

    #[test]
    fn select_chain_is_full_path() {
        assert_eq!(
            paths("objects.flight.status != 'X'"),
            [("objects.flight.status".to_owned(), Some((1, 1)))]
        );
    }

    #[test]
    fn bare_identifier_is_a_path() {
        assert_eq!(names("foo > 1"), ["foo"]);
    }

    #[test]
    fn index_breaks_path() {
        assert_eq!(names("params.items[0].qty > 0"), ["params.items"]);
    }

    #[test]
    fn positions_are_line_and_char_column() {
        let found = paths("params.a > 1 &&\n  params.b");
        assert_eq!(found[1], ("params.b".to_owned(), Some((2, 3))));
        let found = paths("'é' == params.x");
        assert_eq!(found, [("params.x".to_owned(), Some((1, 8)))]);
    }

    #[test]
    fn map_list_and_method_targets_are_walked() {
        assert_eq!(
            names("{'k': params.a}['k'] == params.b"),
            ["params.a", "params.b"]
        );
        assert_eq!(
            names("[params.a, user.id].size() > params.n.size()"),
            ["params.a", "user.id", "params.n"]
        );
    }

    #[test]
    fn has_on_comprehension_variable_yields_nothing() {
        assert_eq!(names("params.items.all(i, has(i.note))"), ["params.items"]);
    }
}

//! Static checks of submission criteria: references (Task 1) and types (Task 2).

use ontoforge_expr::check_ontology;
use ontoforge_schema::diag::{Diagnostic, Severity, codes};
use ontoforge_schema::load_from_memory;

const MANIFEST: &str = "apiName: demo\n";

const OBJECTS: &str = "kind: ObjectType
apiName: Flight
primaryKey: flightId
properties:
  flightId: { type: string, required: true }
  status: { type: string }
  delayMinutes: { type: integer }
  departure: { type: timestamp }
  flightDate: { type: date }
  fare: { type: decimal }
  position: { type: geopoint }
backing: editOnly
";

/// Header of the single action; the criterion line is appended by `check`.
const ACTION_HEAD: &str = "kind: ActionType
apiName: delayFlight
parameters:
  flight: { type: { objectReference: Flight }, required: true }
  delayMinutes: { type: integer, required: true }
  tags: { type: array, items: string }
rules:
  - kind: modifyObject
    object: flight
    properties:
      status: { static: DELAYED }
submissionCriteria:
";

fn actions_for(condition: &str) -> String {
    let quoted = condition.replace('\\', "\\\\").replace('"', "\\\"");
    format!("{ACTION_HEAD}  - condition: \"{quoted}\"\n    failureMessage: nope\n")
}

fn run(condition: &str) -> Vec<Diagnostic> {
    let actions = actions_for(condition);
    let out = load_from_memory(&[
        ("ontology.yaml", MANIFEST),
        ("objects.yaml", OBJECTS),
        ("actions.yaml", &actions),
    ]);
    assert!(out.diagnostics.is_empty(), "{:#?}", out.diagnostics);
    let ontology = out.ontology.expect("ontology");
    check_ontology(&ontology, &out.sources)
}

fn only(condition: &str) -> Diagnostic {
    let mut diags = run(condition);
    assert_eq!(diags.len(), 1, "{condition}: {diags:#?}");
    diags.remove(0)
}

fn assert_clean(condition: &str) {
    let diags = run(condition);
    assert!(diags.is_empty(), "{condition}: {diags:#?}");
}

#[test]
fn aviation_criteria_pass() {
    let dir = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../examples/ontologies/aviation"
    );
    let texts: Vec<(String, String)> = [
        "ontology.yaml",
        "objects.yaml",
        "links.yaml",
        "actions.yaml",
    ]
    .iter()
    .map(|n| {
        let text = std::fs::read_to_string(format!("{dir}/{n}")).expect("aviation file");
        ((*n).to_owned(), text)
    })
    .collect();
    let files: Vec<(&str, &str)> = texts
        .iter()
        .map(|(n, t)| (n.as_str(), t.as_str()))
        .collect();
    let out = load_from_memory(&files);
    assert!(out.diagnostics.is_empty(), "{:#?}", out.diagnostics);
    let ontology = out.ontology.expect("ontology");
    let diags = check_ontology(&ontology, &out.sources);
    assert!(diags.is_empty(), "{diags:#?}");
}

#[test]
fn analyzer_errors_become_v13() {
    let too_long = only(&"a".repeat(5000));
    assert_eq!(too_long.code, codes::V13);
    assert!(too_long.message.contains("4096"), "{}", too_long.message);

    let too_deep = only(&format!("{}1{}", "(".repeat(40), ")".repeat(40)));
    assert_eq!(too_deep.code, codes::V13);
    assert!(too_deep.message.contains("nesting"), "{}", too_deep.message);

    let syntax = only("params.delayMinutes +");
    assert_eq!(syntax.code, codes::V13);
    assert_eq!(syntax.severity, Severity::Error);
    assert!(
        syntax.message.contains("(at 1:22 in expression)"),
        "{}",
        syntax.message
    );
}

