    );
    let d = only("objects.flight['nope'] == 'x'");
    assert!(d.message.contains("no property `nope`"), "{}", d.message);
}

/// WR-02: an index that is not a literal cannot be checked where a name is expected.
#[test]
fn dynamic_index_on_a_checked_root_is_an_error() {
    let d = only("params[params.tags[0]] == 1");
    assert_eq!(d.code, codes::V13);
    assert!(d.message.contains("dynamic index"), "{}", d.message);
    let d = only("objects.flight[params.tags[0]] == 1");
    assert!(d.message.contains("dynamic index"), "{}", d.message);
}

/// WR-08: the CEL parser's recursion limit is reported without its internals.
#[test]
fn parser_recursion_limit_has_a_clean_message() {
    let deep = format!("{}true", "true ? false : ".repeat(120));
    let d = only(&deep);
    assert_eq!(d.code, codes::V13);
    assert!(d.message.contains("too deeply"), "{}", d.message);
    assert!(!d.message.contains("OtherError"), "{}", d.message);
}

//! Diagnostic model shared by the loader, validation, lint and the CLI (D-10).

use serde::Serialize;

/// Diagnostic severity. Serialized as `error` / `warning` / `info`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Severity {
    Error,
    Warning,
    Info,
}

/// Byte span inside the source text, consumed by miette.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct Span {
    pub offset: usize,
    pub length: usize,
}

/// Converts a 0-based UTF-8 byte offset into a 1-based `(line, column)` pair, with the
/// column counted in chars. An offset inside a multi-byte char is moved back to the
/// start of that char; one past the end is clamped to the end of `text`.
#[must_use]
pub fn offset_to_line_col(text: &str, byte_offset: usize) -> (u32, u32) {
    let start = text.floor_char_boundary(byte_offset);
    let before = &text[..start];
    let line = before.matches('\n').count() + 1;
    let column = before.chars().rev().take_while(|c| *c != '\n').count() + 1;
    (
        u32::try_from(line).unwrap_or(u32::MAX),
        u32::try_from(column).unwrap_or(u32::MAX),
    )
}

/// A resolved position inside a source file.
///
/// `file` is relative to the ontology root and always uses `/` separators.
/// `line` and `column` are 1-based; `0` means "no position".
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SourceLocation {
    pub file: String,
    pub line: u32,
    pub column: u32,
    pub offset: usize,
    pub length: usize,
}

/// One finding. Wire format is camelCase JSON (D-10).
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Diagnostic {
    pub code: String,
    pub severity: Severity,
    pub message: String,
    pub file: String,
    pub line: u32,
    pub column: u32,
    pub span: Span,
    pub help: Option<String>,
}

impl Diagnostic {
    pub fn new(
        code: &str,
        severity: Severity,
        message: impl Into<String>,
        at: &SourceLocation,
    ) -> Self {
        Self {
            code: code.to_owned(),
            severity,
            message: message.into(),
            file: at.file.clone(),
            line: at.line,
            column: at.column,
            span: Span {
                offset: at.offset,
                length: at.length,
            },
            help: None,
        }
    }

    pub fn error(code: &str, message: impl Into<String>, at: &SourceLocation) -> Self {
        Self::new(code, Severity::Error, message, at)
    }

    pub fn without_location(
        code: &str,
        severity: Severity,
        message: impl Into<String>,
        file: impl Into<String>,
    ) -> Self {
        Self {
            code: code.to_owned(),
            severity,
            message: message.into(),
            file: file.into(),
            line: 0,
            column: 0,
            span: Span {
                offset: 0,
                length: 0,
            },
            help: None,
        }
    }

    #[must_use]
    pub fn with_help(mut self, help: impl Into<String>) -> Self {
        self.help = Some(help.into());
        self
    }
}

/// Deterministic order: `(file, line, column, code, message)`.
pub fn sort_diagnostics(diags: &mut [Diagnostic]) {
    diags.sort_by(|a, b| {
        (&a.file, a.line, a.column, &a.code, &a.message)
            .cmp(&(&b.file, b.line, b.column, &b.code, &b.message))
    });
}

pub fn has_errors(diags: &[Diagnostic]) -> bool {
    diags.iter().any(|d| d.severity == Severity::Error)
}

/// Separator between message and help inside a `de::Error::custom` string.
const HELP_MARK: char = '\u{1f}';

/// Encode a code, message and optional help into one string so that it survives
/// `serde::de::Error::custom`. [`parse_custom_de_error`] reverses it.
pub fn custom_de_error(code: &str, message: &str, help: Option<&str>) -> String {
    match help {
        Some(h) => format!("[{code}] {message}{HELP_MARK}{h}"),
        None => format!("[{code}] {message}"),
    }
}

/// A decoded [`custom_de_error`] string.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CustomDeError {
    pub code: String,
    pub message: String,
    pub help: Option<String>,
}

/// Decode a string produced by [`custom_de_error`]; `None` for any other error text.
pub fn parse_custom_de_error(text: &str) -> Option<CustomDeError> {
    let rest = text.strip_prefix("[ONT-")?;
    let (code_tail, body) = rest.split_once("] ")?;
    let (message, help) = match body.split_once(HELP_MARK) {
        Some((m, h)) => (m, Some(h.to_owned())),
        None => (body, None),
    };
    Some(CustomDeError {
        code: format!("ONT-{code_tail}"),
        message: message.to_owned(),
        help,
    })
}

/// The closest candidate to `input` (case-insensitive Jaro-Winkler >= 0.8).
pub fn did_you_mean<'a>(
    input: &str,
    candidates: impl IntoIterator<Item = &'a str>,
) -> Option<&'a str> {
    let needle = input.to_lowercase();
    candidates
        .into_iter()
        .map(|c| (strsim::jaro_winkler(&needle, &c.to_lowercase()), c))
        .filter(|(score, _)| *score >= 0.8)
        .max_by(|a, b| a.0.total_cmp(&b.0))
        .map(|(_, c)| c)
}

/// Validate diagnostic codes. Codes are never reused once published.
///
/// V21..V27 (Phase 3) are V-level, not lint E-level: an E rule can be turned off or
/// downgraded in `ontoforge.toml`, but scope, row-predicate and destructive-change
/// failures must never be silenced (SCOPE-06, D-07, STORE-02).
pub mod codes {
    /// Online source `OneToOne` foreign key shared by distinct objects; not an offline lint.
    pub const W18: &str = "ONT-W18";
    /// Syntax error, duplicate key, budget exceeded, or non-UTF-8 input.
    pub const V01: &str = "ONT-V01";
    /// Document shape: not a mapping, missing `kind`, or `kind` is not a string.
    pub const V02: &str = "ONT-V02";
    /// Unknown or unsupported `kind` (including rule kinds).
    pub const V03: &str = "ONT-V03";
    /// Unknown field.
    pub const V04: &str = "ONT-V04";
    /// Missing required field.
    pub const V05: &str = "ONT-V05";
    /// Wrong type or value.
    pub const V06: &str = "ONT-V06";
    /// apiName format violation or reserved word.
    pub const V07: &str = "ONT-V07";
    /// Duplicate definition, property, parameter, or accessor.
    pub const V08: &str = "ONT-V08";
    /// Reference to something that does not exist.
    pub const V09: &str = "ONT-V09";
    /// Primary key or title key problem.
    pub const V10: &str = "ONT-V10";
    /// Link type consistency.
    pub const V11: &str = "ONT-V11";
    /// Action type structure.
    pub const V12: &str = "ONT-V12";
    /// CEL expression.
    pub const V13: &str = "ONT-V13";
    /// Manifest and source files.
    pub const V14: &str = "ONT-V14";
    /// Lint configuration.
    pub const V15: &str = "ONT-V15";
    /// Source binding definition, profile selection and fixture references.
    pub const V16: &str = "ONT-V16";
    /// Online binding check: the physical table does not match the binding.
    pub const V17: &str = "ONT-V17";
    /// Duplicate or NULL primary keys found by `--check-pk`.
    pub const V18: &str = "ONT-V18";
    /// The online check could not complete because of the engine (unavailable,
    /// authentication, timeout, protocol or query error).
    pub const V19: &str = "ONT-V19";
    /// Server configuration (`ontoforge-server.toml`).
    pub const V20: &str = "ONT-V20";
    /// Scope document structure and references: a `Role` / `RoleBinding` refers to an
    /// unknown object type, property, action or role; a property allow-list omits
    /// the primary key; empty or duplicate subjects.
    pub const V21: &str = "ONT-V21";
    /// Row predicate (`rowFilter`): outside the allowed CEL subset, type error,
    /// reference other than same-row properties and declared `principal.attrs`, or
    /// a case-insensitive collation column (D-07, D-08).
    pub const V22: &str = "ONT-V22";
    /// Criteria column coverage: a role granted an action cannot see a property
    /// its submission criteria read (SCOPE-06).
    pub const V23: &str = "ONT-V23";
    /// Edit store physical name: two definitions map to the same physical table,
    /// column or index name.
    pub const V24: &str = "ONT-V24";
    /// Destructive definition change found by reload; apply it with
    /// `ontoforge migrate`.
    pub const V25: &str = "ONT-V25";
    /// The edit store or the Trino visibility probe could not complete:
    /// connection, lock timeout, probe timeout, stale definition.
    pub const V26: &str = "ONT-V26";
    /// Import data: unreadable file, unknown column, value that does not convert
    /// to the property type, or an existing object.
    pub const V27: &str = "ONT-V27";
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn phase3_codes() {
        let all = [
            codes::V21,
            codes::V22,
            codes::V23,
            codes::V24,
            codes::V25,
            codes::V26,
            codes::V27,
        ];
        for (offset, code) in all.iter().enumerate() {
            assert_eq!(*code, format!("ONT-V{}", 21 + offset));
        }
    }

    #[test]
    fn custom_error_round_trips() {
        let s = custom_de_error(codes::V07, "bad name", Some("use Flight"));
        let parsed = parse_custom_de_error(&s).unwrap();
        assert_eq!(parsed.code, "ONT-V07");
        assert_eq!(parsed.message, "bad name");
        assert_eq!(parsed.help.as_deref(), Some("use Flight"));
        assert!(parse_custom_de_error("unknown field `x`").is_none());
    }

    #[test]
    fn did_you_mean_picks_closest_and_ignores_far_names() {
        let names = ["apiName", "primaryKey", "properties"];
        assert_eq!(
            did_you_mean("primaryKy", names.iter().copied()),
            Some("primaryKey")
        );
        assert_eq!(did_you_mean("zzzz", names.iter().copied()), None);
    }

    #[test]
    fn offset_to_line_col_takes_byte_offsets_and_counts_char_columns() {
        assert_eq!(offset_to_line_col("ab\ncd", 0), (1, 1));
        assert_eq!(offset_to_line_col("ab\ncd", 4), (2, 2));
        // `é` is two bytes: byte offset 2 is the char after it, in column 2.
        assert_eq!(offset_to_line_col("éa", 2), (1, 2));
        // Mid-char and past-the-end offsets are clamped instead of panicking.
        assert_eq!(offset_to_line_col("éa", 1), (1, 1));
        assert_eq!(offset_to_line_col("ab", 99), (1, 3));
    }

    #[test]
    fn sort_is_by_file_line_column_code() {
        let at = |file: &str, line| SourceLocation {
            file: file.into(),
            line,
            column: 1,
            offset: 0,
            length: 1,
        };
        let mut d = vec![
            Diagnostic::error(codes::V05, "b", &at("b.yaml", 1)),
            Diagnostic::error(codes::V04, "a", &at("a.yaml", 9)),
            Diagnostic::error(codes::V04, "a", &at("a.yaml", 2)),
        ];
        sort_diagnostics(&mut d);
        let order: Vec<_> = d.iter().map(|x| (x.file.as_str(), x.line)).collect();
        assert_eq!(order, [("a.yaml", 2), ("a.yaml", 9), ("b.yaml", 1)]);
    }
}

//! Action type definition (SCHEMA-05): the only way object data changes.
//!
//! Shape per ADR-0012. Validation of references and types lives in
//! `validate::actions`; CEL in `submissionCriteria` is checked by `ontoforge-expr`.

use indexmap::IndexMap;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use super::basetype::BaseType;
use super::names::{ActionTypeName, LinkTypeName, ObjectTypeName, ParameterName, PropertyName};

/// A named, validated change to the object graph.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ActionType {
    /// Unique `camelCase` name; callers and agents invoke the action by it.
    pub api_name: ActionTypeName,
    /// Human-readable name shown in UIs.
    pub display_name: Option<String>,
    /// What this action does.
    pub description: Option<String>,
    /// Inputs, keyed by their camelCase apiName.
    #[serde(default)]
    pub parameters: IndexMap<ParameterName, ParameterDef>,
    /// Edits applied in order; the order is significant and at least one rule is
    /// required. Each rule is written `kind: <ruleKind>` followed by its fields.
    pub rules: Vec<Rule>,
    /// Conditions that must hold before the rules run.
    #[serde(default)]
    pub submission_criteria: Vec<SubmissionCriterion>,
}

/// One input of an action.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ParameterDef {
    /// A base type, or `{ objectReference: <ObjectType> }` for an existing object.
    #[serde(rename = "type")]
    pub param_type: ParamType,
    /// Element type; required when `type` is `array`, not allowed otherwise.
    pub items: Option<BaseType>,
    /// Whether the caller must supply a value.
    #[serde(default)]
    pub required: bool,
    /// Value used when the caller supplies none. Must be a valid literal of the
    /// parameter type; not allowed for object references.
    pub default: Option<serde_json::Value>,
    /// Human-readable name shown in UIs.
    pub display_name: Option<String>,
    /// What this parameter means.
    pub description: Option<String>,
}

/// The type of a parameter: one of the thirteen base types or an object reference.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum ParamType {
    Byte,
    Short,
    Integer,
    Long,
    Float,
    Double,
    Decimal,
    String,
    Boolean,
    Date,
    Timestamp,
    Array,
    Geopoint,
    /// An existing object of this type, written `{ objectReference: Flight }`.
    ObjectReference(ObjectTypeName),
}

impl ParamType {
    /// The base type, or `None` for an object reference.
    pub fn base_type(&self) -> Option<BaseType> {
        Some(match self {
            Self::Byte => BaseType::Byte,
            Self::Short => BaseType::Short,
            Self::Integer => BaseType::Integer,
            Self::Long => BaseType::Long,
            Self::Float => BaseType::Float,
            Self::Double => BaseType::Double,
            Self::Decimal => BaseType::Decimal,
            Self::String => BaseType::String,
            Self::Boolean => BaseType::Boolean,
            Self::Date => BaseType::Date,
            Self::Timestamp => BaseType::Timestamp,
            Self::Array => BaseType::Array,
            Self::Geopoint => BaseType::Geopoint,
            Self::ObjectReference(_) => return None,
        })
    }
}

/// One edit of an action. Rules run in list order.
///
/// In definition files a rule is `{ kind: createObject, .. }`; the loader turns that
/// into this externally tagged form before deserializing.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
#[schemars(tag = "kind")]
pub enum Rule {
    /// Create a new object.
    CreateObject(CreateObjectRule),
    /// Change properties of an existing object passed as a parameter.
    ModifyObject(ModifyObjectRule),
    /// Delete an existing object passed as a parameter.
    DeleteObject(DeleteObjectRule),
    /// Restore the source view by clearing the edit overlay.
    ReleaseObject(ReleaseObjectRule),
    /// Link two existing objects.
    AddLink(LinkRule),
    /// Unlink two existing objects.
    RemoveLink(LinkRule),
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct CreateObjectRule {
    /// Type of the new object.
    pub object_type: ObjectTypeName,
    /// Property values. The primary key and every required property must appear.
    pub properties: IndexMap<PropertyName, ValueSource>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ModifyObjectRule {
    /// Name of an `objectReference` parameter holding the object to change.
    pub object: ParameterName,
    /// Property values to set. The primary key cannot be set.
    pub properties: IndexMap<PropertyName, ValueSource>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct DeleteObjectRule {
    /// Name of an `objectReference` parameter holding the object to delete.
    pub object: ParameterName,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ReleaseObjectRule {
    /// Name of an `objectReference` parameter for a source-backed object.
    pub object: ParameterName,
}

/// Shared by `addLink` and `removeLink`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct LinkRule {
    /// The link type to edit.
    pub link: LinkTypeName,
    /// `objectReference` parameter for the link's `from` object type.
    pub from: ParameterName,
    /// `objectReference` parameter for the link's `to` object type.
    pub to: ParameterName,
}

/// Where a property value comes from, written as a single-key map.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum ValueSource {
    /// The value of a parameter: `{ param: name }`.
    Param(ParameterName),
    /// A literal: `{ static: value }`. `null` is not allowed.
    Static(serde_json::Value),
    /// The calling user's id, for string properties: `{ currentUser: {} }`.
    CurrentUser(Empty),
    /// The time of the call, for timestamp properties: `{ currentTime: {} }`.
    CurrentTime(Empty),
}

impl ValueSource {
    /// The key this source is written under.
    pub fn key(&self) -> &'static str {
        match self {
            Self::Param(_) => "param",
            Self::Static(_) => "static",
            Self::CurrentUser(_) => "currentUser",
            Self::CurrentTime(_) => "currentTime",
        }
    }
}

/// The empty mapping `{}`; no fields are accepted.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Empty {}

/// A condition checked before the rules run.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct SubmissionCriterion {
    /// A CEL expression over `params`, `user` and `objects` that must be true.
    pub condition: String,
    /// Shown to the caller when the condition is false.
    pub failure_message: String,
}

//! Declared type of a principal attribute (D-05).

use serde::{Deserialize, Serialize};

/// The declared type of a principal attribute, set in `ontoforge-server.toml`
/// under `[auth.principal_attrs]`.
///
/// Row predicates (`rowFilter`) are statically type checked against these
/// declarations, so a predicate cannot read `principal.attrs.x` as the wrong
/// type at request time.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AttrType {
    String,
    Integer,
    Boolean,
    StringList,
    IntegerList,
}

impl AttrType {
    /// Whether values of this type are lists.
    #[must_use]
    pub fn is_list(self) -> bool {
        matches!(self, Self::StringList | Self::IntegerList)
    }
}

#[cfg(test)]
mod tests {
    use super::AttrType;

    #[test]
    fn is_list_only_for_list_types() {
        assert!(AttrType::StringList.is_list());
        assert!(AttrType::IntegerList.is_list());
        for t in [AttrType::String, AttrType::Integer, AttrType::Boolean] {
            assert!(!t.is_list());
        }
    }
}

//! The thirteen base types of a property (D-03) and where they may be used.

use chrono::{DateTime, NaiveDate};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum BaseType {
    Byte,
    Short,
    Integer,
    Long,
    Float,
    Double,
    Decimal,
    String,
    Boolean,
    Date,
    Timestamp,
    Array,
    Geopoint,
}

impl BaseType {
    /// The spelling used in definition files.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Byte => "byte",
            Self::Short => "short",
            Self::Integer => "integer",
            Self::Long => "long",
            Self::Float => "float",
            Self::Double => "double",
            Self::Decimal => "decimal",
            Self::String => "string",
            Self::Boolean => "boolean",
            Self::Date => "date",
            Self::Timestamp => "timestamp",
            Self::Array => "array",
            Self::Geopoint => "geopoint",
        }
    }
}

/// How well a base type serves as a primary key.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PkSuitability {
    /// Accepted without comment.
    Valid,
    /// Accepted by `validate`; `lint` warns (E09).
    Discouraged,
    /// Rejected by `validate` (`ONT-V10`).
    Invalid,
}

/// Primary key suitability of `t`. Defined once; `validate` (V10) and lint (E09)
/// both read this table.
pub fn pk_suitability(t: BaseType) -> PkSuitability {
    match t {
        BaseType::String | BaseType::Integer | BaseType::Short => PkSuitability::Valid,
        BaseType::Date
        | BaseType::Timestamp
        | BaseType::Boolean
        | BaseType::Byte
        | BaseType::Long => PkSuitability::Discouraged,
        BaseType::Float
        | BaseType::Double
        | BaseType::Decimal
        | BaseType::Geopoint
        | BaseType::Array => PkSuitability::Invalid,
    }
}

/// Whether a property of type `t` (with element type `items`) can be a title.
/// Every v1 type can; arrays are judged by their element type.
pub fn is_title_suitable(t: BaseType, items: Option<BaseType>) -> bool {
    match (t, items) {
        (BaseType::Array, Some(inner)) => is_title_suitable(inner, None),
        _ => true,
    }
}

/// Whether a value of type `from` can be assigned to a property of type `to` without
/// loss (D-07, WR-04): the same type, or a wider one along `byte ⊂ short ⊂ integer ⊂
/// long` or `float ⊂ double`. Narrowing (`long` into `integer`) is refused.
pub fn widens_to(from: BaseType, to: BaseType) -> bool {
    use BaseType::{Byte, Double, Float, Integer, Long, Short};
    let rank = |t| match t {
        Byte => Some(0),
        Short => Some(1),
        Integer => Some(2),
        Long => Some(3),
        _ => None,
    };
    match (rank(from), rank(to)) {
        (Some(a), Some(b)) => a <= b,
        _ => from == to || (from == Float && to == Double),
    }
}

/// Check that the JSON value `v` is a legal literal of type `t`. `items` is the
/// element type for arrays; without it array elements are not checked. The error
/// is a short English phrase meant to sit inside a diagnostic message.
pub fn check_literal(v: &Value, t: BaseType, items: Option<BaseType>) -> Result<(), String> {
    if v.is_null() {
        return Err("null is not a valid value".to_owned());
    }
    let wrong = |expected: &str| Err(format!("expected {expected}, found {}", describe(v)));
    match t {
        BaseType::Byte => integer_in(v, "byte", i8::MIN.into(), i8::MAX.into()),
        BaseType::Short => integer_in(v, "short", i16::MIN.into(), i16::MAX.into()),
        BaseType::Integer => integer_in(v, "integer", i32::MIN.into(), i32::MAX.into()),
        BaseType::Long => integer_in(v, "long", i64::MIN, i64::MAX),
        BaseType::Float | BaseType::Double => match v {
            Value::Number(_) => Ok(()),
            _ => wrong("a number"),
        },
        BaseType::Decimal => match v {
            Value::Number(_) => Ok(()),
            Value::String(s) if is_decimal(s) => Ok(()),
            Value::String(s) => Err(format!("`{s}` is not a decimal number")),
            _ => wrong("a number or a decimal string"),
        },
        BaseType::String => match v {
            Value::String(_) => Ok(()),
            _ => wrong("a string"),
        },
        BaseType::Boolean => match v {
            Value::Bool(_) => Ok(()),
            _ => wrong("true or false"),
        },
        BaseType::Date => match v {
            Value::String(s) if is_date(s) => Ok(()),
            Value::String(s) => Err(format!("`{s}` is not a date written as YYYY-MM-DD")),
            _ => wrong("a date string"),
        },
        BaseType::Timestamp => match v {
            Value::String(s) if DateTime::parse_from_rfc3339(s).is_ok() => Ok(()),
            Value::String(s) => Err(format!("`{s}` is not an RFC 3339 timestamp")),
            _ => wrong("a timestamp string"),
        },
        BaseType::Geopoint => match v {
            Value::String(s) => geopoint(s),
            _ => wrong("a \"lat,lon\" string"),
        },
        BaseType::Array => match v {
            Value::Array(elements) => {
                let Some(inner) = items else {
                    return Ok(());
                };
                elements.iter().enumerate().try_for_each(|(i, e)| {
                    check_literal(e, inner, None).map_err(|m| format!("element {i}: {m}"))
                })
            }
            _ => wrong("an array"),
        },
    }
}

fn describe(v: &Value) -> &'static str {
    match v {
        Value::Null => "null",
        Value::Bool(_) => "a boolean",
        Value::Number(_) => "a number",
        Value::String(_) => "a string",
        Value::Array(_) => "an array",
        Value::Object(_) => "a mapping",
    }
}

fn integer_in(v: &Value, name: &str, lo: i64, hi: i64) -> Result<(), String> {
    let Value::Number(n) = v else {
        return Err(format!("expected an integer, found {}", describe(v)));
    };
    match n.as_i64() {
        Some(i) if (lo..=hi).contains(&i) => Ok(()),
        Some(_) => Err(format!("{n} is out of range for {name} ({lo} to {hi})")),
        None if n.is_u64() => Err(format!("{n} is out of range for {name} ({lo} to {hi})")),
        None => Err(format!("{n} is not an integer")),
    }
}

fn is_decimal(s: &str) -> bool {
    let unsigned = s.strip_prefix(['+', '-']).unwrap_or(s);
    let (whole, fraction) = unsigned.split_once('.').unwrap_or((unsigned, ""));
    let digits = |part: &str| part.bytes().all(|b| b.is_ascii_digit());
    digits(whole) && digits(fraction) && !(whole.is_empty() && fraction.is_empty())
}

fn is_date(s: &str) -> bool {
    // `%Y` alone would also take signs and long years; ten bytes pins YYYY-MM-DD.
    s.len() == 10 && NaiveDate::parse_from_str(s, "%Y-%m-%d").is_ok()
}

fn geopoint(s: &str) -> Result<(), String> {
    let parsed = s.split_once(',').and_then(|(lat, lon)| {
        let lat = lat.trim().parse::<f64>().ok()?;
        let lon = lon.trim().parse::<f64>().ok()?;
        Some((lat, lon))
    });
    match parsed {
        Some((lat, lon)) if (-90.0..=90.0).contains(&lat) && (-180.0..=180.0).contains(&lon) => {
            Ok(())
        }
        Some(_) => Err(format!(
            "`{s}` is outside latitude -90 to 90 or longitude -180 to 180"
        )),
        None => Err(format!("`{s}` is not a \"lat,lon\" pair")),
    }
}

//! Where an object type's data comes from (D-02) and how it is bound to a table
//! (D-01).
//!
//! `backing` is the definition-layer declaration. The physical binding to a table
//! lives in separate `kind: SourceBinding` documents under `bindings/<profile>/`
//! (ADR-0021), so a definition file never carries a catalog, schema or table name.

use std::collections::BTreeMap;

use indexmap::IndexMap;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use super::Ontology;
use super::names::{LinkTypeName, ObjectTypeName};
use super::object::PropertyDef;

/// The data source an object type or many-to-many link declares.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum Backing {
    /// Objects come from the physical table bound for the selected profile; edits
    /// are layered on top.
    Source,
    /// Objects are created only through actions or imports. No binding is allowed.
    EditOnly,
}

/// Binds one object type or one many-to-many link to a physical table or view.
///
/// The profile is not written in the document: it is the name of the directory
/// the file sits in, `bindings/<profile>/`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct SourceBinding {
    /// What is bound: `{ objectType: Flight }` or `{ linkType: flightCrew }`. Only
    /// `manyToMany` links can be bound.
    pub target: BindingTarget,
    /// The physical table or view the target reads from.
    pub source: SourceRef,
    /// Column mappings that differ from the default. Keys are property apiNames for
    /// an object type, or `from` and `to` for a link. A property that is not listed
    /// is read from the column of the same name (D-03).
    #[serde(default)]
    pub columns: IndexMap<String, ColumnBinding>,
    /// Sample rows that stand in for the table when no Trino is available; used
    /// only by the SQLite stand-in engine.
    pub fixture: Option<FixtureRef>,
}

/// What a [`SourceBinding`] binds. Externally tagged so that error paths survive
/// deserialization (ADR-0003).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum BindingTarget {
    /// An object type, by its `PascalCase` apiName.
    ObjectType(ObjectTypeName),
    /// A many-to-many link type, by its `camelCase` apiName.
    LinkType(LinkTypeName),
}

/// A physical table or view in the data source.
///
/// It is one table or view. To combine several tables, create a view in Trino and
/// bind that (D-04).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct SourceRef {
    /// Trino catalog.
    pub catalog: String,
    /// Schema inside the catalog.
    pub schema: String,
    /// Table or view name.
    pub table: String,
}

/// How one property (or one link end) maps to a column.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ColumnBinding {
    /// Physical column name. Defaults to the property apiName (D-03).
    pub column: Option<String>,
    /// IANA time zone name for a timestamp column that carries no zone, for
    /// example `Europe/Berlin`; write `aware` when the column already has one
    /// (ADR-0021).
    pub timezone: Option<String>,
    /// How string comparison treats case on this column.
    pub collation: Option<Collation>,
}

/// String comparison semantics of a column.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum Collation {
    /// Upper and lower case letters differ.
    CaseSensitive,
    /// Upper and lower case letters compare equal.
    CaseInsensitive,
}

/// Sample rows for the stand-in engine.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct FixtureRef {
    /// Path relative to the directory of the binding file. Only `.csv` and `.json`
    /// files inside the ontology directory are accepted.
    pub file: String,
}

/// All bindings of one profile.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ProfileBindings {
    /// Object type bindings by object type apiName.
    #[serde(default)]
    pub objects: BTreeMap<ObjectTypeName, SourceBinding>,
    /// Many-to-many link bindings by link type apiName.
    #[serde(default)]
    pub links: BTreeMap<LinkTypeName, SourceBinding>,
}

impl SourceBinding {
    /// The apiName of the bound object type or link type.
    pub fn target_name(&self) -> &str {
        match &self.target {
            BindingTarget::ObjectType(name) => name.as_str(),
            BindingTarget::LinkType(name) => name.as_str(),
        }
    }

    /// The physical column for `key`: `columns[key].column` when written, otherwise
    /// `key` itself (D-03).
    pub fn column_for<'a>(&'a self, key: &'a str) -> &'a str {
        self.columns
            .get(key)
            .and_then(|c| c.column.as_deref())
            .unwrap_or(key)
    }

    /// The declared time zone of `key`, if any.
    pub fn timezone_for(&self, key: &str) -> Option<&str> {
        self.columns.get(key).and_then(|c| c.timezone.as_deref())
    }
}

/// One column a binding expects in the physical table.
#[derive(Debug, Clone, Copy)]
pub struct BoundColumn<'a> {
    /// The property apiName, or `from` / `to` for a link binding.
    pub key: &'a str,
    /// The physical column name ([`SourceBinding::column_for`]).
    pub column: &'a str,
    /// Whether `columns[key].column` was written, as opposed to the same-name default.
    pub explicit: bool,
    /// For an object binding the property itself; for a link binding the primary
    /// key property of the object type at that end.
    pub property: &'a PropertyDef,
}

impl Ontology {
    /// The columns `binding` expects in its table, in a fixed order: property
    /// declaration order for an object type, `from` before `to` for a link. Empty
    /// when the target does not exist.
    ///
    /// The only derivation of expected physical column names; the offline fixture
    /// check and the online comparison both call it.
    pub fn bound_columns<'a>(&'a self, binding: &'a SourceBinding) -> Vec<BoundColumn<'a>> {
        let column = |key: &'a str, property: &'a PropertyDef| BoundColumn {
            key,
            column: binding.column_for(key),
            explicit: binding.columns.get(key).is_some_and(|c| c.column.is_some()),
            property,
        };
        match &binding.target {
            BindingTarget::ObjectType(name) => self
                .object_types
                .get(name.as_str())
                .map(|object| {
                    object
                        .properties
                        .iter()
                        .map(|(key, property)| column(key.as_str(), property))
                        .collect()
                })
                .unwrap_or_default(),
            BindingTarget::LinkType(name) => {
                let Some(link) = self.link_types.get(name.as_str()) else {
                    return Vec::new();
                };
                [("from", &link.from), ("to", &link.to)]
                    .into_iter()
                    .filter_map(|(key, end)| {
                        let object = self.object_types.get(end.object_type.as_str())?;
                        let property = object.properties.get(object.primary_key.as_str())?;
                        Some(column(key, property))
                    })
                    .collect()
            }
        }
    }
}

//! Link type definition (SCHEMA-04): a typed relationship between two object types.

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use super::binding::Backing;
use super::names::{LinkEndName, LinkTypeName, ObjectTypeName, PropertyName};

/// How many objects each side of a link may relate to.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum Cardinality {
    /// One `from` object relates to at most one `to` object, and the other way round.
    /// The `to` end carries the foreign key.
    OneToOne,
    /// One `from` object relates to many `to` objects. The `to` end carries the
    /// foreign key.
    OneToMany,
    /// Many objects on each side. The system manages a join table, so no foreign
    /// key is written.
    ManyToMany,
}

/// A relationship between two object types, for example `Airport` to `Flight`.
///
/// Both ends are written in the link type. An end's `apiName` is the accessor on
/// that end's own `objectType` that reaches the other end. This is the reverse of
/// how Foundry words it, where the name written on one end lives on the opposite
/// object type.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct LinkType {
    /// Unique `camelCase` name; actions refer to the link by it.
    pub api_name: LinkTypeName,
    /// Human-readable name shown in UIs.
    pub display_name: Option<String>,
    /// What this relationship means.
    pub description: Option<String>,
    /// `oneToOne`, `oneToMany` or `manyToMany`.
    pub cardinality: Cardinality,
    /// Where the link rows come from. Required for `manyToMany`; not allowed for
    /// `oneToOne` and `oneToMany`, which follow the foreign key on the `to` end.
    pub backing: Option<Backing>,
    /// The first end. In `oneToMany` this is the "one" side.
    pub from: LinkEnd,
    /// The second end. In `oneToMany` this is the "many" side and holds the
    /// foreign key.
    pub to: LinkEnd,
}

/// One end of a link type.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct LinkEnd {
    /// The object type at this end.
    pub object_type: ObjectTypeName,
    /// The accessor on this end's `objectType` that reaches the other end. It must
    /// be unique among that object type's accessors and must not equal one of its
    /// properties.
    pub api_name: LinkEndName,
    /// Human-readable name of the accessor shown in UIs.
    pub display_name: Option<String>,
    /// What the accessor returns.
    pub description: Option<String>,
    /// Property holding the reference. Only on the `to` end of `oneToOne` and
    /// `oneToMany`; it must be a property of the `to` object type whose type equals
    /// the `from` object type's primary key type. Never written for `manyToMany`.
    pub foreign_key: Option<PropertyName>,
}

