//! Validated apiName newtypes (D-04).
//!
//! The check runs inside `Deserialize`, so a bad name surfaces as a located
//! `ONT-V07` through the normal deserialization error path.

use std::borrow::{Borrow, Cow};
use std::fmt;

use heck::{ToLowerCamelCase, ToUpperCamelCase};
use schemars::{JsonSchema, Schema, SchemaGenerator, json_schema};
use serde::{Serialize, Serializer};

use crate::diag::{codes, custom_de_error};

/// Words no apiName may equal, compared case-insensitively.
pub const RESERVED_API_NAMES: [&str; 9] = [
    "ontology",
    "object",
    "property",
    "link",
    "relation",
    "rid",
    "primaryKey",
    "typeId",
    "ontologyObject",
];

/// CEL keywords and reserved identifiers (case-sensitive). Parameter and property
/// names appear in conditions as `params.<name>` and `objects.<param>.<name>`, where
/// these do not parse, so those names may not be one (WR-03, ONT-V07).
pub const CEL_RESERVED_WORDS: [&str; 21] = [
    "as",
    "break",
    "const",
    "continue",
    "else",
    "false",
    "for",
    "function",
    "if",
    "import",
    "in",
    "let",
    "loop",
    "namespace",
    "null",
    "package",
    "return",
    "true",
    "var",
    "void",
    "while",
];

const MAX_LEN: usize = 100;

#[derive(Clone, Copy)]
enum Initial {
    Upper,
    Lower,
}

fn well_formed(raw: &str, initial: Initial) -> bool {
    let first_ok = raw.chars().next().is_some_and(|c| match initial {
        Initial::Upper => c.is_ascii_uppercase(),
        Initial::Lower => c.is_ascii_lowercase(),
    });
    first_ok && raw.len() <= MAX_LEN && raw.chars().all(|c| c.is_ascii_alphanumeric())
}

fn reserved(raw: &str) -> Option<&'static str> {
    RESERVED_API_NAMES
        .iter()
        .copied()
        .find(|r| r.eq_ignore_ascii_case(raw))
}

/// Rewrite `raw` into the nearest legal spelling, or `None` when none exists.
fn canonical(raw: &str, initial: Initial) -> Option<String> {
    let out = match initial {
        Initial::Upper => raw.to_upper_camel_case(),
        Initial::Lower => raw.to_lower_camel_case(),
    };
    (well_formed(&out, initial) && reserved(&out).is_none() && out != raw).then_some(out)
}

fn check(
    raw: &str,
    what: &str,
    initial: Initial,
    pattern: &str,
    keywords: &[&str],
) -> Result<(), String> {
    if !well_formed(raw, initial) {
        let help = canonical(raw, initial).map(|c| format!("write it as `{c}`"));
        return Err(custom_de_error(
            codes::V07,
            &format!("invalid {what} apiName `{raw}`: must match {pattern}"),
            help.as_deref(),
        ));
    }
    if let Some(word) = reserved(raw) {
        return Err(custom_de_error(
            codes::V07,
            &format!("`{raw}` is a reserved word (`{word}`) and cannot be used as {what} apiName"),
            Some("choose a different name"),
        ));
    }
    if keywords.contains(&raw) {
        return Err(custom_de_error(
            codes::V07,
            &format!(
                "`{raw}` is a CEL keyword and cannot be used as {what} apiName: submission criteria could not refer to it"
            ),
            Some(&format!("choose a different name, such as `{raw}Value`")),
        ));
    }
    Ok(())
}

macro_rules! api_name {
    ($(#[$meta:meta])* $name:ident, $initial:expr, $what:literal, $pattern:literal) => {
        api_name!($(#[$meta])* $name, $initial, $what, $pattern, &[]);
    };
    ($(#[$meta:meta])* $name:ident, $initial:expr, $what:literal, $pattern:literal, $keywords:expr) => {
        $(#[$meta])*
        #[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, serde::Deserialize)]
        #[serde(try_from = "String")]
        pub struct $name(String);

        impl $name {
            pub fn as_str(&self) -> &str {
                &self.0
            }
        }

        impl TryFrom<String> for $name {
            type Error = String;

            fn try_from(value: String) -> Result<Self, String> {
                check(&value, $what, $initial, $pattern, $keywords)?;
                Ok(Self(value))
            }
        }

        impl Serialize for $name {
            fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
                s.serialize_str(&self.0)
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                f.write_str(&self.0)
            }
        }

        impl Borrow<str> for $name {
            fn borrow(&self) -> &str {
                &self.0
            }
        }

        impl JsonSchema for $name {
            fn schema_name() -> Cow<'static, str> {
                Cow::Borrowed(stringify!($name))
            }

            fn json_schema(_generator: &mut SchemaGenerator) -> Schema {
                json_schema!({ "type": "string", "pattern": $pattern })
            }
        }
    };
}

api_name!(
    /// Ontology apiName, `camelCase`.
    OntologyName, Initial::Lower, "ontology", "^[a-z][A-Za-z0-9]{0,99}$"
);
api_name!(
    /// Object type apiName, `PascalCase`.
    ObjectTypeName, Initial::Upper, "object type", "^[A-Z][A-Za-z0-9]{0,99}$"
);
api_name!(
    /// Property apiName, `camelCase`, not a CEL keyword.
    PropertyName, Initial::Lower, "property", "^[a-z][A-Za-z0-9]{0,99}$", &CEL_RESERVED_WORDS
);
api_name!(
    /// Link type apiName, `camelCase`.
    LinkTypeName, Initial::Lower, "link type", "^[a-z][A-Za-z0-9]{0,99}$"
);
api_name!(
    /// Link end apiName (accessor on that end's object type), `camelCase`.
    LinkEndName, Initial::Lower, "link end", "^[a-z][A-Za-z0-9]{0,99}$"
);
api_name!(
    /// Action type apiName, `camelCase`.
    ActionTypeName, Initial::Lower, "action type", "^[a-z][A-Za-z0-9]{0,99}$"
);
api_name!(
    /// Role apiName (scope documents, D-01), `camelCase`.
    RoleName, Initial::Lower, "role", "^[a-z][A-Za-z0-9]{0,99}$"
);
api_name!(
    /// Action parameter apiName, `camelCase`, not a CEL keyword.
    ParameterName, Initial::Lower, "parameter", "^[a-z][A-Za-z0-9]{0,99}$", &CEL_RESERVED_WORDS
);

/// Pattern a [`ProfileName`] must match.
const PROFILE_PATTERN: &str = "^[a-z][a-z0-9_-]{0,31}$";

/// Name of a deployment profile (D-05), for example `dev` or `prod-eu`.
///
/// Source bindings live under `bindings/<profile>/` and the server configuration
/// keys `[profiles.<name>]` by the same name, so both use this one type. A profile
/// name is only ever a map key: it must never be joined into a file system path.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, serde::Deserialize)]
#[serde(try_from = "String")]
pub struct ProfileName(String);

impl ProfileName {
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl TryFrom<String> for ProfileName {
    type Error = String;

    fn try_from(value: String) -> Result<Self, String> {
        let mut chars = value.chars();
        let well_formed = chars.next().is_some_and(|c| c.is_ascii_lowercase())
            && value.len() <= 32
            && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_' || c == '-');
        if !well_formed {
            return Err(custom_de_error(
                codes::V16,
                &format!("invalid profile name `{value}`: must match {PROFILE_PATTERN}"),
                Some(
                    "profile names are lowercase letters, digits, `_` and `-`, starting with a letter, at most 32 characters",
                ),
            ));
        }
        Ok(Self(value))
    }
}

impl Serialize for ProfileName {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&self.0)
    }
}

impl fmt::Display for ProfileName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl Borrow<str> for ProfileName {
    fn borrow(&self) -> &str {
        &self.0
    }
}

impl JsonSchema for ProfileName {
    fn schema_name() -> Cow<'static, str> {
        Cow::Borrowed("ProfileName")
    }

    fn json_schema(_generator: &mut SchemaGenerator) -> Schema {
        json_schema!({ "type": "string", "pattern": PROFILE_PATTERN })
    }
}

#[cfg(test)]
mod tests {
