            Some("write it as `httpServer`")
        );
    }

    #[test]
    fn non_ascii_names_get_no_misleading_suggestion() {
        assert_eq!(help_of::<PropertyName>("café_name"), None);
        assert_eq!(help_of::<ObjectTypeName>("Café"), None);
    }

    #[test]
    fn unfixable_names_get_no_help() {
        assert!(
