        );
    }
}

//! Object type definition (SCHEMA-02) and its properties (SCHEMA-03).

use indexmap::IndexMap;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use super::basetype::BaseType;
use super::binding::Backing;
use super::names::{ObjectTypeName, PropertyName};

/// A kind of object, for example `Flight`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ObjectType {
    /// Unique `PascalCase` name used in code, APIs and references.
    pub api_name: ObjectTypeName,
    /// Human-readable name shown in UIs.
    pub display_name: Option<String>,
    /// What this object type represents.
    pub description: Option<String>,
    /// Alternative names, used for search and by agents.
    #[serde(default)]
    pub aliases: Vec<String>,
    /// Hide the object type from default listings.
    #[serde(default)]
    pub hidden: bool,
    /// Where the objects come from. Required: `source` needs a source binding in
    /// the selected profile, `editOnly` must have none (D-02).
    pub backing: Backing,
    /// Property that uniquely identifies an object. It must be declared in
    /// `properties`, set `required: true`, and be a string, integer or short
    /// (other types are discouraged or invalid).
    pub primary_key: PropertyName,
    /// Property used as the object's title; defaults to `primaryKey`.
    pub title_key: Option<PropertyName>,
    /// Properties keyed by their camelCase apiName.
    pub properties: IndexMap<PropertyName, PropertyDef>,
}

impl ObjectType {
    /// The title property: `titleKey` when set, otherwise the primary key.
    pub fn effective_title_key(&self) -> &PropertyName {
        self.title_key.as_ref().unwrap_or(&self.primary_key)
    }
}

/// One property of an object type.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct PropertyDef {
    /// Base type of the property value.
    #[serde(rename = "type")]
    pub base_type: BaseType,
    /// Whether every object must have a value.
    #[serde(default)]
    pub required: bool,
    /// Human-readable name shown in UIs.
    pub display_name: Option<String>,
    /// What this property holds.
    pub description: Option<String>,
    /// Element type; required when `type` is `array`, not allowed otherwise.
    pub items: Option<BaseType>,
    /// Total number of digits of a `decimal` (or of an `array` of `decimal`).
    /// Defaults to 38 (ADR-0015, ADR-0021).
    pub precision: Option<u32>,
    /// Number of digits after the decimal point of a `decimal` (or of an `array`
    /// of `decimal`). Defaults to 10 (ADR-0015, ADR-0021).
    pub scale: Option<u32>,
    /// Create an index on this property's edit store column (ADR-0016). Defaults
    /// to false. The primary key column always has an index, so it needs no
    /// declaration.
    #[serde(default)]
    pub indexed: bool,
}

/// Precision of a `decimal` that does not write `precision`.
pub const DEFAULT_DECIMAL_PRECISION: u32 = 38;

/// Scale of a `decimal` that does not write `scale`.
pub const DEFAULT_DECIMAL_SCALE: u32 = 10;

impl PropertyDef {
    /// `(precision, scale)` with each missing value replaced by its own default.
    ///
    /// The only definition of the decimal defaults; lint, the engine and the binding
    /// comparison all call it.
    pub fn effective_decimal(&self) -> (u32, u32) {
        (
            self.precision.unwrap_or(DEFAULT_DECIMAL_PRECISION),
            self.scale.unwrap_or(DEFAULT_DECIMAL_SCALE),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn decimal(precision: Option<u32>, scale: Option<u32>) -> PropertyDef {
        PropertyDef {
            base_type: BaseType::Decimal,
            required: false,
            display_name: None,
            description: None,
            items: None,
            precision,
            scale,
            indexed: false,
        }
    }

    #[test]
    fn effective_decimal_defaults() {
        assert_eq!(decimal(None, None).effective_decimal(), (38, 10));
        assert_eq!(decimal(Some(12), None).effective_decimal(), (12, 10));
        assert_eq!(decimal(None, Some(2)).effective_decimal(), (38, 2));
        assert_eq!(decimal(Some(12), Some(2)).effective_decimal(), (12, 2));
        assert_eq!((DEFAULT_DECIMAL_PRECISION, DEFAULT_DECIMAL_SCALE), (38, 10));
    }
}

//! Scope documents: who may see and do what (roles-as-code, D-01).
//!
//! A scope directory holds `kind: Role` and `kind: RoleBinding` documents, kept apart
//! from the ontology definition and its `SourceBinding` files. A `Role` lists grants
//! (ADR-0018, ADR-0019); a `RoleBinding` attaches a role to users and groups. Group
//! membership is never stored: it comes from the token's `groups` claim (D-02), and a
//! user is identified by its principal id `"<iss>|<sub>"` (D-04).
//!
//! These types only describe the document shape. Whether a named object type,
//! property or action exists is checked against the ontology elsewhere.

use std::collections::BTreeMap;

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use super::names::{ActionTypeName, ObjectTypeName, PropertyName, RoleName};

/// What one role may do.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct Role {
    /// Role name, `camelCase`; a `RoleBinding` refers to it.
    pub api_name: RoleName,
    pub display_name: Option<String>,
    pub description: Option<String>,
    /// Per object type: the readable properties and an optional row filter.
    #[serde(default)]
    pub object_types: BTreeMap<ObjectTypeName, TypeGrant>,
    /// Action types the role may submit.
    #[serde(default)]
    pub actions: Vec<ActionTypeName>,
    /// SQL tiers beyond the implicit L0 (ontology-bound queries).
    #[serde(default)]
    pub sql_levels: Vec<SqlLevel>,
    /// Trino catalogs and schemas the role may query directly (L2).
    #[serde(default)]
    pub l2: L2Grant,
    /// MCP toolsets the role may use (ADR-0019).
    #[serde(default)]
    pub toolsets: Vec<Toolset>,
}

/// Access to one object type: which columns, and which rows.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct TypeGrant {
    /// Property allow-list: the only properties of this type the role can read.
    pub properties: Vec<PropertyName>,
    /// CEL over the object's own properties and `principal.attrs`; absent means all
    /// rows are visible.
    pub row_filter: Option<String>,
}

/// A SQL tier a role may use besides the implicit L0.
#[derive(
    Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, JsonSchema,
)]
#[serde(rename_all = "camelCase")]
pub enum SqlLevel {
    /// Raw SQL over the ontology tables.
    Raw,
    /// Administrative SQL.
    Admin,
}

/// Trino namespaces a role may query directly.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct L2Grant {
    /// Whole catalogs.
    #[serde(default)]
    pub catalogs: Vec<String>,
    /// `catalog.schema` pairs.
    #[serde(default)]
    pub schemas: Vec<String>,
}

/// A group of MCP tools (ADR-0019).
#[derive(
    Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, JsonSchema,
)]
#[serde(rename_all = "camelCase")]
pub enum Toolset {
    Core,
    Full,
    #[serde(rename = "sql:raw")]
    SqlRaw,
}

/// Attaches one role to its subjects.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct RoleBinding {
    pub role: RoleName,
    pub subjects: Vec<Subject>,
}

/// Who a role is granted to. Externally tagged so that error paths survive
/// deserialization (ADR-0003).
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum Subject {
    /// A principal id, `"<iss>|<sub>"` (D-04).
    User(String),
    /// A group name taken from the token's `groups` claim (D-02). With several
    /// issuers, `"<iss>|<group>"`.
    Group(String),
}

/// One scope document.
///
/// Like `Definition`, the loader rewrites `{ kind: X, .. }` to `{ X: { .. } }` before
/// deserializing; the `schemars` attribute only shapes the exported JSON Schema.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[schemars(tag = "kind")]
pub enum ScopeDefinition {
    Role(Role),
    RoleBinding(RoleBinding),
}

/// All roles and bindings of a scope directory, each keyed by role name.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ScopeSet {
    pub roles: BTreeMap<RoleName, Role>,
    /// At most one binding per role.
    pub bindings: BTreeMap<RoleName, RoleBinding>,
}

