//! Source binding rules ONT-E13 to ONT-E16 and ONT-W17 (BIND-02, D-03). They check
//! the type contract between an ontology and its bindings without any connection to
//! a data source; what only the data source knows is `validate --online`.

use super::LintRule;
use crate::ir::{
    BaseType, BindingTarget, Ontology, ProfileName, PropertyDef, SourceBinding, binding_def_name,
};
use crate::loader::sourcemap::{DefKey, DefKind};

mod e13;
mod e14;
mod e15;
mod e16;
mod w17;

pub(super) fn rules() -> Vec<&'static dyn LintRule> {
    vec![&e13::RULE, &e14::RULE, &e15::RULE, &e16::RULE, &w17::RULE]
}

/// Every binding of every profile, objects before links, profiles in name order.
fn all_bindings(ontology: &Ontology) -> impl Iterator<Item = (&ProfileName, &SourceBinding)> {
    ontology.bindings.iter().flat_map(|(profile, bound)| {
        bound
            .objects
            .values()
            .chain(bound.links.values())
            .map(move |binding| (profile, binding))
    })
}

/// The definition key a binding document is registered under in the `SourceMap`.
fn binding_def(profile: &ProfileName, binding: &SourceBinding) -> DefKey {
    DefKey {
        kind: DefKind::SourceBinding,
        api_name: binding_def_name(profile, binding.target_name()),
    }
}

/// The type a column holds per value: the element type of an array, otherwise the
/// type itself.
fn element_type(property: &PropertyDef) -> BaseType {
    match (property.base_type, property.items) {
        (BaseType::Array, Some(items)) => items,
        (base, _) => base,
    }
}

/// Names what a column belongs to in a message: a property of an object type, or an
/// end of a link. `key` is a [`crate::ir::BoundColumn::key`].
fn describe(binding: &SourceBinding, key: &str) -> String {
    match &binding.target {
        BindingTarget::ObjectType(name) => format!("property `{key}` of `{name}`"),
        BindingTarget::LinkType(name) => format!("`{key}` end of `{name}`"),
    }
}

//! ONT-W17: a bound column is missing from the binding's fixture (D-03).
//!
//! The offline part of "a property has no column in the bound table": a binding that
//! names a fixture is compared with the header the loader recorded for it. Columns
//! that exist only in the real table are checked by `validate --online` (ONT-V17).
//! A fixture whose header cannot be read is reported as well, so a broken fixture
//! never makes the lint look clean (E20).

use std::collections::HashSet;

use super::{all_bindings, binding_def};
use crate::lint::{Finding, Level, LintCx, LintRule};
use crate::loader::sourcemap::{Part, Seg};

pub(super) struct W17;

pub(super) static RULE: W17 = W17;

impl LintRule for W17 {
    fn id(&self) -> &'static str {
        "ONT-W17"
    }

    fn default_level(&self) -> Level {
        Level::Warn
    }

    fn check(&self, cx: &LintCx<'_>, out: &mut Vec<Finding>) {
        for (profile, binding) in all_bindings(cx.ontology) {
            let Some(fixture) = &binding.fixture else {
                continue;
            };
            let def = binding_def(profile, binding);
            let Some(header) = cx.sources.fixture_columns(&def.api_name) else {
                continue;
            };
            let finding = |path: &[&str], message: String, help: String| Finding {
                def: def.clone(),
                path: path.iter().map(|k| Seg::Key((*k).to_owned())).collect(),
                part: Part::Value,
                message,
                help: Some(help),
                severity: None,
            };
            let header = match header {
                Ok(header) => header,
                Err(reason) => {
                    out.push(finding(
                        &["fixture", "file"],
                        format!(
                            "cannot read the header of fixture `{}`: {reason}; bound columns cannot be checked offline",
                            fixture.file
                        ),
                        "fix the fixture, or run `ontoforge validate --online` to check the binding"
                            .to_owned(),
                    ));
                    continue;
                }
            };
            // Column names compare without regard to case, like the engine's tables.
            let present: HashSet<String> = header.iter().map(|c| c.to_lowercase()).collect();
            for column in cx.ontology.bound_columns(binding) {
                if present.contains(&column.column.to_lowercase()) {
                    continue;
                }
                let path: &[&str] = if column.explicit {
                    &["columns", column.key, "column"]
                } else {
                    &["fixture", "file"]
                };
                out.push(finding(
                    path,
                    format!(
                        "fixture `{}` has no column `{}` for `{}`",
                        fixture.file, column.column, column.key
                    ),
                    "add the column to the fixture, or map the property with `columns.<key>.column`"
                        .to_owned(),
                ));
            }
        }
    }
}

