//! Structure rules ONT-W06 to ONT-W11. Plan 01-11 registers them here, so plans
//! 01-10 and 01-11 never edit `lint/mod.rs` at the same time.

use super::Finding;
use super::LintRule;
use crate::ir::ObjectType;
use crate::loader::sourcemap::{DefKey, DefKind, Part, Seg};

mod w06;
mod w07;
mod w08;
mod w09;
mod w10;
mod w11;

pub(super) fn rules() -> Vec<&'static dyn LintRule> {
    vec![
        &w06::RULE,
        &w07::RULE,
        &w08::RULE,
        &w09::RULE,
        &w10::RULE,
        &w11::RULE,
    ]
}

/// Appended to every structure help text: these rules are heuristics, so the way out
/// is part of the message.
fn off_hint(rule_id: &str) -> String {
    format!("if this is intentional, set \"{rule_id}\" = \"off\" under [lint] in ontoforge.toml")
}

/// A finding on the `apiName` value of `object`.
fn type_finding(object: &ObjectType, message: String, help: String) -> Finding {
    Finding {
        def: DefKey {
            kind: DefKind::ObjectType,
            api_name: object.api_name.to_string(),
        },
        path: vec![Seg::Key("apiName".to_owned())],
        part: Part::Value,
        message,
        help: Some(help),
        severity: None,
    }
}

/// Fixture helpers shared by the rule tests.
#[cfg(test)]
pub(super) mod testing {
    use crate::diag::Diagnostic;
    use crate::lint::lint_rule_on;

    const MANIFEST: &str = "apiName: demo\n";

    /// One object type document. `pk` is added as a required string property, then
    /// `props` as `(name, base type)` pairs.
    pub fn object(name: &str, pk: &str, props: &[(&str, &str)]) -> String {
        let mut lines = vec![
            "kind: ObjectType".to_owned(),
            format!("apiName: {name}"),
            format!("primaryKey: {pk}"),
            "properties:".to_owned(),
            format!("  {pk}: {{ type: string, required: true }}"),
        ];
        lines.extend(
            props
                .iter()
                .map(|(prop, ty)| format!("  {prop}: {{ type: {ty} }}")),
        );
        lines.push("backing: editOnly".to_owned());
        lines.join("\n") + "\n"
    }

    /// Join documents into one multi-document file.
    pub fn join(docs: &[String]) -> String {
        docs.join("---\n")
    }

    pub fn run(rule_id: &str, text: &str) -> Vec<Diagnostic> {
        run_with(rule_id, text, None)
    }

    pub fn run_with(rule_id: &str, text: &str, config: Option<&str>) -> Vec<Diagnostic> {
        lint_rule_on(
            rule_id,
            &[("ontology.yaml", MANIFEST), ("defs.yaml", text)],
            config,
        )
    }

    /// [`run`] on another thread, failing the test when it takes longer than
    /// `seconds`. A run that never ends is left behind; the test process exits
    /// without waiting for it.
    pub fn run_within(seconds: u64, rule_id: &'static str, text: String) -> Vec<Diagnostic> {
        let (tx, rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let _ = tx.send(run(rule_id, &text));
        });
        rx.recv_timeout(std::time::Duration::from_secs(seconds))
            .unwrap_or_else(|e| panic!("{rule_id} did not finish within {seconds} s: {e}"))
    }

    /// The source text each diagnostic points at, in report order.
    pub fn flagged<'a>(text: &'a str, found: &[Diagnostic]) -> Vec<&'a str> {
        found
            .iter()
            .map(|d| &text[d.span.offset..d.span.offset + d.span.length])
            .collect()
    }
}

//! ONT-W06: God Object (D-13, static part only).
//!
//! An object type is reported when it has more than `max_properties` properties
//! (default 60), or when it has a `string` discriminator property (last word `type`
//! or `subtype`, such as `accountType`) and more than half of `max_properties`
//! properties: a type that switches on a discriminator usually hides several types.
//!
//! The null-rate branch of the original rule needs stored data, so it is Deferred
//! until the storage phase.

use super::super::words::split_camel;
use super::super::{Finding, Level, LintCx, LintRule, OptionKind};
use super::{off_hint, type_finding};
use crate::ir::BaseType;

const DEFAULT_MAX_PROPERTIES: usize = 60;

pub(super) struct W06;

pub(super) static RULE: W06 = W06;

impl LintRule for W06 {
    fn id(&self) -> &'static str {
        "ONT-W06"
    }

    fn default_level(&self) -> Level {
        Level::Warn
    }

    fn option_keys(&self) -> &'static [(&'static str, OptionKind)] {
        &[("max_properties", OptionKind::Count)]
    }

    fn check(&self, cx: &LintCx<'_>, out: &mut Vec<Finding>) {
        let max = cx.option_usize("max_properties", DEFAULT_MAX_PROPERTIES);
        for object in cx.ontology.object_types.values() {
            let count = object.properties.len();
            if count > max {
                out.push(type_finding(
                    object,
                    format!(
                        "object type `{}` has {count} properties, more than the limit of {max}",
                        object.api_name
                    ),
                    format!(
                        "split it into several object types; {}",
                        off_hint(self.id())
                    ),
                ));
            } else if count > max / 2 {
                let discriminator = object.properties.iter().find(|(name, def)| {
                    def.base_type == BaseType::String
                        && split_camel(name.as_str())
                            .last()
                            .is_some_and(|w| w == "type" || w == "subtype")
                });
                if let Some((name, _)) = discriminator {
                    out.push(type_finding(
                        object,
                        format!(
                            "object type `{}` has {count} properties and the discriminator `{name}`",
                            object.api_name
                        ),
                        format!(
                            "one object type per `{name}` value, or an interface for the shared part, is easier to maintain; {}",
                            off_hint(self.id())
                        ),
                    ));
                }
            }
        }
    }
}

