                let extra = [
                    format!("extra{}", i % 7),
                    format!("more{}", i % 11),
                    format!("tag{}", i % 13),
                ];
                let mut props: Vec<(&str, &str)> = AUDIT.to_vec();
                props.extend(extra.iter().map(|p| (p.as_str(), "string")));
