            create_flight("setFlight"),
        ]);
        let found = run("ONT-W09", &text);
        assert!(found.is_empty(), "{found:#?}");
        insta::assert_json_snapshot!("clean", found);
    }

    #[test]
    fn max_actions_per_type_option_applies() {
