        assert_eq!(profile_dir("bindings/dev/sub/x.yaml"), Some("dev"));
        assert_eq!(profile_dir("bindings/Prod/x.yaml"), Some("Prod"));
        assert_eq!(profile_dir("bindings/flight.yaml"), None);
        assert_eq!(profile_dir("defs/bindings/dev/x.yaml"), None);
        assert_eq!(profile_dir("objects.yaml"), None);
    }

    #[test]
    fn only_binding_fixture_directories_are_excluded() {
        assert!(!is_candidate("bindings/dev/fixtures/rows.json"));
        assert!(!is_candidate("bindings/dev/fixtures/deep/rows.json"));
        assert!(is_candidate("bindings/dev/flight.yaml"));
        assert!(is_candidate("fixtures/objects.yaml"));
        assert!(is_candidate("defs/fixtures/x.yaml"));
        assert!(is_candidate("bindings/fixtures/x.yaml"));
    }

    #[test]
    fn walk_lists_nested_files_and_prunes_dirs() {
        let dir = tempfile::tempdir().unwrap();
        for f in ["b.yaml", "x/a.json", ".git/c.yaml", "target/d.yaml"] {
            let p = dir.path().join(f);
            std::fs::create_dir_all(p.parent().unwrap()).unwrap();
            std::fs::write(p, "").unwrap();
        }
        let root = Utf8Path::from_path(dir.path()).unwrap();
        let (mut files, diags) = walk(root);
        files.sort();
        assert!(diags.is_empty());
        assert_eq!(files, ["b.yaml", "x/a.json"]);
    }
}

//! `kind` dispatch and deserialization-error mapping.
//!
//! A document `{ kind: X, .. }` is rewritten to the externally tagged `{ X: { .. } }`
//! before `serde_path_to_error` deserializes it; internally tagged enums lose the
//! error path. Errors are then turned into located `ONT-V` diagnostics.

use serde::de::DeserializeOwned;
use serde_json::Value;
use serde_path_to_error::{Path, Segment};

use super::parse::{Kind, Node};
use super::sourcemap::{FileId, Part, Seg, SourceMap, walk};
use crate::diag::{Diagnostic, SourceLocation, codes, did_you_mean, parse_custom_de_error};
use crate::ir::{Definition, Manifest, ScopeDefinition};

/// Kinds a definition document may declare.
const KINDS: [&str; 4] = ["ObjectType", "LinkType", "ActionType", "SourceBinding"];
/// Kinds whose deserialization exists in this build.
const IMPLEMENTED_KINDS: [&str; 4] = ["ObjectType", "LinkType", "ActionType", "SourceBinding"];
/// Rule kinds an action may use; `function` is recognised only to reject it.
const RULE_KINDS: [&str; 6] = [
    "createObject",
    "modifyObject",
    "deleteObject",
    "releaseObject",
    "addLink",
    "removeLink",
];
/// Kinds a scope document may declare (D-01).
const SCOPE_KINDS: [&str; 2] = ["Role", "RoleBinding"];
/// Kinds reserved for later versions.
const RESERVED_KINDS: [&str; 3] = ["Interface", "ValueType", "SharedProperty"];

/// The family of documents a directory holds. An ontology directory takes definition
/// documents and a scope directory takes `Role` / `RoleBinding`; a kind of the other
/// family is reported with where it belongs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DocSet {
    Ontology,
    Scope,
}

impl DocSet {
    fn kinds(self) -> &'static [&'static str] {
        match self {
            Self::Ontology => &KINDS,
            Self::Scope => &SCOPE_KINDS,
        }
    }

    /// Kinds this family deserializes in this build.
    fn implemented(self) -> &'static [&'static str] {
        match self {
            Self::Ontology => &IMPLEMENTED_KINDS,
            Self::Scope => &SCOPE_KINDS,
        }
    }

    /// The error for a kind that belongs to the other family, if `kind` is one.
    fn misplaced(self, kind: &str, at: &SourceLocation) -> Option<Diagnostic> {
        let (other, message, help) = match self {
            Self::Ontology => (
                &SCOPE_KINDS[..],
                format!("kind `{kind}` belongs in a scope directory"),
                "move it to a scope directory (the directory passed to `ontoforge scope plan`)",
            ),
            Self::Scope => (
                &KINDS[..],
                format!("kind `{kind}` belongs in the ontology directory"),
                "move it to the ontology directory",
            ),
        };
        other
            .contains(&kind)
            .then(|| Diagnostic::error(codes::V03, message, at).with_help(help))
    }
}

/// What the dispatcher needs to turn a node path into a source location.
pub struct Ctx<'a> {
    pub file: FileId,
    pub sources: &'a SourceMap,
}

impl Ctx<'_> {
    fn at(&self, root: &Node, path: &[Seg], part: Part) -> SourceLocation {
        self.sources.locate_in(self.file, root, path, part)
    }
}

fn ticked(items: &[&str]) -> String {
    items
        .iter()
        .map(|i| format!("`{i}`"))
        .collect::<Vec<_>>()
        .join(", ")
}

/// Parse one definition document into its IR.
pub fn dispatch(doc: &Node, cx: &Ctx) -> Result<Definition, Diagnostic> {
    deserialize_document(doc, cx, DocSet::Ontology)
}

/// Parse one scope document (`Role` or `RoleBinding`) into its IR.
pub fn dispatch_scope(doc: &Node, cx: &Ctx) -> Result<ScopeDefinition, Diagnostic> {
    deserialize_document(doc, cx, DocSet::Scope)
}

fn deserialize_document<T: DeserializeOwned>(
    doc: &Node,
    cx: &Ctx,
    set: DocSet,
) -> Result<T, Diagnostic> {
    let kinds = set.kinds();
    let root = |p: &[Seg]| cx.at(doc, p, Part::Value);
    if !matches!(doc.kind, Kind::Map(_)) {
        return Err(Diagnostic::error(
            codes::V02,
            "a definition document must be a mapping",
            &root(&[]),
        ));
    }
    let Some((_, kind_node)) = doc.get("kind") else {
        return Err(
            Diagnostic::error(codes::V02, "document has no `kind` field", &root(&[]))
                .with_help(format!("add `kind: <{}>`", kinds.join(" | "))),
        );
    };
    let kind_at = || root(&[Seg::Key("kind".into())]);
    let Kind::Str(kind) = &kind_node.kind else {
        return Err(Diagnostic::error(
            codes::V02,
            "`kind` must be a string",
            &kind_at(),
        ));
    };
    if RESERVED_KINDS.contains(&kind.as_str()) {
        return Err(Diagnostic::error(
            codes::V03,
            format!("kind `{kind}` is reserved and not supported in v1"),
            &kind_at(),
        ));
    }
    if let Some(d) = set.misplaced(kind, &kind_at()) {
        return Err(d);
    }
    if !set.implemented().contains(&kind.as_str()) {
        let d = if kinds.contains(&kind.as_str()) {
            Diagnostic::error(
                codes::V03,
                format!("kind `{kind}` is not implemented yet"),
                &kind_at(),
            )
        } else {
            let help = did_you_mean(kind, kinds.iter().copied()).map_or_else(
                || format!("expected one of: {}", ticked(kinds)),
                |s| format!("did you mean `{s}`?"),
            );
            Diagnostic::error(codes::V03, format!("unknown kind `{kind}`"), &kind_at())
                .with_help(help)
        };
        return Err(d);
    }

    let Value::Object(mut body) = doc.to_value() else {
        return Err(Diagnostic::error(
            codes::V02,
            "a definition document must be a mapping",
            &root(&[]),
        ));
    };
    body.shift_remove("kind");
    if kind == "ActionType" {
        rewrite_rules(&mut body, cx, doc)?;
    }
    let mut wrapped = serde_json::Map::new();
    wrapped.insert(kind.clone(), Value::Object(body));
    serde_path_to_error::deserialize::<_, T>(Value::Object(wrapped))
        .map_err(|e| map_error(&e, doc, cx))
}

/// Rewrite each `rules[i]` from `{ kind: x, .. }` to `{ x: { .. } }`, the same
/// transformation the document root gets, so rule errors keep their paths.
fn rewrite_rules(
    body: &mut serde_json::Map<String, Value>,
    cx: &Ctx,
    doc: &Node,
) -> Result<(), Diagnostic> {
    let Some(Value::Array(rules)) = body.get_mut("rules") else {
        return Ok(());
    };
    for (i, rule) in rules.iter_mut().enumerate() {
        let rule_path = [Seg::Key("rules".into()), Seg::Index(i)];
        let at_rule = |field: Option<&str>| {
            let mut path = rule_path.to_vec();
            path.extend(field.map(|f| Seg::Key(f.into())));
            cx.at(doc, &path, Part::Value)
        };
        let Value::Object(fields) = rule else {
            return Err(Diagnostic::error(
                codes::V02,
                "a rule must be a mapping",
                &at_rule(None),
            ));
        };
        let Some(kind) = fields.shift_remove("kind") else {
            return Err(
                Diagnostic::error(codes::V02, "rule has no `kind` field", &at_rule(None))
                    .with_help(format!("add `kind: <{}>`", RULE_KINDS.join(" | "))),
            );
        };
        let Value::String(kind) = kind else {
            return Err(Diagnostic::error(
                codes::V02,
                "`kind` must be a string",
                &at_rule(Some("kind")),
            ));
        };
        if kind == "function" {
            return Err(Diagnostic::error(
                codes::V03,
                "function-backed rules are not supported in v1",
                &at_rule(Some("kind")),
            )
            .with_help(format!("use one of: {}", ticked(&RULE_KINDS))));
        }
        let inner = std::mem::take(fields);
        let mut wrapped = serde_json::Map::new();
        wrapped.insert(kind, Value::Object(inner));
        *rule = Value::Object(wrapped);
    }
    Ok(())
}

/// Parse the manifest document (no `kind`).
pub fn parse_manifest(doc: &Node, cx: &Ctx) -> Result<Manifest, Diagnostic> {
    if !matches!(doc.kind, Kind::Map(_)) {
        let at = cx.at(doc, &[], Part::Value);
        return Err(Diagnostic::error(
            codes::V02,
            "the manifest must be a mapping",
            &at,
        ));
    }
    serde_path_to_error::deserialize::<_, Manifest>(doc.to_value())
        .map_err(|e| map_error(&e, doc, cx))
}

/// Backtick-quoted fragments of a serde message, in order.
fn ticks(msg: &str) -> Vec<&str> {
    msg.split('`').skip(1).step_by(2).collect()
}

/// Convert a `serde_path_to_error` path into original-document segments. An enum
/// segment that names no key of the original node is the rewrite wrapper and is
/// dropped.
fn to_segs(path: &Path, root: &Node) -> Vec<Seg> {
    let mut cur = root;
    let mut out = Vec::new();
    for seg in path {
        let next = match seg {
            Segment::Map { key } => Seg::Key(key.clone()),
            Segment::Seq { index } => Seg::Index(*index),
            Segment::Enum { variant } if cur.get(variant).is_some() => Seg::Key(variant.clone()),
            Segment::Enum { .. } => continue,
            Segment::Unknown => break,
        };
        cur = walk(cur, std::slice::from_ref(&next)).0;
        out.push(next);
    }
    out
}

fn map_error(
    e: &serde_path_to_error::Error<serde_json::Error>,
    root: &Node,
    cx: &Ctx,
) -> Diagnostic {
    let msg = e.inner().to_string();
    let mut path = to_segs(e.path(), root);
    let parts = ticks(&msg);

    if let Some(c) = parse_custom_de_error(&msg) {
        let d = Diagnostic::error(&c.code, c.message, &cx.at(root, &path, Part::Value));
        return match c.help {
            Some(h) => d.with_help(h),
            None => d,
        };
    }

    if msg.starts_with("unknown field ") {
        let name = parts.first().copied().unwrap_or_default();
        let expected = parts.get(1..).unwrap_or_default();
        if path.last() != Some(&Seg::Key(name.to_owned())) {
            path.push(Seg::Key(name.to_owned()));
        }
        let help = match did_you_mean(name, expected.iter().copied()) {
            Some(s) => format!("did you mean `{s}`?"),
            None if expected.is_empty() => "this object takes no fields".to_owned(),
            None => format!("expected one of: {}", ticked(expected)),
        };
        return Diagnostic::error(
            codes::V04,
            format!("unknown field `{name}`"),
            &cx.at(root, &path, Part::Key),
        )
        .with_help(help);
    }

    if msg.starts_with("missing field ") {
        let name = parts.first().copied().unwrap_or_default();
        if path.is_empty() && root.get("kind").is_some() {
            path.push(Seg::Key("kind".into()));
        }
        return Diagnostic::error(
            codes::V05,
            format!("missing required field `{name}`"),
            &cx.at(root, &path, Part::Value),
        );
    }

    if msg.starts_with("unknown variant ") {
        let got = parts.first().copied().unwrap_or_default();
        let expected = parts.get(1..).unwrap_or_default();
        let help = did_you_mean(got, expected.iter().copied()).map_or_else(
            || format!("expected one of: {}", ticked(expected)),
            |s| format!("did you mean `{s}`?"),
        );
        if walk(root, &path).0.get("kind").is_some() {
            path.push(Seg::Key("kind".into()));
            return Diagnostic::error(
                codes::V03,
                format!("unknown kind `{got}`"),
                &cx.at(root, &path, Part::Value),
            )
            .with_help(help);
        }
        return Diagnostic::error(
            codes::V06,
            format!("unknown value `{got}`"),
            &cx.at(root, &path, Part::Value),
        )
        .with_help(help);
    }

    let d = Diagnostic::error(codes::V06, msg.clone(), &cx.at(root, &path, Part::Value));
    if msg.contains("expected a string") {
        d.with_help("quote the value if it is meant to be a string")
    } else {
        d
    }
}

//! The column names a fixture file declares.
//!
//! The only implementation of fixture header semantics: the engine loads fixtures
//! with it and the offline lint rule compares the same names against the binding.

use camino::Utf8Path;
use indexmap::IndexSet;

/// The column names of a fixture, in file order.
///
/// A leading UTF-8 byte order mark is ignored in either format. A `.csv` file's header
/// is its first record. A `.json` file is a top-level array of objects whose header is
/// the union of all keys, in order of first appearance. A column without a name, or two
/// names that are equal in lower case, are errors: the engine could not load such a
/// fixture, so the lint must not look clean either (WR-S01). The error text names a
/// structural problem only and never repeats data from the file.
pub fn fixture_header(file: &str, text: &str) -> Result<Vec<String>, String> {
    let text = text.strip_prefix('\u{feff}').unwrap_or(text);
    let extension = Utf8Path::new(file).extension().map(str::to_ascii_lowercase);
    let header = match extension.as_deref() {
        Some("csv") => csv_header(text),
        Some("json") => json_header(text),
        _ => Err("a fixture must be a `.csv` or `.json` file".to_owned()),
    }?;
    let mut seen = std::collections::HashSet::new();
    for name in &header {
        if name.is_empty() {
            return Err("the fixture has a column without a name".to_owned());
        }
        if !seen.insert(name.to_lowercase()) {
            return Err(format!(
                "the fixture has two columns named `{name}` (names are compared in lower case)"
            ));
        }
    }
    Ok(header)
}

fn csv_header(text: &str) -> Result<Vec<String>, String> {
    let mut reader = csv::ReaderBuilder::new()
        .has_headers(true)
        .flexible(true)
        .from_reader(text.as_bytes());
    // `headers()` reads the first record only; the rest of the file is not parsed.
    let headers = reader
        .headers()
        .map_err(|_| "the first line is not valid CSV".to_owned())?;
    if headers.is_empty() {
        return Err("the CSV fixture has no header line".to_owned());
    }
    Ok(headers.iter().map(str::to_owned).collect())
}

fn json_header(text: &str) -> Result<Vec<String>, String> {
    let value: serde_json::Value = serde_json::from_str(text).map_err(|e| {
        format!(
            "the JSON fixture is not valid JSON (line {}, column {})",
            e.line(),
            e.column()
        )
    })?;
    let serde_json::Value::Array(rows) = value else {
        return Err("expected an array of objects at the top level".to_owned());
    };
    let mut keys: IndexSet<String> = IndexSet::new();
    for (i, row) in rows.into_iter().enumerate() {
        let serde_json::Value::Object(row) = row else {
            return Err(format!("element {i} of the array is not an object"));
        };
        keys.extend(row.into_iter().map(|(key, _)| key));
    }
    Ok(keys.into_iter().collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fixture_header_rules() {
        // A byte order mark is ignored, quoted fields keep their commas.
        assert_eq!(
            fixture_header("rows.csv", "\u{FEFF}a,\"b,c\",d\n1,2,3\n").unwrap(),
            ["a", "b,c", "d"]
        );
        // A header without data rows is a header.
        assert_eq!(fixture_header("rows.CSV", "x,y\n").unwrap(), ["x", "y"]);
        assert_eq!(fixture_header("rows.csv", "x,y").unwrap(), ["x", "y"]);
        // Only the first record is parsed: a ragged body is not this function's concern.
        assert_eq!(
            fixture_header("rows.csv", "x,y\n1,2,3,4\n").unwrap(),
            ["x", "y"]
        );
        assert!(fixture_header("rows.csv", "").is_err());
        assert!(fixture_header("rows.csv", "\u{FEFF}").is_err());

        // JSON: union of keys in order of first appearance.
        assert_eq!(
            fixture_header("rows.json", r#"[{"a":1},{"b":2,"a":3}]"#).unwrap(),
            ["a", "b"]
        );
        assert!(fixture_header("rows.json", "[]").unwrap().is_empty());
        assert!(fixture_header("rows.json", r#"{"a":1}"#).is_err());
        assert!(fixture_header("rows.json", r#"[{"a":1}, 2]"#).is_err());
        assert!(fixture_header("rows.json", "[{").is_err());

        // Anything else is not a fixture.
        assert!(fixture_header("rows.txt", "a,b").is_err());
        assert!(fixture_header("rows", "a,b").is_err());
    }

    /// WR-S01: the header rules the engine loads with live here, so the lint agrees with it.
    #[test]
    fn fixture_header_matches_the_engine_rules() {
        // A byte order mark is ignored in JSON too (Notepad writes one).
        assert_eq!(
            fixture_header("rows.json", "\u{FEFF}[{\"a\":1}]").unwrap(),
            ["a"]
        );
        // A column without a name, and names equal in lower case, are refused.
        for (file, text) in [
            ("rows.csv", "id,,name\n"),
            ("rows.csv", "id,ID\n"),
            ("rows.json", r#"[{"id":1,"":2}]"#),
            ("rows.json", r#"[{"Id":1},{"iD":2}]"#),
        ] {
            assert!(fixture_header(file, text).is_err(), "{file}: {text:?}");
        }
    }

    #[test]
    fn fixture_header_errors_do_not_echo_data() {
        let secret = "s3cr3t-value";
        for (file, text) in [
            ("rows.json", format!(r#"[{{"a":"{secret}"}}, "{secret}"]"#)),
            ("rows.json", format!(r#"{{"a":"{secret}"}}"#)),
            ("rows.json", format!(r#"[{{"a":"{secret}"#)),
        ] {
            let err = fixture_header(file, &text).expect_err("malformed");
            assert!(!err.contains(secret), "{err}");
        }
    }
}

//! Loading an ontology directory: parse, dispatch, merge, validate.

use std::collections::{BTreeMap, HashMap};

use camino::Utf8Path;

use crate::diag::{
    Diagnostic, Severity, SourceLocation, codes, has_errors, parse_custom_de_error,
    sort_diagnostics,
};
use crate::ir::{
    ActionType, ActionTypeName, BindingTarget, Definition, LinkType, LinkTypeName, Manifest,
    ObjectType, ObjectTypeName, Ontology, ProfileBindings, ProfileName, SourceBinding,
    binding_def_name,
};

mod discover;
mod dispatch;
mod fixture;
mod parse;
mod scope;
pub mod sourcemap;

pub use discover::{fixture_path, profile_dir};
use dispatch::{Ctx, dispatch, parse_manifest};
pub use fixture::fixture_header;
pub use scope::{ScopeLoadOutput, load_scope_dir, load_scope_from_memory};
pub use sourcemap::SourceMap;
use sourcemap::{DefKey, DefKind, FileId, FixtureColumns, Part, Seg};

/// File name of the manifest at the ontology root.
pub const MANIFEST: &str = "ontology.yaml";

#[derive(Debug)]
pub struct LoadOutput {
    /// `Some` only when no error was found.
    pub ontology: Option<Ontology>,
    pub sources: SourceMap,
    pub diagnostics: Vec<Diagnostic>,
}

type Text = Result<String, Diagnostic>;

/// Largest definition file the loader reads.
pub const MAX_FILE_BYTES: u64 = 4 * 1024 * 1024;

/// Most definition files one ontology may select (WR-07).
pub const MAX_FILES: usize = 10_000;

/// Most bytes all selected definition files may hold together (WR-07). Every text is
/// kept in the [`SourceMap`] for rendering, so this bounds the loader's memory.
pub const MAX_TOTAL_BYTES: u64 = 64 * 1024 * 1024;

/// Load the ontology under `root`: parse, merge and validate (every `ONT-V`
/// check except CEL, which `ontoforge-expr` owns).
pub fn load_dir(root: &Utf8Path) -> LoadOutput {
    isolated(internal_error, || {
        let manifest = read_text(root, MANIFEST);
        let (candidates, diagnostics) = discover::walk(root);
        let listing = Listing {
            candidates,
            diagnostics,
        };
        let probe = |rel: &str| probe_disk(root, rel);
        assemble(manifest, listing, &|name| read_text(root, name), &probe)
    })
}

/// Same pipeline over in-memory files; paths use `/` (`\` is accepted) and are
/// the diagnostic `file`s.
pub fn load_from_memory(files: &[(&str, &str)]) -> LoadOutput {
    isolated(internal_error, || load_from_memory_inner(files))
}

/// In-memory files by normalized path.
fn memory_files<'a>(files: &[(&str, &'a str)]) -> BTreeMap<String, &'a str> {
    files
        .iter()
        .map(|(p, t)| (discover::normalize(p), *t))
        .collect()
}

/// Reads one in-memory file, applying the same size limit as the disk reader.
fn read_memory(by_path: &BTreeMap<String, &str>, name: &str) -> Text {
    match by_path.get(name) {
        Some(t) => check_size(name, t.len() as u64).map(|()| (*t).to_owned()),
        None if name == MANIFEST => Err(missing_manifest()),
        None => Err(Diagnostic::without_location(
            codes::V14,
            Severity::Error,
            format!("cannot read `{name}`: not found"),
            name,
        )),
    }
}

fn load_from_memory_inner(files: &[(&str, &str)]) -> LoadOutput {
    let by_path = memory_files(files);
    let read = |name: &str| read_memory(&by_path, name);
    let listing = Listing {
        candidates: by_path.keys().cloned().collect(),
        diagnostics: Vec::new(),
    };
    let probe = |rel: &str| match by_path.get(rel) {
        Some(t) => {
            let len = t.len() as u64;
            if len > MAX_FILE_BYTES {
                Err(too_large(Some(len)))
            } else {
                Ok(len)
            }
        }
        None => Err("not found".to_owned()),
    };
    assemble(read(MANIFEST), listing, &read, &probe)
}

/// Stack size of the loader thread. The recursive-descent parsers need far more
/// than a 1 MiB debug-build stack (a Windows main thread) for nested input.
const LOADER_STACK_BYTES: usize = 32 << 20;

/// Run the whole load on a thread with a large stack, so callers never depend on
/// their own stack size. A panic becomes the `failed` output instead of unwinding
/// into the caller.
fn isolated<'a, T: Send>(failed: fn() -> T, work: impl FnOnce() -> T + Send + 'a) -> T {
    let outcome = std::thread::scope(|scope| {
        std::thread::Builder::new()
            .stack_size(LOADER_STACK_BYTES)
            .spawn_scoped(scope, work)
            .ok()
            .and_then(|handle| handle.join().ok())
    });
    outcome.unwrap_or_else(failed)
}

fn internal_error_diagnostic(file: &str) -> Diagnostic {
    Diagnostic::without_location(
        codes::V01,
        Severity::Error,
        "internal error while loading",
        file,
    )
}

fn internal_error() -> LoadOutput {
    LoadOutput {
        ontology: None,
        sources: SourceMap::default(),
        diagnostics: vec![internal_error_diagnostic(MANIFEST)],
    }
}

/// Candidate definition files plus problems found while listing them.
struct Listing {
    candidates: Vec<String>,
    diagnostics: Vec<Diagnostic>,
}

fn check_size(name: &str, len: u64) -> Result<(), Diagnostic> {
    if len > MAX_FILE_BYTES {
        return Err(Diagnostic::without_location(
            codes::V14,
            Severity::Error,
            format!("{}; skipped", too_large(Some(len))),
            name,
        ));
    }
    Ok(())
}

/// "file is N bytes, over the limit", without the size when it is not known.
pub(crate) fn too_large(len: Option<u64>) -> String {
    match len {
        Some(len) => format!("file is {len} bytes, over the {MAX_FILE_BYTES} byte limit"),
        None => format!("file is over the {MAX_FILE_BYTES} byte limit"),
    }
}

fn missing_manifest() -> Diagnostic {
    Diagnostic::without_location(
        codes::V14,
        Severity::Error,
        format!("manifest `{MANIFEST}` not found in the ontology directory"),
        MANIFEST,
    )
    .with_help(format!(
        "create `{MANIFEST}` with at least `apiName: <camelCaseName>`"
    ))
}

/// Why [`read_limited`] returned no bytes.
#[derive(Debug, PartialEq, Eq)]
pub enum ReadFailure {
    Io(std::io::ErrorKind),
    /// A symbolic link (when links are not followed), directory, device or pipe.
    NotRegular,
    /// Over the caller's limit; the size when the file system reported it.
    TooLarge(Option<u64>),
}

/// Read a regular file of at most `max_bytes` (CR-03). With `follow_links` false a
/// symbolic link as the last component is refused; a link on a directory on the way is
/// not, so repository content goes through [`read_beneath`], which refuses those too
/// (CR-S01). The read itself is bounded, so a file that grows or lies about its size
/// still cannot exhaust memory.
///
/// Repository content (definitions, binding files, fixtures) is read with
/// [`read_beneath`] and [`MAX_FILE_BYTES`]. Paths the deployer supplies
/// (server configuration, secret files, CA files) may use `true`, because Kubernetes
/// mounts secrets and config maps as symbolic links.
pub fn read_limited(
    path: &std::path::Path,
    follow_links: bool,
    max_bytes: u64,
) -> Result<Vec<u8>, ReadFailure> {
    use std::io::Read;

    let meta = if follow_links {
        std::fs::metadata(path)
    } else {
        std::fs::symlink_metadata(path)
    }
    .map_err(|e| ReadFailure::Io(e.kind()))?;
    if !meta.file_type().is_file() {
        return Err(ReadFailure::NotRegular);
    }
    if meta.len() > max_bytes {
        return Err(ReadFailure::TooLarge(Some(meta.len())));
    }
    let mut bytes = Vec::new();
    std::fs::File::open(path)
        .and_then(|f| f.take(max_bytes.saturating_add(1)).read_to_end(&mut bytes))
        .map_err(|e| ReadFailure::Io(e.kind()))?;
    if bytes.len() as u64 > max_bytes {
        return Err(ReadFailure::TooLarge(None));
    }
    Ok(bytes)
}

/// Refuse `rel` (`/` separated, relative to `root`) when a symbolic link or junction sits
/// anywhere on the way from `root` to it, or when the resolved path is not below the resolved
/// `root` (CR-S01). `lstat` on the full path only looks at the last component, so a checked-in
/// directory link (a junction on Windows) would otherwise lead a read out of the ontology.
/// A component that does not exist is left to the caller's own open, which reports it.
pub fn check_beneath(root: &Utf8Path, rel: &str) -> Result<(), ReadFailure> {
    let mut at = root.as_std_path().to_path_buf();
    for segment in rel.split('/').filter(|s| !s.is_empty() && *s != ".") {
        if segment == ".." {
            return Err(ReadFailure::NotRegular);
        }
        at.push(segment);
        match std::fs::symlink_metadata(&at) {
            // On Windows this is true for symbolic links and junctions alike.
            Ok(meta) if meta.file_type().is_symlink() => return Err(ReadFailure::NotRegular),
            Ok(_) => {}
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(e) => return Err(ReadFailure::Io(e.kind())),
        }
    }
    // Defense in depth: whatever the file system did, the real path stays under the root.
    let resolved = std::fs::canonicalize(&at).map_err(|e| ReadFailure::Io(e.kind()))?;
    let base = std::fs::canonicalize(root.as_std_path()).map_err(|e| ReadFailure::Io(e.kind()))?;
    if resolved.starts_with(&base) {
        Ok(())
    } else {
        Err(ReadFailure::NotRegular)
    }
}

/// [`read_limited`] of repository content at `rel` below `root`, links refused on the whole
/// way there ([`check_beneath`]). The schema loader and the engine's fixture loader both read
/// fixtures through this.
pub fn read_beneath(root: &Utf8Path, rel: &str, max_bytes: u64) -> Result<Vec<u8>, ReadFailure> {
    check_beneath(root, rel)?;
    read_limited(root.join(rel).as_std_path(), false, max_bytes)
}

/// Size of the fixture at `rel` (relative to `root`) from its metadata alone: it must be a
/// regular file inside the ontology directory, with no symbolic link or junction on the way,
/// within [`MAX_FILE_BYTES`] (E23, CR-S01).
fn probe_disk(root: &Utf8Path, rel: &str) -> Result<u64, String> {
    const NOT_REGULAR: &str = "not a regular file inside the ontology directory (symbolic links and junctions are not followed)";
    match check_beneath(root, rel) {
        Ok(()) => {}
        Err(ReadFailure::Io(std::io::ErrorKind::NotFound)) => return Err("not found".to_owned()),
        Err(ReadFailure::Io(kind)) => return Err(format!("cannot be read: {kind}")),
        Err(ReadFailure::NotRegular | ReadFailure::TooLarge(_)) => {
            return Err(NOT_REGULAR.to_owned());
        }
    }
    let meta = std::fs::symlink_metadata(root.join(rel).as_std_path()).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            "not found".to_owned()
        } else {
            format!("cannot be read: {}", e.kind())
        }
    })?;
    if !meta.file_type().is_file() {
        return Err(NOT_REGULAR.to_owned());
    }
    if meta.len() > MAX_FILE_BYTES {
        return Err(too_large(Some(meta.len())));
    }
    Ok(meta.len())
}

fn read_text(root: &Utf8Path, name: &str) -> Text {
    let v14 =
        |message: String| Diagnostic::without_location(codes::V14, Severity::Error, message, name);
    match read_beneath(root, name, MAX_FILE_BYTES) {
        Ok(bytes) => String::from_utf8(bytes).map_err(|_| {
            Diagnostic::without_location(
                codes::V01,
                Severity::Error,
                "file is not valid UTF-8",
                name,
            )
        }),
        Err(ReadFailure::TooLarge(len)) => Err(v14(format!("{}; skipped", too_large(len)))),
        Err(ReadFailure::NotRegular) => Err(v14(format!(
            "`{name}` is not a regular file (symbolic links are not followed); skipped"
        ))),
        Err(ReadFailure::Io(std::io::ErrorKind::NotFound)) if name == MANIFEST => {
            Err(missing_manifest())
        }
        Err(ReadFailure::Io(kind)) => Err(v14(format!("cannot read `{name}`: {kind}"))),
    }
}

fn syntax_diagnostic(sources: &SourceMap, file: FileId, e: &parse::ParseError) -> Diagnostic {
    let at = if e.line == 0 {
        sources.whole_file(file)
    } else {
        sources.raw_location(file, e.line, e.column, e.offset, e.length)
    };
    Diagnostic::error(codes::V01, e.message.clone(), &at)
}

/// What [`assemble`] asks about a fixture file: its size, or why it cannot be used. Only
/// metadata is looked at; the content is never read here.
type Probe<'a> = &'a dyn Fn(&str) -> Result<u64, String>;

fn assemble(
    manifest: Text,
    listing: Listing,
    read: &dyn Fn(&str) -> Text,
    probe: Probe,
) -> LoadOutput {
    let mut sources = SourceMap::default();
    let mut diags = Vec::new();
    let manifest = load_manifest(&mut sources, manifest, &mut diags);

    let report_empty = listing.diagnostics.is_empty();
    diags.extend(listing.diagnostics);
    let selection = discover::select(
        listing.candidates,
        manifest.as_ref(),
        &sources,
        report_empty,
    );
    diags.extend(selection.diagnostics);

    let mut defs = Defs::default();
    if selection.files.len() > MAX_FILES {
        diags.push(
            Diagnostic::without_location(
                codes::V14,
                Severity::Error,
                format!(
                    "the include patterns select {} files, more than the {MAX_FILES} an ontology may have; only the first {MAX_FILES} were read",
                    selection.files.len()
                ),
                MANIFEST,
            )
            .with_help("narrow `include` in the manifest"),
        );
    }
    let mut total: u64 = 0;
    for path in selection.files.into_iter().take(MAX_FILES) {
        let text = match read(&path) {
            Ok(t) => t,
            Err(d) => {
                diags.push(d);
                continue;
            }
        };
        total += text.len() as u64;
        if total > MAX_TOTAL_BYTES {
            diags.push(Diagnostic::without_location(
                codes::V14,
                Severity::Error,
                format!(
                    "definition files exceed the {MAX_TOTAL_BYTES} byte budget of an ontology; this file and the ones after it were not read"
                ),
                path,
            ));
            break;
        }
        let parsed = parse::parse_documents(&text, discover::is_json_file(&path));
        let file = sources.add_file(&path, text);
        match parsed {
            Err(e) => diags.push(syntax_diagnostic(&sources, file, &e)),
            Ok(docs) => {
                for doc in docs {
                    merge(&mut sources, file, doc, &mut defs, &mut diags);
                }
            }
        }
    }

    let mut ontology = manifest.filter(|_| !has_errors(&diags)).map(|m| Ontology {
        api_name: m.api_name,
        display_name: m.display_name,
        description: m.description,
        object_types: defs.objects,
        link_types: defs.links,
        action_types: defs.actions,
        default_profile: m.default_profile,
        bindings: defs.bindings,
    });
    if let Some(o) = &ontology {
        diags.extend(crate::validate::validate(o, &sources));
        diags.extend(crate::validate::check_fixture_files(o, &sources, probe));
    }
    sort_diagnostics(&mut diags);
    if has_errors(&diags) {
        ontology = None;
    }
    if let Some(o) = &ontology {
        capture_fixture_headers(o, &mut sources, read, probe, total);
    }
    LoadOutput {
        ontology,
        sources,
        diagnostics: diags,
    }
}

/// Record the header of every fixture the bindings name, for the offline lint rule that
/// compares it with the bound columns (ONT-W17).
///
/// Fixture bytes count against [`MAX_TOTAL_BYTES`] together with the definition files
/// (`total` is what those already used, E23), and a fixture several bindings share is
/// read once. A fixture that is not read, or whose header cannot be parsed, is recorded
/// with the reason instead of being left out, so the rule can say so (E20). Only the
/// header is kept: the text is dropped after it is parsed.
fn capture_fixture_headers(
    ontology: &Ontology,
    sources: &mut SourceMap,
    read: &dyn Fn(&str) -> Text,
    probe: Probe,
    mut total: u64,
) {
    let mut by_path: HashMap<String, FixtureColumns> = HashMap::new();
    for (profile, bound) in &ontology.bindings {
        for binding in bound.objects.values().chain(bound.links.values()) {
            let Some(fixture) = &binding.fixture else {
                continue;
            };
            let def_name = binding_def_name(profile, binding.target_name());
            let key = DefKey {
                kind: DefKind::SourceBinding,
                api_name: def_name.clone(),
            };
            let binding_file = sources.locate(&key, &[], Part::Value).file;
            let columns = match fixture_path(&binding_file, &fixture.file) {
                Ok(resolved) => by_path
                    .entry(resolved.clone())
                    .or_insert_with(|| read_fixture_header(&resolved, read, probe, &mut total))
                    .clone(),
                Err(reason) => Err(reason),
            };
            sources.set_fixture_columns(def_name, columns);
        }
    }
}

/// The header of the fixture at `path`, adding the bytes read to `total`.
fn read_fixture_header(
    path: &str,
    read: &dyn Fn(&str) -> Text,
    probe: Probe,
    total: &mut u64,
) -> FixtureColumns {
    let size = probe(path)?;
    if total.saturating_add(size) > MAX_TOTAL_BYTES {
        return Err(format!(
            "fixture skipped: the ontology byte budget of {MAX_TOTAL_BYTES} bytes is exhausted"
        ));
    }
    let text = read(path).map_err(|d| d.message)?;
    *total += text.len() as u64;
    fixture_header(path, &text)
}

fn load_manifest(
    sources: &mut SourceMap,
    text: Text,
    diags: &mut Vec<Diagnostic>,
) -> Option<Manifest> {
    let text = match text {
        Ok(t) => t,
        Err(d) => {
            diags.push(d);
            return None;
        }
    };
    let parsed = parse::parse_documents(&text, false);
    let file = sources.add_file(MANIFEST, text);
    let mut docs = match parsed {
        Ok(d) => d,
        Err(e) => {
            diags.push(syntax_diagnostic(sources, file, &e));
            return None;
        }
    };
    if docs.is_empty() {
        diags.push(Diagnostic::error(
            codes::V02,
            "the manifest is empty",
            &sources.whole_file(file),
        ));
        return None;
    }
    if docs.len() > 1 {
        let at = sources.locate_in(file, &docs[1], &[], Part::Value);
        diags.push(Diagnostic::error(
            codes::V02,
            "the manifest must be a single document",
            &at,
        ));
        return None;
    }
    let doc = docs.remove(0);
    let result = parse_manifest(&doc, &Ctx { file, sources });
    sources.set_manifest(file, doc);
    match result {
        Ok(m) => Some(m),
        Err(d) => {
            diags.push(d);
            None
        }
    }
}

/// Definitions collected from all files, keyed by apiName.
#[derive(Default)]
struct Defs {
    objects: BTreeMap<ObjectTypeName, ObjectType>,
    links: BTreeMap<LinkTypeName, LinkType>,
    actions: BTreeMap<ActionTypeName, ActionType>,
    bindings: BTreeMap<ProfileName, ProfileBindings>,
}

fn merge(
    sources: &mut SourceMap,
    file: FileId,
    doc: parse::Node,
    defs: &mut Defs,
    diags: &mut Vec<Diagnostic>,
) {
    let def = match dispatch(&doc, &Ctx { file, sources }) {
        Ok(d) => d,
        Err(d) => {
            diags.push(d);
            return;
        }
    };
    let path = sources.path(file).to_owned();
    let def = match def {
        Definition::SourceBinding(binding) => {
            merge_binding(sources, file, &path, doc, binding, defs, diags);
            return;
        }
        other => other,
    };
    if path.starts_with(&format!("{}/", discover::BINDINGS_DIR)) {
        let label = match &def {
            Definition::ObjectType(_) => "ObjectType",
            Definition::LinkType(_) => "LinkType",
            Definition::ActionType(_) => "ActionType",
            Definition::SourceBinding(_) => "SourceBinding",
        };
        let at = sources.locate_in(file, &doc, &[Seg::Key("kind".into())], Part::Value);
        diags.push(
            Diagnostic::error(
                codes::V16,
                format!(
                    "a {label} document cannot be placed under `bindings/`, which holds only SourceBinding documents"
                ),
                &at,
            )
            .with_help("move this file out of `bindings/`"),
        );
        return;
    }
    let (kind, label, api_name, duplicate) = match &def {
        Definition::ObjectType(o) => (
            DefKind::ObjectType,
            "ObjectType",
            o.api_name.to_string(),
            defs.objects.contains_key(o.api_name.as_str()),
        ),
        Definition::LinkType(l) => (
            DefKind::LinkType,
            "LinkType",
            l.api_name.to_string(),
            defs.links.contains_key(l.api_name.as_str()),
        ),
        Definition::ActionType(a) => (
            DefKind::ActionType,
            "ActionType",
            a.api_name.to_string(),
            defs.actions.contains_key(a.api_name.as_str()),
        ),
        // Handled above.
        Definition::SourceBinding(_) => return,
    };
    let key = DefKey { kind, api_name };
    let name_path = [Seg::Key("apiName".into())];
    if duplicate {
        let first: SourceLocation = sources.locate(&key, &name_path, Part::Value);
        let at = sources.locate_in(file, &doc, &name_path, Part::Value);
        diags.push(Diagnostic::error(
            codes::V08,
            format!(
                "duplicate {label} `{}`; first defined at {}:{}:{}",
                key.api_name, first.file, first.line, first.column
            ),
            &at,
        ));
        return;
    }
    sources.register_def(key, file, doc);
    match def {
        Definition::ObjectType(o) => {
            defs.objects.insert(o.api_name.clone(), o);
        }
        Definition::LinkType(l) => {
            defs.links.insert(l.api_name.clone(), l);
        }
        Definition::ActionType(a) => {
            defs.actions.insert(a.api_name.clone(), a);
        }
        Definition::SourceBinding(_) => {}
    }
}

/// Place a `SourceBinding` document: it must sit under `bindings/<profile>/` with a
/// valid profile name, and each target may be bound once per profile. The profile is
/// taken from the directory and used only as a map key.
fn merge_binding(
    sources: &mut SourceMap,
    file: FileId,
    path: &str,
    doc: parse::Node,
    binding: SourceBinding,
    defs: &mut Defs,
    diags: &mut Vec<Diagnostic>,
) {
    let kind_at = |sources: &SourceMap| {
        sources.locate_in(file, &doc, &[Seg::Key("kind".into())], Part::Value)
    };
    let Some(dir) = discover::profile_dir(path) else {
        diags.push(
            Diagnostic::error(
                codes::V16,
                "a SourceBinding document must be placed under `bindings/<profile>/`",
                &kind_at(sources),
            )
            .with_help("move this file to `bindings/<profile>/`, for example `bindings/dev/`"),
        );
        return;
    };
    let profile = match ProfileName::try_from(dir.to_owned()) {
        Ok(profile) => profile,
        Err(raw) => {
            let (message, help) =
                parse_custom_de_error(&raw).map_or((raw, None), |c| (c.message, c.help));
            let d = Diagnostic::error(
                codes::V16,
                format!("{message} (the profile is the directory name under `bindings/`)"),
                &kind_at(sources),
            );
            diags.push(match help {
                Some(h) => d.with_help(h),
                None => d,
            });
            return;
        }
    };

    let (target_key, target_name, duplicate) = {
        let bound = defs.bindings.entry(profile.clone()).or_default();
        match &binding.target {
            BindingTarget::ObjectType(n) => (
                "objectType",
                n.as_str().to_owned(),
                bound.objects.contains_key(n.as_str()),
            ),
            BindingTarget::LinkType(n) => (
                "linkType",
                n.as_str().to_owned(),
                bound.links.contains_key(n.as_str()),
            ),
        }
    };
    let key = DefKey {
        kind: DefKind::SourceBinding,
        api_name: binding_def_name(&profile, &target_name),
    };
    let name_path = [Seg::Key("target".into()), Seg::Key(target_key.into())];
    if duplicate {
        let first = sources.locate(&key, &name_path, Part::Value);
        let at = sources.locate_in(file, &doc, &name_path, Part::Value);
        diags.push(Diagnostic::error(
            codes::V08,
            format!(
                "duplicate SourceBinding for `{target_name}` in profile `{profile}`; first defined at {}:{}:{}",
                first.file, first.line, first.column
            ),
            &at,
        ));
        return;
    }
    sources.register_def(key, file, doc);
    let bound = defs.bindings.entry(profile).or_default();
    match &binding.target {
        BindingTarget::ObjectType(n) => {
            bound.objects.insert(n.clone(), binding);
        }
        BindingTarget::LinkType(n) => {
            bound.links.insert(n.clone(), binding);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{MAX_FILE_BYTES, ReadFailure, load_from_memory, read_limited};

    const MANIFEST: &str = "apiName: demo\n";

    fn object(name: &str) -> String {
        format!(
            "kind: ObjectType\napiName: {name}\nprimaryKey: id\nproperties:\n  id: {{ type: string, required: true }}\nbacking: source\n"
        )
    }

    fn binding(name: &str, fixture: &str) -> String {
        format!(
            "kind: SourceBinding\ntarget: {{ objectType: {name} }}\nsource: {{ catalog: demo, schema: s, table: t }}\nfixture: {{ file: {fixture} }}\n"
        )
    }

    #[test]
    fn fixture_header_is_captured() {
        let objects = format!("{}---\n{}", object("Flight"), object("Pilot"));
        let flight = binding("Flight", "fixtures/flights.csv");
        let pilot = binding("Pilot", "fixtures/pilots.json");
        let broken = "kind: SourceBinding\ntarget: { objectType: Seat }\nsource: { catalog: demo, schema: s, table: t }\nfixture: { file: fixtures/seats.json }\n";
        let seat = object("Seat");
        let files = [
            ("ontology.yaml", MANIFEST),
            ("objects.yaml", objects.as_str()),
            ("seats.yaml", seat.as_str()),
            ("bindings/dev/flight.yaml", flight.as_str()),
            (
                "bindings/dev/fixtures/flights.csv",
                "\u{feff}id,flight_no\nF-1,LH1\n",
            ),
            ("bindings/dev/pilot.yaml", pilot.as_str()),
            (
                "bindings/dev/fixtures/pilots.json",
                r#"[{"id": "P-1"}, {"name": "Ann", "id": "P-2"}]"#,
            ),
            ("bindings/dev/seat.yaml", broken),
            ("bindings/dev/fixtures/seats.json", r#"{"id": "S-1"}"#),
        ];
        let out = load_from_memory(&files);
        assert!(out.ontology.is_some(), "{:#?}", out.diagnostics);
        let columns = |name: &str| out.sources.fixture_columns(name).cloned();
        assert_eq!(
            columns("dev/Flight"),
            Some(Ok(vec!["id".to_owned(), "flight_no".to_owned()]))
        );
        assert_eq!(
            columns("dev/Pilot"),
            Some(Ok(vec!["id".to_owned(), "name".to_owned()]))
        );
        let Some(Err(reason)) = columns("dev/Seat") else {
            panic!("a malformed fixture records why it cannot be read");
        };
        assert!(reason.contains("array of objects"), "{reason}");
        // A binding without a fixture has no entry.
        assert_eq!(columns("dev/Nothing"), None);
    }

    /// E23: fixtures are read after the definition files and share their byte budget.
    #[test]
    fn fixture_bytes_count_toward_budget() {
        let (objects, bindings, fixtures) = many_fixture_bindings(17, 17);
        let big = max_size_fixture();
        let out = load_from_memory(&memory_files(&objects, &bindings, &fixtures, &big));
        assert!(out.ontology.is_some(), "{:#?}", out.diagnostics);
        // 64 MiB hold 15 fixtures of 4 MiB next to the small definition files.
        for (i, letter) in letters(17).enumerate() {
            let columns = out.sources.fixture_columns(&format!("dev/Item{letter}"));
            if i < 15 {
                assert_eq!(columns, Some(&Ok(vec!["id".to_owned()])), "Item{letter}");
            } else {
                let Some(Err(reason)) = columns else {
                    panic!("Item{letter} was read past the budget: {columns:?}");
                };
                assert!(reason.contains("byte budget"), "{reason}");
            }
        }
    }

    /// E23: a fixture that several bindings use is read, and counted, once.
    #[test]
    fn shared_fixture_is_counted_once() {
        let (objects, bindings, fixtures) = many_fixture_bindings(17, 15);
        let big = max_size_fixture();
        let out = load_from_memory(&memory_files(&objects, &bindings, &fixtures, &big));
        assert!(out.ontology.is_some(), "{:#?}", out.diagnostics);
        for letter in letters(17) {
            let columns = out.sources.fixture_columns(&format!("dev/Item{letter}"));
            assert_eq!(columns, Some(&Ok(vec!["id".to_owned()])), "Item{letter}");
        }
    }

    fn letters(n: u8) -> impl Iterator<Item = char> {
        (0..n).map(|i| char::from(b'A' + i))
    }

    /// A CSV with a one-column header that is exactly [`MAX_FILE_BYTES`] long.
    fn max_size_fixture() -> String {
        let big = format!(
            "id\n{}",
            "x".repeat(usize::try_from(MAX_FILE_BYTES).unwrap() - 3)
        );
        assert_eq!(big.len() as u64, MAX_FILE_BYTES);
        big
    }

    /// `bindings` object types `ItemA`.. each with a binding; binding `i` uses
    /// fixture `f{i % distinct}.csv`. Returns the object text, the (path, text) of
    /// every binding, and the fixture paths.
    fn many_fixture_bindings(
        bindings: u8,
        distinct: u8,
    ) -> (String, Vec<(String, String)>, Vec<String>) {
        let objects: Vec<String> = letters(bindings)
            .map(|l| object(&format!("Item{l}")))
            .collect();
        let bound: Vec<(String, String)> = letters(bindings)
            .zip(0..)
            .map(|(l, i)| {
                (
                    format!("bindings/dev/item-{l}.yaml"),
                    binding(
                        &format!("Item{l}"),
                        &format!("fixtures/f{}.csv", i % distinct),
                    ),
                )
            })
            .collect();
        let fixtures = (0..distinct)
            .map(|i| format!("bindings/dev/fixtures/f{i}.csv"))
            .collect();
        (objects.join("---\n"), bound, fixtures)
    }

    fn memory_files<'a>(
        objects: &'a str,
        bindings: &'a [(String, String)],
        fixtures: &'a [String],
        fixture_text: &'a str,
    ) -> Vec<(&'a str, &'a str)> {
        let mut files = vec![("ontology.yaml", MANIFEST), ("objects.yaml", objects)];
        files.extend(bindings.iter().map(|(p, t)| (p.as_str(), t.as_str())));
        files.extend(fixtures.iter().map(|p| (p.as_str(), fixture_text)));
        files
    }

    /// E20: bytes that are not UTF-8 are recorded as unreadable, not skipped.
    #[test]
    fn fixture_that_is_not_utf8_is_recorded_as_unreadable() {
        let dir = tempfile::tempdir().expect("tempdir");
        let root = camino::Utf8Path::from_path(dir.path()).expect("utf-8 temp dir");
        std::fs::create_dir_all(dir.path().join("bindings/dev/fixtures")).unwrap();
        std::fs::write(dir.path().join("ontology.yaml"), MANIFEST).unwrap();
        std::fs::write(dir.path().join("objects.yaml"), object("Flight")).unwrap();
        std::fs::write(
            dir.path().join("bindings/dev/flight.yaml"),
            binding("Flight", "fixtures/flights.csv"),
        )
        .unwrap();
        std::fs::write(
            dir.path().join("bindings/dev/fixtures/flights.csv"),
            [b'i', b'd', b'\n', 0xff, 0xfe],
        )
        .unwrap();
        let out = super::load_dir(root);
        assert!(out.ontology.is_some(), "{:#?}", out.diagnostics);
        let Some(Err(reason)) = out.sources.fixture_columns("dev/Flight") else {
            panic!("an unreadable fixture records why");
        };
        assert!(reason.contains("UTF-8"), "{reason}");
    }

    #[test]
    fn read_limited_custom_limit() {
        let dir = tempfile::tempdir().expect("tempdir");
        let at_limit = dir.path().join("at-limit.txt");
        std::fs::write(&at_limit, vec![b'a'; 65_536]).expect("write");
        let over = dir.path().join("over.txt");
        std::fs::write(&over, vec![b'a'; 65_537]).expect("write");

        assert_eq!(
            read_limited(&at_limit, false, 65_536).map(|bytes| bytes.len()),
            Ok(65_536)
        );
        assert_eq!(
            read_limited(&over, false, 65_536).map(|bytes| bytes.len()),
            Err(ReadFailure::TooLarge(Some(65_537)))
        );
    }

    #[test]
    fn read_limited_missing_and_directory() {
        let dir = tempfile::tempdir().expect("tempdir");
        assert_eq!(
            read_limited(&dir.path().join("nope"), false, 16),
            Err(ReadFailure::Io(std::io::ErrorKind::NotFound))
        );
        assert_eq!(
            read_limited(dir.path(), false, 16),
            Err(ReadFailure::NotRegular)
        );
    }

    #[cfg(unix)]
    #[test]
    fn read_limited_follows_links_only_when_asked() {
        let dir = tempfile::tempdir().expect("tempdir");
        let target = dir.path().join("target.txt");
        std::fs::write(&target, b"hello").expect("write");
        let link = dir.path().join("link.txt");
        std::os::unix::fs::symlink(&target, &link).expect("symlink");

        assert_eq!(read_limited(&link, false, 16), Err(ReadFailure::NotRegular));
        assert_eq!(read_limited(&link, true, 16), Ok(b"hello".to_vec()));
    }
}

//! YAML/JSON text to a span-carrying [`Node`] tree.
//!
//! Every definition file goes through this one module, so replacing the YAML
//! parser only touches this file. Input is always a `&str`: byte offsets are only
//! available for string input.

use std::fmt;

use serde::de::{self, MapAccess, SeqAccess, Visitor};
use serde::{Deserialize, Deserializer};
use serde_saphyr::{Budget, DuplicateKeyPolicy, Location, MergeKeyPolicy, Options, Spanned};

use crate::diag::offset_to_line_col;

/// Maximum structural nesting depth accepted in definition files.
const MAX_DEPTH: usize = 32;

#[derive(Debug)]
pub struct Node {
    pub loc: Location,
    pub kind: Kind,
}

#[derive(Debug)]
pub enum Kind {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Seq(Vec<Node>),
    Map(Vec<(Spanned<String>, Node)>),
}

impl<'de> Deserialize<'de> for Node {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let s = Spanned::<Kind>::deserialize(d)?;
        Ok(Node {
            loc: s.referenced,
            kind: s.value,
        })
    }
}

impl<'de> Deserialize<'de> for Kind {
    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        struct V;
        impl<'de> Visitor<'de> for V {
            type Value = Kind;

            fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result {
                f.write_str("a YAML or JSON value")
            }
            fn visit_unit<E>(self) -> Result<Kind, E> {
                Ok(Kind::Null)
            }
            fn visit_bool<E>(self, v: bool) -> Result<Kind, E> {
                Ok(Kind::Bool(v))
            }
            fn visit_i64<E>(self, v: i64) -> Result<Kind, E> {
                Ok(Kind::Int(v))
            }
            fn visit_u64<E: de::Error>(self, v: u64) -> Result<Kind, E> {
                i64::try_from(v).map(Kind::Int).map_err(E::custom)
            }
            fn visit_f64<E>(self, v: f64) -> Result<Kind, E> {
                Ok(Kind::Float(v))
            }
            fn visit_str<E>(self, v: &str) -> Result<Kind, E> {
                Ok(Kind::Str(v.to_owned()))
            }
            fn visit_seq<A: SeqAccess<'de>>(self, mut a: A) -> Result<Kind, A::Error> {
                let mut items = Vec::new();
                while let Some(n) = a.next_element()? {
                    items.push(n);
                }
                Ok(Kind::Seq(items))
            }
            fn visit_map<A: MapAccess<'de>>(self, mut a: A) -> Result<Kind, A::Error> {
                let mut entries = Vec::new();
                while let Some(k) = a.next_key()? {
                    entries.push((k, a.next_value()?));
                }
                Ok(Kind::Map(entries))
            }
        }
        d.deserialize_any(V)
    }
}

impl Node {
    /// Convert to a `serde_json::Value` (map order preserved).
    pub fn to_value(&self) -> serde_json::Value {
        use serde_json::Value as J;
        match &self.kind {
            Kind::Null => J::Null,
            Kind::Bool(b) => J::Bool(*b),
            Kind::Int(i) => J::from(*i),
            Kind::Float(f) => serde_json::Number::from_f64(*f).map_or(J::Null, J::Number),
            Kind::Str(s) => J::String(s.clone()),
            Kind::Seq(items) => J::Array(items.iter().map(Node::to_value).collect()),
            Kind::Map(entries) => J::Object(
                entries
                    .iter()
                    .map(|(k, v)| (k.value.clone(), v.to_value()))
                    .collect(),
            ),
        }
    }

    /// The entry named `key` when this node is a mapping.
    pub fn get(&self, key: &str) -> Option<(&Spanned<String>, &Node)> {
        match &self.kind {
            Kind::Map(entries) => entries
                .iter()
                .find(|(k, _)| k.value == key)
                .map(|(k, v)| (k, v)),
            _ => None,
        }
    }
}

/// A syntax-level failure with the numbers needed to build a location later.
#[derive(Debug)]
pub struct ParseError {
    pub message: String,
    pub line: u64,
    pub column: u64,
    pub offset: usize,
    pub length: usize,
}

fn options() -> Options {
    let mut o = Options::default();
    o.strict_booleans = true;
    o.duplicate_keys = DuplicateKeyPolicy::Error;
    o.merge_keys = MergeKeyPolicy::Error;
    o.reject_unsupported_tags = true;
    o.with_snippet = false;
    let mut budget = Budget::default();
    budget.max_depth = MAX_DEPTH;
    o.budget = Some(budget);
    o
}

/// Parse all documents of a file. A `.json` file is first checked with a strict JSON
/// parser (the YAML parser accepts trailing commas and comments), and a top-level
/// array is flattened into one document per element.
pub fn parse_documents(text: &str, json: bool) -> Result<Vec<Node>, ParseError> {
    if json {
        precheck_json(text)?;
    }
    let mut docs: Vec<Node> =
        serde_saphyr::from_multiple_with_options(text, options()).map_err(|e| {
            let loc = e.location();
            let span = loc.map(|l| l.span());
            ParseError {
                message: clean_message(&e.to_string()),
                line: loc.map_or(0, |l| l.line()),
                column: loc.map_or(0, |l| l.column()),
                offset: span
                    .and_then(|s| s.byte_offset())
                    .and_then(|o| usize::try_from(o).ok())
                    .unwrap_or(0),
                length: span
                    .and_then(|s| s.byte_len())
                    .and_then(|o| usize::try_from(o).ok())
                    .unwrap_or(1),
            }
        })?;
    if json
        && docs.len() == 1
        && matches!(docs[0].kind, Kind::Seq(_))
        && let Kind::Seq(items) = docs.remove(0).kind
    {
        docs = items;
    }
    Ok(docs)
}

fn precheck_json(text: &str) -> Result<(), ParseError> {
    let body = text.trim_start_matches('\u{feff}');
    serde_json::from_str::<de::IgnoredAny>(body)
        .map(|_| ())
        .map_err(|e| {
            let bom = text.len() - body.len();
            let offset = offset_of(body, e.line(), e.column());
            ParseError {
                message: json_message(&e.to_string()),
                line: u64::try_from(e.line()).unwrap_or(0),
                // serde_json counts bytes; the diagnostic column counts characters.
                column: u64::from(offset_to_line_col(body, offset).1),
                offset: bom + offset,
                length: 1,
            }
        })
}

/// Byte offset of a 1-based line and byte column, moved back to a char boundary.
fn offset_of(text: &str, line: usize, column: usize) -> usize {
    let line_start: usize = text
        .split_inclusive('\n')
        .take(line.saturating_sub(1))
        .map(str::len)
        .sum();
    let mut offset = (line_start + column.saturating_sub(1)).min(text.len());
    while !text.is_char_boundary(offset) {
        offset -= 1;
    }
    offset
}

/// Drop the trailing position the parsers append (` at line L, column C` for YAML,
/// ` at line L column C` for JSON); the location is reported separately. A position
/// inside the message is kept (WR-08).
fn strip_position(first_line: &str) -> String {
    static TRAILING: std::sync::LazyLock<regex::Regex> = std::sync::LazyLock::new(|| {
        regex::Regex::new(r"\s+at line \d+,? column \d+$").expect("valid regex")
    });
    TRAILING.replace(first_line, "").into_owned()
}

/// A readable message for a breached parser budget (`budget breached: Nodes { .. }`).
fn budget_message(breach: &str) -> String {
    let budget = Budget::default();
    let name = breach.split([' ', '{']).next().unwrap_or(breach);
    match name {
        "Depth" => format!("document nests deeper than {MAX_DEPTH} levels"),
        "Nodes" => format!(
            "document has more than {} nodes; each use of a YAML alias counts again",
            budget.max_nodes
        ),
        "Aliases" => format!(
            "document uses YAML aliases more than {} times",
            budget.max_aliases
        ),
        "Anchors" => format!(
            "document defines more than {} YAML anchors",
            budget.max_anchors
        ),
        "Events" => format!(
            "document is too large to parse (more than {} parser events)",
            budget.max_events
        ),
        other => format!("document exceeds a parser limit ({other})"),
    }
}

/// `serde_json` says "key must be a string" for both an unquoted key and a trailing
/// comma in an object; name both.
fn json_message(raw: &str) -> String {
    let message = strip_position(raw);
    if message == "key must be a string" {
        return "expected a quoted key; JSON does not allow a trailing comma".to_owned();
    }
    message
}

/// One-line, developer-facing message without parser internals.
fn clean_message(raw: &str) -> String {
    let message = strip_position(raw.lines().next().unwrap_or(raw));
    if let Some(rest) = message.strip_prefix("duplicate mapping key: ") {
        let key = rest.split(", set ").next().unwrap_or(rest);
        return format!("duplicate mapping key `{key}`");
    }
    if let Some(breach) = message.strip_prefix("budget breached: ") {
        return budget_message(breach);
    }
    // Mapping keys are read as strings, so this is a `null:`, `~:` or empty key.
    if message.starts_with("cannot deserialize null into string") {
        return "a mapping key is null; write a name, or quote it (`\"null\"`) if the text null is meant".to_owned();
    }
    message
}

#[cfg(test)]
mod tests {
