        assert_eq!(docs.len(), 2);
    }

    #[test]
    fn json_trailing_comma_reports_line_and_offset() {
        let e = parse_documents("{\"a\":1,\n}\n", true).unwrap_err();
        assert_eq!(e.line, 2);
        assert_eq!(e.offset, 8, "start of line 2");
    }

    #[test]
    fn yaml_1_1_booleans_stay_strings() {
        let docs = parse_documents("a: yes\n", false).unwrap();
        assert_eq!(docs[0].to_value()["a"], "yes");
    }

    #[test]
    fn duplicate_keys_are_an_error_without_the_position_suffix() {
        let e = parse_documents("a: 1\na: 2\n", false).unwrap_err();
        assert!(!e.message.contains(" at line "), "{}", e.message);
        assert_eq!(e.line, 2);
    }

    #[test]
    fn depth_budget_message_names_the_limit() {
        let mut text = String::new();
        for depth in 0..40 {
            text.push_str(&"  ".repeat(depth));
            text.push_str(
                "a:
",
            );
        }
        let e = parse_documents(&text, false).unwrap_err();
        assert_eq!(e.message, "document nests deeper than 32 levels");
    }

    /// WR-08: only a trailing position is stripped.
    #[test]
    fn only_the_trailing_position_is_stripped() {
        assert_eq!(strip_position("bad at line 3, column 4"), "bad");
        assert_eq!(strip_position("bad at line 3 column 4"), "bad");
        let inner = "x (defined at line 9, column 9) y";
        assert_eq!(strip_position(inner), inner);
    }

    /// WR-08: an alias bomb names the node budget instead of a cut debug message.
    #[test]
    fn node_budget_message_is_readable() {
        use std::fmt::Write as _;
        let mut text = String::from("a: &a [x, x, x, x, x, x, x, x, x, x]\n");
        for (name, prev) in [("b", "a"), ("c", "b"), ("d", "c"), ("e", "d"), ("f", "e")] {
            let refs = vec![format!("*{prev}"); 10].join(", ");
            writeln!(text, "{name}: &{name} [{refs}]").unwrap();
        }
        let e = parse_documents(&text, false).unwrap_err();
        assert!(e.message.contains("nodes"), "{}", e.message);
        assert!(!e.message.contains("budget breached"), "{}", e.message);
        assert!(!e.message.contains("(used"), "{}", e.message);
    }

    /// WR-08: a null mapping key does not mention Rust types.
    #[test]
    fn null_key_message_has_no_rust_types() {
        let e = parse_documents("null: 1\n", false).unwrap_err();
        assert!(e.message.contains("null"), "{}", e.message);
        assert!(!e.message.contains("Option<"), "{}", e.message);
    }

    #[test]
    fn nesting_beyond_the_budget_is_an_error() {
        let mut text = String::new();
        for depth in 0..100 {
            text.push_str(&"  ".repeat(depth));
            text.push_str("a:\n");
        }
        assert!(parse_documents(&text, false).is_err());
    }
}

//! Loading a scope directory: roles and role bindings (D-01).
//!
//! The pipeline is the ontology loader's: size and file-count budgets, path safety,
//! the large-stack thread, the span-carrying parser and `kind` dispatch, so a scope
//! error carries the same file, line and column as an ontology error. A scope
//! directory has no manifest. Checks that need the ontology (does the type, property
//! or action exist) are not made here.

use std::collections::HashSet;

use camino::Utf8Path;

use super::dispatch::{Ctx, dispatch_scope};
use super::parse::{self, Node};
use super::sourcemap::{DefKey, DefKind, FileId, Part, Seg};
use super::{
    Listing, MAX_FILES, MAX_TOTAL_BYTES, SourceMap, Text, discover, internal_error_diagnostic,
    isolated, memory_files, read_memory, read_text,
};
use crate::diag::{Diagnostic, Severity, codes, did_you_mean, has_errors, sort_diagnostics};
use crate::ir::{Role, RoleBinding, RoleName, ScopeDefinition, ScopeSet, Subject};

#[derive(Debug)]
pub struct ScopeLoadOutput {
    /// `Some` only when no error was found.
    pub scope: Option<ScopeSet>,
    pub sources: SourceMap,
    pub diagnostics: Vec<Diagnostic>,
}

/// Load every YAML and JSON file below `root` as scope documents.
pub fn load_scope_dir(root: &Utf8Path) -> ScopeLoadOutput {
    isolated(internal_error, || {
        let (candidates, diagnostics) = discover::walk(root);
        let listing = Listing {
            candidates,
            diagnostics,
        };
        assemble_scope(listing, &|name| read_text(root, name))
    })
}

/// Same pipeline over in-memory files; paths use `/` (`\` is accepted) and are the
/// diagnostic `file`s.
pub fn load_scope_from_memory(files: &[(&str, &str)]) -> ScopeLoadOutput {
    isolated(internal_error, || {
        let by_path = memory_files(files);
        let listing = Listing {
            candidates: by_path.keys().cloned().collect(),
            diagnostics: Vec::new(),
        };
        assemble_scope(listing, &|name| read_memory(&by_path, name))
    })
}

fn internal_error() -> ScopeLoadOutput {
    ScopeLoadOutput {
        scope: None,
        sources: SourceMap::default(),
        diagnostics: vec![internal_error_diagnostic(".")],
    }
}

fn assemble_scope(listing: Listing, read: &dyn Fn(&str) -> Text) -> ScopeLoadOutput {
    let mut sources = SourceMap::default();
    let mut diags = listing.diagnostics;
    let files = discover::select_scope(listing.candidates);

    if files.is_empty() && diags.is_empty() {
        diags.push(
            Diagnostic::without_location(
                codes::V14,
                Severity::Error,
                "no scope documents found",
                ".",
            )
            .with_help("add `.yaml`, `.yml` or `.json` files holding `kind: Role` and `kind: RoleBinding` documents"),
        );
    }
    if files.len() > MAX_FILES {
        diags.push(Diagnostic::without_location(
            codes::V14,
            Severity::Error,
            format!(
                "the scope directory holds {} files, more than the {MAX_FILES} it may have; only the first {MAX_FILES} were read",
                files.len()
            ),
            ".",
        ));
    }

    let mut scope = ScopeSet::default();
    let mut total: u64 = 0;
    for path in files.into_iter().take(MAX_FILES) {
        let text = match read(&path) {
            Ok(t) => t,
            Err(d) => {
                diags.push(d);
                continue;
            }
        };
        total += text.len() as u64;
        if total > MAX_TOTAL_BYTES {
            diags.push(Diagnostic::without_location(
                codes::V14,
                Severity::Error,
                format!(
                    "scope files exceed the {MAX_TOTAL_BYTES} byte budget; this file and the ones after it were not read"
                ),
                path,
            ));
            break;
        }
        let parsed = parse::parse_documents(&text, discover::is_json_file(&path));
        let file = sources.add_file(&path, text);
        match parsed {
            Err(e) => diags.push(super::syntax_diagnostic(&sources, file, &e)),
            Ok(docs) => {
                for doc in docs {
                    merge_scope(&mut sources, file, doc, &mut scope, &mut diags);
                }
            }
        }
    }

    check_bound_roles_exist(&sources, &scope, &mut diags);
    sort_diagnostics(&mut diags);
    let scope = (!has_errors(&diags)).then_some(scope);
    ScopeLoadOutput {
        scope,
        sources,
        diagnostics: diags,
    }
}

fn merge_scope(
    sources: &mut SourceMap,
    file: FileId,
    doc: Node,
    scope: &mut ScopeSet,
    diags: &mut Vec<Diagnostic>,
) {
    let def = match dispatch_scope(&doc, &Ctx { file, sources }) {
        Ok(d) => d,
        Err(d) => {
            diags.push(d);
            return;
        }
    };
    match def {
        ScopeDefinition::Role(role) => merge_role(sources, file, doc, role, scope, diags),
        ScopeDefinition::RoleBinding(binding) => {
            merge_binding(sources, file, doc, binding, scope, diags);
        }
    }
}

fn merge_role(
    sources: &mut SourceMap,
    file: FileId,
    doc: Node,
    role: Role,
    scope: &mut ScopeSet,
    diags: &mut Vec<Diagnostic>,
) {
    let key = DefKey {
        kind: DefKind::Role,
        api_name: role.api_name.to_string(),
    };
    let name_path = [Seg::Key("apiName".into())];
    if scope.roles.contains_key(&role.api_name) {
        let first = sources.locate(&key, &name_path, Part::Value);
        let at = sources.locate_in(file, &doc, &name_path, Part::Value);
        diags.push(Diagnostic::error(
            codes::V08,
            format!(
                "duplicate Role `{}`; first defined at {}:{}:{}",
                key.api_name, first.file, first.line, first.column
            ),
            &at,
        ));
        return;
    }
    sources.register_def(key, file, doc);
    scope.roles.insert(role.api_name.clone(), role);
}

fn merge_binding(
    sources: &mut SourceMap,
    file: FileId,
    doc: Node,
    binding: RoleBinding,
    scope: &mut ScopeSet,
    diags: &mut Vec<Diagnostic>,
) {
    diags.extend(subject_errors(sources, file, &doc, &binding));
    let key = DefKey {
        kind: DefKind::RoleBinding,
        api_name: binding.role.to_string(),
    };
    let role_path = [Seg::Key("role".into())];
    if scope.bindings.contains_key(&binding.role) {
        let first = sources.locate(&key, &role_path, Part::Value);
        let at = sources.locate_in(file, &doc, &role_path, Part::Value);
        diags.push(
            Diagnostic::error(
                codes::V08,
                format!(
                    "a second RoleBinding for role `{}`; first defined at {}:{}:{}",
                    key.api_name, first.file, first.line, first.column
                ),
                &at,
            )
            .with_help("list all subjects of a role in one RoleBinding"),
        );
        return;
    }
    sources.register_def(key, file, doc);
    scope.bindings.insert(binding.role.clone(), binding);
}

/// Structure rules for the subjects of one binding (D-02, D-04): at least one, no
/// repeats, a user is `<iss>|<sub>`, a group has a name.
fn subject_errors(
    sources: &SourceMap,
    file: FileId,
    doc: &Node,
    binding: &RoleBinding,
) -> Vec<Diagnostic> {
    let at = |path: &[Seg]| sources.locate_in(file, doc, path, Part::Value);
    let subjects = || Seg::Key("subjects".into());
    if binding.subjects.is_empty() {
        return vec![
            Diagnostic::error(
                codes::V21,
                format!("RoleBinding for `{}` has no subjects", binding.role),
                &at(&[subjects()]),
            )
            .with_help("list at least one `user: \"<iss>|<sub>\"` or `group: <name>`"),
        ];
    }
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    for (i, subject) in binding.subjects.iter().enumerate() {
        let key = match subject {
            Subject::User(_) => "user",
            Subject::Group(_) => "group",
        };
        if let Some((message, help)) = subject_problem(subject) {
            let path = [subjects(), Seg::Index(i), Seg::Key(key.into())];
            out.push(Diagnostic::error(codes::V21, message, &at(&path)).with_help(help));
        } else if !seen.insert(subject) {
            let path = [subjects(), Seg::Index(i)];
            out.push(
                Diagnostic::error(
                    codes::V21,
                    format!(
                        "duplicate subject in the RoleBinding for `{}`",
                        binding.role
                    ),
                    &at(&path),
                )
                .with_help("remove the repeated entry"),
            );
        }
    }
    out
}

/// What is wrong with a single subject, as a message and a help text.
fn subject_problem(subject: &Subject) -> Option<(String, &'static str)> {
    match subject {
        Subject::User(user) => {
            if user.chars().any(char::is_control) {
                return Some((
                    "a user subject contains a control character".to_owned(),
                    "a user is a principal id such as `ontoforge-dev|mia`",
                ));
            }
            let mut parts = user.split('|');
            let well_formed = matches!(
                (parts.next(), parts.next(), parts.next()),
                (Some(iss), Some(sub), None) if !iss.is_empty() && !sub.is_empty()
            );
            (!well_formed).then(|| {
                (
                    format!("user `{user}` is not a principal id `<iss>|<sub>`"),
                    "write the issuer and the subject separated by one `|`, for example `ontoforge-dev|mia`",
                )
            })
        }
        Subject::Group(group) => {
            if group.trim().is_empty() {
                Some((
                    "a group subject has an empty name".to_owned(),
                    "name the group as it appears in the token's `groups` claim",
                ))
            } else if group.chars().any(char::is_control) {
                Some((
                    "a group subject contains a control character".to_owned(),
                    "name the group as it appears in the token's `groups` claim",
                ))
            } else {
                None
            }
        }
    }
}

/// A binding must name a role defined somewhere in the directory. Checked after all
/// files are read, because the role may sit in a later file.
fn check_bound_roles_exist(sources: &SourceMap, scope: &ScopeSet, diags: &mut Vec<Diagnostic>) {
    for role in scope.bindings.keys() {
        if scope.roles.contains_key(role) {
            continue;
        }
        let key = DefKey {
            kind: DefKind::RoleBinding,
            api_name: role.to_string(),
        };
        let at = sources.locate(&key, &[Seg::Key("role".into())], Part::Value);
        let help = did_you_mean(role.as_str(), scope.roles.keys().map(RoleName::as_str))
            .map_or_else(
                || format!("define a `kind: Role` with `apiName: {role}`"),
                |s| format!("did you mean `{s}`?"),
            );
        diags.push(
            Diagnostic::error(
                codes::V21,
                format!("RoleBinding refers to role `{role}`, which is not defined"),
                &at,
            )
            .with_help(help),
        );
    }
}

//! Source text and span lookup, kept apart from the IR.
//!
//! The IR carries no positions; validation and lint ask the [`SourceMap`] where a
//! definition's field lives, by definition key and path.

use std::collections::HashMap;

use serde_saphyr::Location;

use super::parse::{Kind, Node};
use crate::diag::SourceLocation;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct FileId(usize);

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum DefKind {
    ObjectType,
    LinkType,
    ActionType,
    /// Registered under `{profile}/{target}` ([`crate::ir::binding_def_name`]).
    SourceBinding,
    /// Scope documents (D-01).
    Role,
    /// Registered under the name of the role it binds.
    RoleBinding,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct DefKey {
    pub kind: DefKind,
    pub api_name: String,
}

/// One step of a path through the original document (the `kind` field included,
/// no rewrite wrapper).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Seg {
    Key(String),
    Index(usize),
}

/// Whether a location should point at a mapping key or at its value.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Part {
    Key,
    Value,
}

#[derive(Debug)]
struct SourceFile {
    path: String,
    text: String,
}

#[derive(Debug)]
struct Entry {
    file: FileId,
    node: Node,
}

/// The column names a binding's fixture declares, or why they could not be read. The
/// reason names a structural problem and never repeats data from the file.
pub type FixtureColumns = Result<Vec<String>, String>;

#[derive(Debug, Default)]
pub struct SourceMap {
    files: Vec<SourceFile>,
    defs: HashMap<DefKey, Entry>,
    manifest: Option<Entry>,
    /// Fixture headers by binding definition name ([`crate::ir::binding_def_name`]).
    fixture_columns: HashMap<String, FixtureColumns>,
}

impl SourceMap {
    /// Register a file's text (also used for files that hold no definitions).
    pub fn add_file(&mut self, path: &str, text: String) -> FileId {
        self.files.push(SourceFile {
            path: path.to_owned(),
            text,
        });
        FileId(self.files.len() - 1)
    }

    /// The path a file was registered under.
    pub(crate) fn path(&self, file: FileId) -> &str {
        &self.files[file.0].path
    }

    pub fn text(&self, path: &str) -> Option<&str> {
        self.files
            .iter()
            .find(|f| f.path == path)
            .map(|f| f.text.as_str())
    }

    pub(crate) fn register_def(&mut self, key: DefKey, file: FileId, node: Node) {
        self.defs.insert(key, Entry { file, node });
    }

    pub(crate) fn set_manifest(&mut self, file: FileId, node: Node) {
        self.manifest = Some(Entry { file, node });
    }

    /// Record the header of the fixture of the binding named `def_name`.
    pub(crate) fn set_fixture_columns(&mut self, def_name: String, columns: FixtureColumns) {
        self.fixture_columns.insert(def_name, columns);
    }

    /// The header of the fixture of the binding named `def_name` (`{profile}/{target}`):
    /// `None` when the binding has no fixture or its header was not looked at.
    pub fn fixture_columns(&self, def_name: &str) -> Option<&FixtureColumns> {
        self.fixture_columns.get(def_name)
    }

    /// Where `path` of the definition `def` lives. A path that does not exist
    /// resolves to its nearest existing ancestor.
    pub fn locate(&self, def: &DefKey, path: &[Seg], part: Part) -> SourceLocation {
        match self.defs.get(def) {
            Some(e) => self.locate_in(e.file, &e.node, path, part),
            None => Self::unknown(),
        }
    }

    pub fn locate_manifest(&self, path: &[Seg], part: Part) -> SourceLocation {
        match &self.manifest {
            Some(e) => self.locate_in(e.file, &e.node, path, part),
            None => Self::unknown(),
        }
    }

    /// Resolve `path` inside a node that may not be registered yet.
    pub(crate) fn locate_in(
        &self,
        file: FileId,
        root: &Node,
        path: &[Seg],
        part: Part,
    ) -> SourceLocation {
        self.location(file, resolve(root, path, part))
    }

    pub(crate) fn location(&self, file: FileId, loc: Location) -> SourceLocation {
        let span = loc.span();
        let to_usize = |v: Option<u64>| v.and_then(|v| usize::try_from(v).ok());
        self.raw_location(
            file,
            loc.line(),
            loc.column(),
            to_usize(span.byte_offset()).unwrap_or(0),
            to_usize(span.byte_len()).unwrap_or(1),
        )
    }

    /// Build a location, clamping the span to the file text.
    pub(crate) fn raw_location(
        &self,
        file: FileId,
        line: u64,
        column: u64,
        offset: usize,
        length: usize,
    ) -> SourceLocation {
        let f = &self.files[file.0];
        let offset = offset.min(f.text.len());
        let length = length.clamp(1, f.text.len().saturating_sub(offset).max(1));
        SourceLocation {
            file: f.path.clone(),
            line: u32::try_from(line).unwrap_or(u32::MAX),
            column: u32::try_from(column).unwrap_or(u32::MAX),
            offset,
            length,
        }
    }

    /// A position-less location in `file`, for problems with a whole file.
    pub(crate) fn whole_file(&self, file: FileId) -> SourceLocation {
        SourceLocation {
            file: self.files[file.0].path.clone(),
            line: 0,
            column: 0,
            offset: 0,
            length: 0,
        }
    }

    fn unknown() -> SourceLocation {
        SourceLocation {
            file: String::new(),
            line: 0,
            column: 0,
            offset: 0,
            length: 0,
        }
    }
}

/// Walk `path` down a node tree. On a missing step the walk stops at the nearest
/// existing ancestor. Also returns the key location of the last step taken.
pub(crate) fn walk<'a>(root: &'a Node, path: &[Seg]) -> (&'a Node, Option<Location>) {
    let mut cur = root;
    let mut key_loc: Option<Location> = None;
    for seg in path {
        match (seg, &cur.kind) {
            (Seg::Key(k), Kind::Map(entries)) => {
                match entries.iter().find(|(ek, _)| &ek.value == k) {
                    Some((ek, v)) => {
                        key_loc = Some(ek.referenced);
                        cur = v;
                    }
                    None => break,
                }
            }
            (Seg::Index(i), Kind::Seq(items)) => match items.get(*i) {
                Some(v) => {
                    key_loc = None;
                    cur = v;
                }
                None => break,
            },
            _ => break,
        }
    }
    (cur, key_loc)
}

pub(crate) fn resolve(root: &Node, path: &[Seg], part: Part) -> Location {
    let (node, key_loc) = walk(root, path);
    match part {
        Part::Key => key_loc.unwrap_or(node.loc),
        Part::Value => node.loc,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::loader::parse::parse_documents;

    fn map_with(text: &str) -> (SourceMap, DefKey) {
        let mut sm = SourceMap::default();
        let id = sm.add_file("a.yaml", text.to_owned());
        let doc = parse_documents(text, false).unwrap().remove(0);
        let key = DefKey {
            kind: DefKind::ObjectType,
            api_name: "Flight".into(),
        };
        sm.register_def(key.clone(), id, doc);
        (sm, key)
    }

    const TEXT: &str = "kind: ObjectType\napiName: Flight\nproperties:\n  id: { type: string }\n  tags:\n    - one\n";

    #[test]
    fn key_and_value_parts_differ() {
        let (sm, k) = map_with(TEXT);
        let path = [Seg::Key("apiName".into())];
        let key = sm.locate(&k, &path, Part::Key);
        let value = sm.locate(&k, &path, Part::Value);
        assert_eq!((key.file.as_str(), key.line, key.column), ("a.yaml", 2, 1));
        assert_eq!((value.line, value.column), (2, 10));
        assert_eq!(&TEXT[value.offset..value.offset + value.length], "Flight");
        assert_eq!(&TEXT[key.offset..key.offset + key.length], "apiName");
    }

    #[test]
    fn nested_keys_and_sequence_indexes_resolve() {
        let (sm, k) = map_with(TEXT);
        let prop = [Seg::Key("properties".into()), Seg::Key("id".into())];
        assert_eq!(sm.locate(&k, &prop, Part::Key).line, 4);
        let item = [
            Seg::Key("properties".into()),
            Seg::Key("tags".into()),
            Seg::Index(0),
        ];
        assert_eq!(sm.locate(&k, &item, Part::Value).line, 6);
    }

    #[test]
    fn missing_path_falls_back_to_the_nearest_ancestor() {
        let (sm, k) = map_with(TEXT);
        let path = [Seg::Key("properties".into()), Seg::Key("nope".into())];
        assert_eq!(sm.locate(&k, &path, Part::Value).line, 4);
        assert_eq!(sm.locate(&k, &path, Part::Key).line, 3);
    }

    #[test]
    fn multibyte_values_report_byte_offsets_and_char_columns() {
        let text = "apiName: 航班\nx: 1\n";
        let (sm, k) = map_with(text);
        let v = sm.locate(&k, &[Seg::Key("apiName".into())], Part::Value);
        assert_eq!(v.column, 10);
        assert_eq!(&text[v.offset..v.offset + v.length], "航班");
    }

    #[test]
    fn text_is_available_by_path() {
        let (sm, _) = map_with(TEXT);
        assert_eq!(sm.text("a.yaml"), Some(TEXT));
        assert_eq!(sm.text("b.yaml"), None);
    }
}

//! JSON Schema export for editors and LLM generation (SCHEMA-07).
//!
//! The schemas are derived from the IR types, so the format an editor completes
//! against is the format the loader accepts. The committed copies under `schemas/`
//! are checked against this output by a test.

use schemars::{JsonSchema, schema_for};
use serde_json::{Value, json};

use crate::ir::{Definition, Manifest, ScopeDefinition};

/// A definition file holds one document or, for JSON, an array of them. Export-only:
/// the loader never deserializes this type.
#[derive(JsonSchema)]
#[serde(untagged)]
#[allow(dead_code)]
enum DefinitionFile {
    One(Box<Definition>),
    Many(Vec<Definition>),
}

/// A scope file holds one document or, for JSON, an array of them. Export-only, like
/// [`DefinitionFile`].
#[derive(JsonSchema)]
#[serde(untagged)]
#[allow(dead_code)]
enum ScopeFile {
    One(Box<ScopeDefinition>),
    Many(Vec<ScopeDefinition>),
}

fn with_header(mut schema: Value, title: &str, description: &str) -> Value {
    let root = schema
        .as_object_mut()
        .expect("a derived root schema is an object");
    root.insert("title".to_owned(), json!(title));
    root.insert("description".to_owned(), json!(description));
    schema
}

/// Replace the description of `$defs.<name>`: the IR doc comments of the two tagged
/// enums describe loader internals, which editor users should not see.
fn describe_def(schema: &mut Value, name: &str, description: &str) {
    if let Some(def) = schema
        .pointer_mut(&format!("/$defs/{name}"))
        .and_then(Value::as_object_mut)
    {
        def.insert("description".to_owned(), json!(description));
    }
}

/// Schema of one definition file: a single definition or an array of definitions.
pub fn definition_schema() -> Value {
    let mut schema = with_header(
        serde_json::to_value(schema_for!(DefinitionFile)).expect("schema serializes"),
        "ontoforge definition document",
        "An ObjectType, LinkType, ActionType or SourceBinding document (ADR-0012, ADR-0021), selected by its `kind`; \
         JSON files may hold an array of them.",
    );
    describe_def(
        &mut schema,
        "Definition",
        "One definition document: an ObjectType, LinkType, ActionType or SourceBinding, selected by `kind`.",
    );
    describe_def(
        &mut schema,
        "Rule",
        "One edit of an action, selected by `kind`. Rules run in list order.",
    );
    schema
}

/// Schema of `ontology.yaml`.
pub fn manifest_schema() -> Value {
    with_header(
        serde_json::to_value(schema_for!(Manifest)).expect("schema serializes"),
        "ontoforge ontology manifest",
        "The ontology.yaml manifest naming the ontology and listing definition files.",
    )
}

/// Schema of one scope file: a `Role` or `RoleBinding` document, or an array of them.
pub fn scope_schema() -> Value {
    let mut schema = with_header(
        serde_json::to_value(schema_for!(ScopeFile)).expect("schema serializes"),
        "ontoforge scope document",
        "A Role or RoleBinding document (ADR-0018, ADR-0019), selected by its `kind`. Scope documents live in their own directory, apart from the ontology definition and its SourceBinding files; JSON files may hold an array of them.",
    );
    describe_def(
        &mut schema,
        "ScopeDefinition",
        "One scope document: a Role or a RoleBinding, selected by `kind`.",
    );
    schema
}

/// File name and content of each exported schema; content is pretty JSON ending in a
/// newline and identical on every call.
pub fn rendered_schemas() -> Vec<(&'static str, String)> {
    let render = |schema: &Value| {
        let mut text = serde_json::to_string_pretty(schema).expect("schema serializes");
        text.push('\n');
        text
    };
    vec![
        (
            "ontoforge-definition.schema.json",
            render(&definition_schema()),
        ),
        ("ontoforge-manifest.schema.json", render(&manifest_schema())),
        ("ontoforge-scope.schema.json", render(&scope_schema())),
    ]
}

//! Action type structural checks (hard errors): references (V09) and parameter,
//! rule and value-source consistency (V12).
//!
//! A reference that does not resolve is reported once; the checks that need what
//! it points at are skipped so one typo does not produce a chain of errors.

use crate::diag::{Diagnostic, SourceLocation, codes, did_you_mean};
use crate::ir::basetype::{check_literal, widens_to};
use crate::ir::{
    ActionType, Backing, BaseType, CreateObjectRule, LinkRule, LinkTypeName, ModifyObjectRule,
    ObjectType, ObjectTypeName, Ontology, ParamType, ParameterName, PropertyDef, PropertyName,
    Rule, ValueSource,
};
use crate::loader::SourceMap;
use crate::loader::sourcemap::{DefKey, DefKind, Part, Seg};

struct Cx<'a> {
    ontology: &'a Ontology,
    action: &'a ActionType,
    key: DefKey,
    sources: &'a SourceMap,
}

impl Cx<'_> {
    fn at(&self, path: &[Seg], part: Part) -> SourceLocation {
        self.sources.locate(&self.key, path, part)
    }

    /// Location of `rules[i]` followed by the given keys.
    fn rule_at(&self, i: usize, rest: &[&str], part: Part) -> SourceLocation {
        let mut path = vec![key("rules"), Seg::Index(i)];
        path.extend(rest.iter().map(|s| key(s)));
        self.at(&path, part)
    }
}

fn key(name: &str) -> Seg {
    Seg::Key(name.to_owned())
}

pub fn check(ontology: &Ontology, sources: &SourceMap, out: &mut Vec<Diagnostic>) {
    for action in ontology.action_types.values() {
        let cx = Cx {
            ontology,
            action,
            key: DefKey {
                kind: DefKind::ActionType,
                api_name: action.api_name.to_string(),
            },
            sources,
        };
        parameters(&cx, out);
        criteria(&cx, out);
        if action.rules.is_empty() {
            out.push(
                Diagnostic::error(
                    codes::V12,
                    format!("action `{}` has no rules", action.api_name),
                    &cx.at(&[key("rules")], Part::Value),
                )
                .with_help("add at least one rule, for example `kind: createObject`"),
            );
        }
        for (i, rule) in action.rules.iter().enumerate() {
            match rule {
                Rule::CreateObject(r) => create_object(&cx, i, r, out),
                Rule::ModifyObject(r) => modify_object(&cx, i, r, out),
                Rule::DeleteObject(r) => {
                    object_param(&cx, i, &r.object, out);
                }
                Rule::ReleaseObject(r) => {
                    if let Some(object) = object_param(&cx, i, &r.object, out)
                        && object.backing != Backing::Source
                    {
                        out.push(Diagnostic::error(
                            codes::V12,
                            format!("releaseObject requires a source-backed object, but `{}` is editOnly", object.api_name),
                            &cx.rule_at(i, &["object"], Part::Value),
                        ));
                    }
                }
                Rule::AddLink(r) | Rule::RemoveLink(r) => link_rule(&cx, i, r, out),
            }
        }
    }
}

/// `d` with a "did you mean" help when `input` is close to one of `names`.
fn suggest<'a>(d: Diagnostic, input: &str, names: impl IntoIterator<Item = &'a str>) -> Diagnostic {
    match did_you_mean(input, names) {
        Some(s) => d.with_help(format!("did you mean `{s}`?")),
        None => d,
    }
}

fn type_name(t: BaseType, items: Option<BaseType>) -> String {
    match (t, items) {
        (BaseType::Array, Some(inner)) => format!("array of {}", inner.as_str()),
        _ => t.as_str().to_owned(),
    }
}

fn parameters(cx: &Cx, out: &mut Vec<Diagnostic>) {
    for (name, p) in &cx.action.parameters {
        let name = name.as_str();
        let at = |field: &str, part: Part| cx.at(&[key("parameters"), key(name), key(field)], part);
        let base = p.param_type.base_type();
        match (&p.param_type, base, p.items) {
            (ParamType::ObjectReference(target), _, _) => {
                if !cx.ontology.object_types.contains_key(target.as_str()) {
                    let here = cx.at(
                        &[
                            key("parameters"),
                            key(name),
                            key("type"),
                            key("objectReference"),
                        ],
                        Part::Value,
                    );
                    let d = Diagnostic::error(
                        codes::V09,
                        format!("parameter `{name}` refers to unknown object type `{target}`"),
                        &here,
                    );
                    let names = cx.ontology.object_types.keys().map(ObjectTypeName::as_str);
                    out.push(suggest(d, target.as_str(), names));
                }
            }
            (_, Some(BaseType::Array), None) => out.push(
                Diagnostic::error(
                    codes::V05,
                    format!("array parameter `{name}` must declare `items`"),
                    &at("type", Part::Value),
                )
                .with_help("add `items: <element type>`, for example `items: string`"),
            ),
            _ => {}
        }
        if p.items.is_some() && base != Some(BaseType::Array) {
            out.push(
                Diagnostic::error(
                    codes::V06,
                    format!(
                        "`items` is only allowed on array parameters, but `{name}` is not an array"
                    ),
                    &at("items", Part::Key),
                )
                .with_help("remove `items`, or change the type to `array`"),
            );
        }
        let Some(default) = &p.default else {
            continue;
        };
        match base {
            None => out.push(
                Diagnostic::error(
                    codes::V12,
                    format!("object reference parameter `{name}` cannot have a default"),
                    &at("default", Part::Value),
                )
                .with_help("remove `default`; callers must pass the object"),
            ),
            Some(t) => {
                if let Err(reason) = check_literal(default, t, p.items) {
                    out.push(Diagnostic::error(
                        codes::V12,
                        format!(
                            "default of parameter `{name}` is not a valid `{}` value: {reason}",
                            type_name(t, p.items)
                        ),
                        &at("default", Part::Value),
                    ));
                }
            }
        }
    }
}

fn criteria(cx: &Cx, out: &mut Vec<Diagnostic>) {
    for (i, c) in cx.action.submission_criteria.iter().enumerate() {
        for (field, text) in [
            ("condition", &c.condition),
            ("failureMessage", &c.failure_message),
        ] {
            if text.trim().is_empty() {
                let here = cx.at(
                    &[key("submissionCriteria"), Seg::Index(i), key(field)],
                    Part::Value,
                );
                out.push(Diagnostic::error(
                    codes::V12,
                    format!("submission criterion `{field}` must not be empty"),
                    &here,
                ));
            }
        }
    }
}

fn create_object(cx: &Cx, i: usize, r: &CreateObjectRule, out: &mut Vec<Diagnostic>) {
    let Some(object) = cx.ontology.object_types.get(r.object_type.as_str()) else {
        let d = Diagnostic::error(
            codes::V09,
            format!(
                "createObject refers to unknown object type `{}`",
                r.object_type
            ),
            &cx.rule_at(i, &["objectType"], Part::Value),
        );
        let names = cx.ontology.object_types.keys().map(ObjectTypeName::as_str);
        out.push(suggest(d, r.object_type.as_str(), names));
        return;
    };
    properties(cx, i, object, &r.properties, out);
    let missing: Vec<String> = object
        .properties
        .iter()
        .filter(|(name, p)| p.required || **name == object.primary_key)
        .filter(|(name, _)| !r.properties.contains_key(name.as_str()))
        .map(|(name, _)| format!("`{name}`"))
        .collect();
    if !missing.is_empty() {
        out.push(
            Diagnostic::error(
                codes::V12,
                format!(
                    "createObject of `{}` does not assign the primary key or required properties: {}",
                    object.api_name,
                    missing.join(", ")
                ),
                &cx.rule_at(i, &["properties"], Part::Key),
            )
            .with_help("add each missing property under `properties` with a value source"),
        );
    }
}

fn modify_object(cx: &Cx, i: usize, r: &ModifyObjectRule, out: &mut Vec<Diagnostic>) {
    let Some(object) = object_param(cx, i, &r.object, out) else {
        return;
    };
    for name in r.properties.keys() {
        if *name == object.primary_key {
            out.push(
                Diagnostic::error(
                    codes::V12,
                    format!(
                        "modifyObject cannot assign the primary key `{name}` of `{}`",
                        object.api_name
                    ),
                    &cx.rule_at(i, &["properties", name.as_str()], Part::Key),
                )
                .with_help("an action cannot change an object's primary key"),
            );
        }
    }
    properties(cx, i, object, &r.properties, out);
}

fn link_rule(cx: &Cx, i: usize, r: &LinkRule, out: &mut Vec<Diagnostic>) {
    let Some(link) = cx.ontology.link_types.get(r.link.as_str()) else {
        let d = Diagnostic::error(
            codes::V09,
            format!("rule refers to unknown link type `{}`", r.link),
            &cx.rule_at(i, &["link"], Part::Value),
        );
        let names = cx.ontology.link_types.keys().map(LinkTypeName::as_str);
        out.push(suggest(d, r.link.as_str(), names));
        return;
    };
    for (field, param, end) in [("from", &r.from, &link.from), ("to", &r.to, &link.to)] {
        let Some(target) = reference_param(cx, i, field, param, out) else {
            continue;
        };
        let exists = cx.ontology.object_types.contains_key(target.as_str());
        if exists && *target != end.object_type {
            out.push(Diagnostic::error(
                codes::V12,
                format!(
                    "parameter `{param}` references `{target}`, but the `{field}` end of link `{}` is `{}`",
                    link.api_name, end.object_type
                ),
                &cx.rule_at(i, &[field], Part::Value),
            ));
        }
    }
}

/// The object type a rule's `object` parameter refers to. Reports an unknown
/// parameter (V09) or one that is not an object reference (V12).
fn object_param<'a>(
    cx: &Cx<'a>,
    i: usize,
    name: &ParameterName,
    out: &mut Vec<Diagnostic>,
) -> Option<&'a ObjectType> {
    let target = reference_param(cx, i, "object", name, out)?;
    cx.ontology.object_types.get(target.as_str())
}

/// Resolve parameter `name`, written in field `field` of `rules[i]`, to the object
/// type it references.
fn reference_param<'a>(
    cx: &Cx<'a>,
    i: usize,
    field: &str,
    name: &ParameterName,
    out: &mut Vec<Diagnostic>,
) -> Option<&'a ObjectTypeName> {
    let here = || cx.rule_at(i, &[field], Part::Value);
    let Some(def) = cx.action.parameters.get(name.as_str()) else {
        let d = Diagnostic::error(
            codes::V09,
            format!("`{field}` refers to unknown parameter `{name}`"),
            &here(),
        );
        let names = cx.action.parameters.keys().map(ParameterName::as_str);
        out.push(suggest(d, name.as_str(), names));
        return None;
    };
    if let ParamType::ObjectReference(target) = &def.param_type {
        return Some(target);
    }
    out.push(
        Diagnostic::error(
            codes::V12,
            format!("parameter `{name}` must be an objectReference parameter"),
            &here(),
        )
        .with_help("declare it as `type: { objectReference: <ObjectType> }`"),
    );
    None
}

fn properties(
    cx: &Cx,
    i: usize,
    object: &ObjectType,
    assigned: &indexmap::IndexMap<PropertyName, ValueSource>,
    out: &mut Vec<Diagnostic>,
) {
    for (name, source) in assigned {
        let Some(prop) = object.properties.get(name.as_str()) else {
            let d = Diagnostic::error(
                codes::V09,
                format!("`{}` has no property `{name}`", object.api_name),
                &cx.rule_at(i, &["properties", name.as_str()], Part::Key),
            );
            let names = object.properties.keys().map(PropertyName::as_str);
            out.push(suggest(d, name.as_str(), names));
            continue;
        };
        value_source(cx, i, name, prop, source, out);
    }
}

fn value_source(
    cx: &Cx,
    i: usize,
    name: &PropertyName,
    prop: &PropertyDef,
    source: &ValueSource,
    out: &mut Vec<Diagnostic>,
) {
    let here = cx.rule_at(i, &["properties", name.as_str(), source.key()], Part::Value);
    let prop_type = type_name(prop.base_type, prop.items);
    match source {
        ValueSource::Param(param) => {
            let Some(def) = cx.action.parameters.get(param.as_str()) else {
                let d = Diagnostic::error(
                    codes::V09,
                    format!("`param` refers to unknown parameter `{param}`"),
                    &here,
                );
                let names = cx.action.parameters.keys().map(ParameterName::as_str);
                out.push(suggest(d, param.as_str(), names));
                return;
            };
            let Some(t) = def.param_type.base_type() else {
                out.push(
                    Diagnostic::error(
                        codes::V12,
                        format!(
                            "object reference parameter `{param}` cannot be assigned to property `{name}`"
                        ),
                        &here,
                    )
                    .with_help("pass the primary key as a `string` parameter instead"),
                );
                return;
            };
            if !compatible((t, def.items), (prop.base_type, prop.items)) {
                out.push(Diagnostic::error(
                    codes::V12,
                    format!(
                        "parameter `{param}` has type `{}`, but property `{name}` has type `{prop_type}`",
                        type_name(t, def.items)
                    ),
                    &here,
                ));
            }
        }
        ValueSource::Static(value) => {
            let reason = if value.is_null() {
                Some(
                    "a static value cannot be null; leave the property out to leave it unset"
                        .to_owned(),
                )
            } else {
                check_literal(value, prop.base_type, prop.items).err()
            };
            if let Some(reason) = reason {
                out.push(Diagnostic::error(
                    codes::V12,
                    format!(
                        "static value for property `{name}` (`{prop_type}`) is invalid: {reason}"
                    ),
                    &here,
                ));
            }
        }
        ValueSource::CurrentUser(_) if prop.base_type != BaseType::String => {
            out.push(Diagnostic::error(
                codes::V12,
                format!("`currentUser` can only be assigned to a string property, but `{name}` is `{prop_type}`"),
                &here,
            ));
        }
        ValueSource::CurrentTime(_) if prop.base_type != BaseType::Timestamp => {
            out.push(Diagnostic::error(
                codes::V12,
                format!("`currentTime` can only be assigned to a timestamp property, but `{name}` is `{prop_type}`"),
                &here,
            ));
        }
        ValueSource::CurrentUser(_) | ValueSource::CurrentTime(_) => {}
    }
}

/// Whether a value of type `from` can be assigned to a property of type `to`:
/// numbers only widen ([`widens_to`]); arrays also compare their element types.
fn compatible(from: (BaseType, Option<BaseType>), to: (BaseType, Option<BaseType>)) -> bool {
    if !widens_to(from.0, to.0) {
        return false;
    }
    match (from.1, to.1) {
        (Some(a), Some(b)) => widens_to(a, b),
        _ => true,
    }
}

//! Source binding checks (hard errors): the target exists (V09), it may be bound at
//! all (V16), and the selected profile binds every source-backed type (V16).

use crate::diag::{Diagnostic, Severity, SourceLocation, codes, did_you_mean};
use crate::ir::{
    Backing, BindingTarget, BoundColumn, Cardinality, LinkTypeName, ObjectTypeName, Ontology,
    ProfileName, PropertyName, SourceBinding, binding_def_name,
};
use crate::loader::sourcemap::{DefKey, DefKind, Part, Seg};
use crate::loader::{MANIFEST, SourceMap, fixture_path};

type At<'a> = dyn Fn(&[&str], Part) -> SourceLocation + 'a;

/// Every binding of every profile, objects before links.
fn all_bindings(ontology: &Ontology) -> impl Iterator<Item = (&ProfileName, &SourceBinding)> {
    ontology.bindings.iter().flat_map(|(profile, bound)| {
        bound
            .objects
            .values()
            .chain(bound.links.values())
            .map(move |binding| (profile, binding))
    })
}

fn locate<'a>(
    sources: &'a SourceMap,
    key: &'a DefKey,
) -> impl Fn(&[&str], Part) -> SourceLocation + 'a {
    move |path: &[&str], part: Part| {
        let path: Vec<Seg> = path.iter().map(|s| Seg::Key((*s).to_owned())).collect();
        sources.locate(key, &path, part)
    }
}

/// Checks that need no profile selection; they run while loading.
pub fn check(ontology: &Ontology, sources: &SourceMap, out: &mut Vec<Diagnostic>) {
    for (profile, binding) in all_bindings(ontology) {
        let key = DefKey {
            kind: DefKind::SourceBinding,
            api_name: binding_def_name(profile, binding.target_name()),
        };
        let at = locate(sources, &key);
        if target_exists(ontology, profile, binding, &at, out) {
            may_be_bound(ontology, binding, &at, out);
            column_keys(ontology, binding, &at, out);
            distinct_columns(ontology, binding, &at, out);
        }
        physical_names(binding, &at, out);
        time_zones(binding, &at, out);
        fixture_reference(binding, &at, out);
    }
}

/// Fixture existence and size, per binding, through `probe` (metadata only: the
/// content is never read here). A fixture path that is itself invalid was already
/// reported by [`check`] and is skipped.
pub(crate) fn check_fixture_files(
    ontology: &Ontology,
    sources: &SourceMap,
    probe: &dyn Fn(&str) -> Result<u64, String>,
) -> Vec<Diagnostic> {
    let mut out = Vec::new();
    for (profile, binding) in all_bindings(ontology) {
        let Some(fixture) = &binding.fixture else {
            continue;
        };
        let key = DefKey {
            kind: DefKind::SourceBinding,
            api_name: binding_def_name(profile, binding.target_name()),
        };
        let at = locate(sources, &key);
        let Ok(resolved) = fixture_path(&at(&[], Part::Value).file, &fixture.file) else {
            continue;
        };
        if let Err(reason) = probe(&resolved) {
            out.push(Diagnostic::error(
                codes::V16,
                format!("fixture `{resolved}`: {reason}"),
                &at(&["fixture", "file"], Part::Value),
            ));
        }
    }
    out
}

/// `columns` keys: property names for an object type, exactly `from` and `to` for a
/// link (D-03).
fn column_keys(ontology: &Ontology, binding: &SourceBinding, at: &At, out: &mut Vec<Diagnostic>) {
    match &binding.target {
        BindingTarget::ObjectType(name) => {
            let Some(object) = ontology.object_types.get(name.as_str()) else {
                return;
            };
            for key in binding.columns.keys() {
                if object.properties.contains_key(key.as_str()) {
                    continue;
                }
                let d = Diagnostic::error(
                    codes::V09,
                    format!(
                        "`{key}` is not a property of `{name}`, so it cannot be mapped to a column"
                    ),
                    &at(&["columns", key], Part::Key),
                );
                let candidates = object.properties.keys().map(PropertyName::as_str);
                out.push(match did_you_mean(key, candidates) {
                    Some(s) => d.with_help(format!("did you mean `{s}`?")),
                    None => d,
                });
            }
        }
        BindingTarget::LinkType(name) => {
            for end in LINK_ENDS {
                // `from: {}` names no column either: the end would fall back to a column
                // literally named `from` (WR-S03).
                if binding
                    .columns
                    .get(end)
                    .and_then(|c| c.column.as_deref())
                    .is_none()
                {
                    out.push(
                        Diagnostic::error(
                            codes::V16,
                            format!("the binding of link `{name}` must map the `{end}` end to a column"),
                            &at(&["columns"], Part::Value),
                        )
                        .with_help(format!(
                            "add `columns: {{ {end}: {{ column: <column holding the {end} key> }} }}`"
                        )),
                    );
                }
            }
            for key in binding.columns.keys() {
                if !LINK_ENDS.contains(&key.as_str()) {
                    out.push(
                        Diagnostic::error(
                            codes::V09,
                            format!("`{key}` is not an end of link `{name}`"),
                            &at(&["columns", key], Part::Key),
                        )
                        .with_help("a link binding maps only `from` and `to`"),
                    );
                }
            }
        }
    }
}

/// The two ends of a link binding, in the order columns are derived.
const LINK_ENDS: [&str; 2] = ["from", "to"];

/// V16 when two keys read the same physical column (compared in lower case, as the
/// engines do). The engine would give both the type of the first, silently (WR-S04).
/// Points at the explicit `column` of the pair, the later one when both are explicit.
fn distinct_columns(
    ontology: &Ontology,
    binding: &SourceBinding,
    at: &At,
    out: &mut Vec<Diagnostic>,
) {
    let mut seen: std::collections::HashMap<String, BoundColumn<'_>> =
        std::collections::HashMap::new();
    for c in ontology.bound_columns(binding) {
        let Some(first) = seen.get(&c.column.to_lowercase()).copied() else {
            seen.insert(c.column.to_lowercase(), c);
            continue;
        };
        let here = if c.explicit {
            at(&["columns", c.key, "column"], Part::Value)
        } else if first.explicit {
            at(&["columns", first.key, "column"], Part::Value)
        } else {
            at(&["target"], Part::Value)
        };
        out.push(
            Diagnostic::error(
                codes::V16,
                format!(
                    "`{}` and `{}` are both read from column `{}`",
                    first.key, c.key, c.column
                ),
                &here,
            )
            .with_help("map each key to a column of its own"),
        );
    }
}

/// Catalog, schema, table and column names must be non-empty text without control
/// characters (T-02-09). They are quoted when printed; this keeps them readable.
fn physical_names(binding: &SourceBinding, at: &At, out: &mut Vec<Diagnostic>) {
    let mut check = |what: &str, value: &str, path: &[&str]| {
        let problem = if value.is_empty() {
            "must not be empty"
        } else if value.chars().any(char::is_control) {
            "must not contain control characters"
        } else {
            return;
        };
        out.push(Diagnostic::error(
            codes::V16,
            format!("`{what}` {problem}"),
            &at(path, Part::Value),
        ));
    };
    check("catalog", &binding.source.catalog, &["source", "catalog"]);
    check("schema", &binding.source.schema, &["source", "schema"]);
    check("table", &binding.source.table, &["source", "table"]);
    for (key, mapping) in &binding.columns {
        if let Some(column) = &mapping.column {
            check("column", column, &["columns", key, "column"]);
        }
    }
}

/// A `timezone` is an IANA name or `aware`. Whether a timestamp property needs one is
/// lint territory (E14).
fn time_zones(binding: &SourceBinding, at: &At, out: &mut Vec<Diagnostic>) {
    for (key, mapping) in &binding.columns {
        let Some(zone) = &mapping.timezone else {
            continue;
        };
        if zone == AWARE || zone.parse::<chrono_tz::Tz>().is_ok() {
            continue;
        }
        out.push(
            Diagnostic::error(
                codes::V16,
                format!("`{zone}` is not an IANA time zone name or `aware`"),
                &at(&["columns", key, "timezone"], Part::Value),
            )
            .with_help(
                "write a name such as `Europe/Berlin`, or `aware` when the column already carries a time zone",
            ),
        );
    }
}

/// Timezone value for a column that already carries its zone.
const AWARE: &str = "aware";

/// The fixture path must stay inside the ontology directory and name a `.csv` or
/// `.json` file (T-02-07). Existence is checked by [`check_fixture_files`].
fn fixture_reference(binding: &SourceBinding, at: &At, out: &mut Vec<Diagnostic>) {
    let Some(fixture) = &binding.fixture else {
        return;
    };
    if let Err(reason) = fixture_path(&at(&[], Part::Value).file, &fixture.file) {
        out.push(Diagnostic::error(
            codes::V16,
            format!("fixture file `{}` cannot be used: {reason}", fixture.file),
            &at(&["fixture", "file"], Part::Value),
        ));
    }
}

/// V09 unless the target exists. Returns whether it does.
fn target_exists(
    ontology: &Ontology,
    profile: &ProfileName,
    binding: &SourceBinding,
    at: &At,
    out: &mut Vec<Diagnostic>,
) -> bool {
    let (what, key, name, exists, candidates): (_, _, _, _, Vec<&str>) = match &binding.target {
        BindingTarget::ObjectType(name) => (
            "object type",
            "objectType",
            name.as_str(),
            ontology.object_types.contains_key(name.as_str()),
            ontology
                .object_types
                .keys()
                .map(ObjectTypeName::as_str)
                .collect(),
        ),
        BindingTarget::LinkType(name) => (
            "link type",
            "linkType",
            name.as_str(),
            ontology.link_types.contains_key(name.as_str()),
            ontology
                .link_types
                .keys()
                .map(LinkTypeName::as_str)
                .collect(),
        ),
    };
    if exists {
        return true;
    }
    let d = Diagnostic::error(
        codes::V09,
        format!("binding in profile `{profile}` targets unknown {what} `{name}`"),
        &at(&["target", key], Part::Value),
    );
    out.push(match did_you_mean(name, candidates) {
        Some(s) => d.with_help(format!("did you mean `{s}`?")),
        None => d,
    });
    false
}

/// V16 when the target is `editOnly`, or is a link that is not `manyToMany` (D-02).
/// Applies to a binding in any profile.
fn may_be_bound(ontology: &Ontology, binding: &SourceBinding, at: &At, out: &mut Vec<Diagnostic>) {
    let (what, key, name, backing, cardinality) = match &binding.target {
        BindingTarget::ObjectType(name) => {
            let Some(object) = ontology.object_types.get(name.as_str()) else {
                return;
            };
            (
                "object type",
                "objectType",
                name.as_str(),
                Some(object.backing),
                None,
            )
        }
        BindingTarget::LinkType(name) => {
            let Some(link) = ontology.link_types.get(name.as_str()) else {
                return;
            };
            (
                "link type",
                "linkType",
                name.as_str(),
                link.backing,
                Some(link.cardinality),
            )
        }
    };
    let here = at(&["target", key], Part::Value);
    match cardinality {
        Some(Cardinality::OneToOne | Cardinality::OneToMany) => out.push(
            Diagnostic::error(
                codes::V16,
                format!(
                    "link type `{name}` is not manyToMany, so it cannot have a source binding"
                ),
                &here,
            )
            .with_help(
                "remove this binding: oneToOne and oneToMany links follow the foreign key on the `to` object type; only manyToMany links are bound",
            ),
        ),
        _ if backing == Some(Backing::EditOnly) => out.push(
            Diagnostic::error(
                codes::V16,
                format!("{what} `{name}` is `backing: editOnly`, so it cannot have a source binding"),
                &here,
            )
            .with_help(format!(
                "remove this binding, or set `backing: source` on `{name}`"
            )),
        ),
        _ => {}
    }
}

/// Where the selected profile name came from; decides how a bad name is located.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProfileOrigin {
    /// `--profile` or `ONTOFORGE_PROFILE`: there is no file position to point at.
    Flag,
    /// The manifest's `defaultProfile`.
    Manifest,
}

/// Checks that depend on the selected profile (D-02, D-05): when the ontology has
/// source-backed types, a profile must be selected, must exist, and must bind each
/// of them. An ontology without source-backed types needs no profile.
pub fn check_profile(
    ontology: &Ontology,
    sources: &SourceMap,
    selection: Option<(&ProfileName, ProfileOrigin)>,
) -> Vec<Diagnostic> {
    let source_objects: Vec<&ObjectTypeName> = ontology
        .object_types
        .iter()
        .filter(|(_, o)| o.backing == Backing::Source)
        .map(|(name, _)| name)
        .collect();
    let source_links: Vec<&LinkTypeName> = ontology
        .link_types
        .iter()
        .filter(|(_, l)| {
            l.cardinality == Cardinality::ManyToMany && l.backing == Some(Backing::Source)
        })
        .map(|(name, _)| name)
        .collect();
    let needed = source_objects.len() + source_links.len();
    if needed == 0 {
        return Vec::new();
    }

    let Some((profile, origin)) = selection else {
        return vec![
            Diagnostic::error(
                codes::V16,
                format!("no profile is selected, but {needed} source-backed type(s) need a binding"),
                &sources.locate_manifest(&[], Part::Value),
            )
            .with_help(
                "select a profile with `--profile <name>`, the `ONTOFORGE_PROFILE` environment variable, or `defaultProfile` in `ontology.yaml`",
            ),
        ];
    };
    let Some(bound) = ontology.profile_bindings(profile) else {
        return vec![unknown_profile(ontology, sources, profile, origin)];
    };

    let mut out = Vec::new();
    let missing = |what: &str, key: DefKey, target: &str, target_key: &str| {
        let at = sources.locate(&key, &[Seg::Key("backing".to_owned())], Part::Value);
        Diagnostic::error(
            codes::V16,
            format!("{what} `{target}` is `backing: source`, but profile `{profile}` has no binding for it"),
            &at,
        )
        .with_help(format!(
            "add a SourceBinding with `target: {{ {target_key}: {target} }}` under `bindings/{profile}/`"
        ))
    };
    for name in source_objects {
        if !bound.objects.contains_key(name.as_str()) {
            let key = DefKey {
                kind: DefKind::ObjectType,
                api_name: name.to_string(),
            };
            out.push(missing("object type", key, name.as_str(), "objectType"));
        }
    }
    for name in source_links {
        if !bound.links.contains_key(name.as_str()) {
            let key = DefKey {
                kind: DefKind::LinkType,
                api_name: name.to_string(),
            };
            out.push(missing("link type", key, name.as_str(), "linkType"));
        }
    }
    out
}

/// V16 for a selected profile that has no bindings at all.
fn unknown_profile(
    ontology: &Ontology,
    sources: &SourceMap,
    profile: &ProfileName,
    origin: ProfileOrigin,
) -> Diagnostic {
    let known: Vec<&str> = ontology.bindings.keys().map(ProfileName::as_str).collect();
    let help = match did_you_mean(profile.as_str(), known.iter().copied()) {
        Some(s) => format!("did you mean `{s}`?"),
        None if known.is_empty() => {
            format!("create `bindings/{profile}/` with one SourceBinding per source-backed type")
        }
        None => format!(
            "profiles with bindings: {}",
            known
                .iter()
                .map(|p| format!("`{p}`"))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    };
    let d = match origin {
        ProfileOrigin::Manifest => {
            let at = sources.locate_manifest(&[Seg::Key("defaultProfile".to_owned())], Part::Value);
            Diagnostic::error(
                codes::V16,
                format!(
                    "`defaultProfile` is `{profile}`, but there are no source bindings under `bindings/{profile}/`"
                ),
                &at,
            )
        }
        ProfileOrigin::Flag => Diagnostic::without_location(
            codes::V16,
            Severity::Error,
            format!(
                "profile `{profile}` was selected, but there are no source bindings under `bindings/{profile}/`"
            ),
            MANIFEST,
        ),
    };
    d.with_help(help)
}

//! Link type structural checks (hard errors): references (V09), cardinality and
//! foreign key consistency (V11), `backing` placement (V05, V11), and accessor
//! names on each object type (V08).
//!
//! A link whose end types do not exist reports V09 and the `backing` check; the
//! other checks need those types and would only add noise.

use std::collections::HashMap;
use std::collections::hash_map::Entry;

use crate::diag::{Diagnostic, SourceLocation, codes, did_you_mean};
use crate::ir::{Cardinality, LinkType, ObjectType, ObjectTypeName, Ontology, PropertyName};
use crate::loader::SourceMap;
use crate::loader::sourcemap::{DefKey, DefKind, Part, Seg};

type At<'a> = dyn Fn(&[&str], Part) -> SourceLocation + 'a;

/// Accessor `(object type, name)` mapped to the `(link, side)` that claimed it.
type Accessors<'a> = HashMap<(&'a str, &'a str), (&'a str, &'static str)>;

pub fn check(ontology: &Ontology, sources: &SourceMap, out: &mut Vec<Diagnostic>) {
    let mut accessors = Accessors::new();
    // BTreeMap order keeps the "later definition" of a clash deterministic.
    for link in ontology.link_types.values() {
        let key = DefKey {
            kind: DefKind::LinkType,
            api_name: link.api_name.to_string(),
        };
        let at = |path: &[&str], part: Part| {
            let path: Vec<Seg> = path.iter().map(|s| Seg::Key((*s).to_owned())).collect();
            sources.locate(&key, &path, part)
        };
        backing(link, &at, out);
        let Some((from, to)) = end_types(link, ontology, &at, out) else {
            continue;
        };
        foreign_key(link, from, to, &at, out);
        end_names(link, [from, to], &at, &mut accessors, out);
    }
}

/// `manyToMany` links must say where their rows come from; `oneToOne` and
/// `oneToMany` follow the foreign key on the `to` end and must not (D-02).
fn backing(link: &LinkType, at: &At, out: &mut Vec<Diagnostic>) {
    let name = &link.api_name;
    match (link.cardinality, link.backing) {
        (Cardinality::ManyToMany, None) => out.push(
            Diagnostic::error(
                codes::V05,
                format!("manyToMany link `{name}` must declare `backing`"),
                &at(&["cardinality"], Part::Value),
            )
            .with_help("add `backing: source` or `backing: editOnly`"),
        ),
        (Cardinality::OneToOne | Cardinality::OneToMany, Some(_)) => out.push(
            Diagnostic::error(
                codes::V11,
                format!(
                    "{} link `{name}` must not declare `backing`",
                    cardinality_name(link.cardinality)
                ),
                &at(&["backing"], Part::Key),
            )
            .with_help(
                "remove `backing`: oneToOne and oneToMany links follow the foreign key on the `to` object type",
            ),
        ),
        _ => {}
    }
}

fn end_types<'a>(
    link: &LinkType,
    ontology: &'a Ontology,
    at: &At,
    out: &mut Vec<Diagnostic>,
) -> Option<(&'a ObjectType, &'a ObjectType)> {
    let mut found = [None, None];
    for (slot, (side, end)) in found
        .iter_mut()
        .zip([("from", &link.from), ("to", &link.to)])
    {
        *slot = ontology.object_types.get(end.object_type.as_str());
        if slot.is_some() {
            continue;
        }
        let d = Diagnostic::error(
            codes::V09,
            format!(
                "`{side}` end of link `{}` refers to unknown object type `{}`",
                link.api_name, end.object_type
            ),
            &at(&[side, "objectType"], Part::Value),
        );
        let names = ontology.object_types.keys().map(ObjectTypeName::as_str);
        out.push(match did_you_mean(end.object_type.as_str(), names) {
            Some(s) => d.with_help(format!("did you mean `{s}`?")),
            None => d,
        });
    }
    let [Some(from), Some(to)] = found else {
        return None;
    };
    Some((from, to))
}

fn foreign_key(
    link: &LinkType,
    from: &ObjectType,
    to: &ObjectType,
    at: &At,
    out: &mut Vec<Diagnostic>,
) {
    let name = &link.api_name;
    if link.cardinality == Cardinality::ManyToMany {
        for (side, end) in [("from", &link.from), ("to", &link.to)] {
            if end.foreign_key.is_some() {
                out.push(
                    Diagnostic::error(
                        codes::V11,
                        format!("manyToMany link `{name}` must not declare a `foreignKey`"),
                        &at(&[side, "foreignKey"], Part::Value),
                    )
                    .with_help("remove it; the system manages the join for manyToMany links"),
                );
            }
        }
        return;
    }

    if link.from.foreign_key.is_some() {
        out.push(
            Diagnostic::error(
                codes::V11,
                format!("`foreignKey` of link `{name}` is on the `from` end"),
                &at(&["from", "foreignKey"], Part::Value),
            )
            .with_help("the foreign key belongs on the `to` end"),
        );
    }
    let Some(fk) = &link.to.foreign_key else {
        out.push(
            Diagnostic::error(
                codes::V11,
                format!(
                    "{} link `{name}` needs a `foreignKey` on its `to` end",
                    cardinality_name(link.cardinality)
                ),
                &at(&["cardinality"], Part::Value),
            )
            .with_help(format!(
                "add `foreignKey: <property of {}>` to the `to` end, or use manyToMany",
                to.api_name
            )),
        );
        return;
    };
    let fk_at = at(&["to", "foreignKey"], Part::Value);
    let Some(fk_prop) = to.properties.get(fk.as_str()) else {
        let d = Diagnostic::error(
            codes::V09,
            format!("foreignKey `{fk}` is not a property of `{}`", to.api_name),
            &fk_at,
        );
        let names = to.properties.keys().map(PropertyName::as_str);
        out.push(match did_you_mean(fk.as_str(), names) {
            Some(s) => d.with_help(format!("did you mean `{s}`?")),
            None => d,
        });
        return;
    };
    // A missing or malformed primary key is V10's job.
    let Some(pk_prop) = from.properties.get(from.primary_key.as_str()) else {
        return;
    };
    if fk_prop.base_type != pk_prop.base_type {
        out.push(
            Diagnostic::error(
                codes::V11,
                format!(
                    "foreignKey `{fk}` has type `{}`, but the primary key `{}.{}` has type `{}`",
                    fk_prop.base_type.as_str(),
                    from.api_name,
                    from.primary_key,
                    pk_prop.base_type.as_str()
                ),
                &fk_at,
            )
            .with_help("a foreign key must have exactly the type of the primary key it references"),
        );
    }
}

fn cardinality_name(c: Cardinality) -> &'static str {
    match c {
        Cardinality::OneToOne => "oneToOne",
        Cardinality::OneToMany => "oneToMany",
        Cardinality::ManyToMany => "manyToMany",
    }
}

/// An end's `apiName` is an accessor on its own object type, so it must differ
/// from that type's properties and from the accessors of earlier links.
fn end_names<'a>(
    link: &'a LinkType,
    [from, to]: [&'a ObjectType; 2],
    at: &At,
    accessors: &mut Accessors<'a>,
    out: &mut Vec<Diagnostic>,
) {
    for (side, end, owner) in [("from", &link.from, from), ("to", &link.to, to)] {
        let name = end.api_name.as_str();
        let here = at(&[side, "apiName"], Part::Value);
        if owner.properties.contains_key(name) {
            out.push(
                Diagnostic::error(
                    codes::V08,
                    format!(
                        "`{side}` end `{name}` of link `{}` has the same name as a property of `{}`",
                        link.api_name, owner.api_name
                    ),
                    &here,
                )
                .with_help("rename the link end or the property"),
            );
            continue;
        }
        match accessors.entry((owner.api_name.as_str(), name)) {
            Entry::Occupied(taken) => {
                let (other, other_side) = taken.get();
                out.push(
                    Diagnostic::error(
                        codes::V08,
                        format!(
                            "accessor `{name}` on `{}` is already used by the `{other_side}` end of link `{other}`",
                            owner.api_name
                        ),
                        &here,
                    )
                    .with_help("rename one of the two link ends"),
                );
            }
            Entry::Vacant(slot) => {
                slot.insert((link.api_name.as_str(), side));
            }
        }
    }
}

//! Cross-definition validation (hard `ONT-V` errors). Grows with plans 01-04..06.

use crate::diag::Diagnostic;
use crate::ir::Ontology;
use crate::loader::SourceMap;

mod actions;
mod bindings;
mod links;
mod objects;

pub(crate) use bindings::check_fixture_files;
pub use bindings::{ProfileOrigin, check_profile};

/// All structural checks on a fully merged ontology.
pub fn validate(ontology: &Ontology, sources: &SourceMap) -> Vec<Diagnostic> {
    let mut out = Vec::new();
    objects::check(ontology, sources, &mut out);
    links::check(ontology, sources, &mut out);
    actions::check(ontology, sources, &mut out);
    bindings::check(ontology, sources, &mut out);
    out
}

//! Object type structural checks (hard errors): primary key, title key, `items`,
//! `precision` and `scale` placement.
//!
//! Discouraged primary key types and nested arrays are lint territory (E09), not
//! errors here; both read [`pk_suitability`].

use crate::diag::{Diagnostic, SourceLocation, codes, did_you_mean};
use crate::ir::basetype::{PkSuitability, pk_suitability};
use crate::ir::{BaseType, ObjectType, Ontology, PropertyName};
use crate::loader::SourceMap;
use crate::loader::sourcemap::{DefKey, DefKind, Part, Seg};

pub fn check(ontology: &Ontology, sources: &SourceMap, out: &mut Vec<Diagnostic>) {
    for object in ontology.object_types.values() {
        let key = DefKey {
            kind: DefKind::ObjectType,
            api_name: object.api_name.to_string(),
        };
        let at = |path: &[&str], part: Part| {
            let path: Vec<Seg> = path.iter().map(|s| Seg::Key((*s).to_owned())).collect();
            sources.locate(&key, &path, part)
        };
        primary_key(object, &at, out);
        title_key(object, &at, out);
        items(object, &at, out);
        decimal_arguments(object, &at, out);
    }
}

type At<'a> = dyn Fn(&[&str], Part) -> SourceLocation + 'a;

fn suggest(d: Diagnostic, name: &PropertyName, object: &ObjectType) -> Diagnostic {
    let candidates = object.properties.keys().map(PropertyName::as_str);
    match did_you_mean(name.as_str(), candidates) {
        Some(s) => d.with_help(format!("did you mean `{s}`?")),
        None => d,
    }
}

fn primary_key(object: &ObjectType, at: &At, out: &mut Vec<Diagnostic>) {
    let pk = &object.primary_key;
    let Some(prop) = object.properties.get(pk.as_str()) else {
        let d = Diagnostic::error(
            codes::V10,
            format!(
                "primaryKey `{pk}` is not a property of `{}`",
                object.api_name
            ),
            &at(&["primaryKey"], Part::Value),
        );
        out.push(suggest(d, pk, object));
        return;
    };
    if !prop.required {
        out.push(
            Diagnostic::error(
                codes::V10,
                format!("primary key property `{pk}` must be required"),
                &at(&["properties", pk.as_str()], Part::Key),
            )
            .with_help("declare `required: true` on the primary key property"),
        );
    }
    if pk_suitability(prop.base_type) == PkSuitability::Invalid {
        out.push(
            Diagnostic::error(
                codes::V10,
                format!(
                    "primary key property `{pk}` has type `{}`, which cannot identify an object",
                    prop.base_type.as_str()
                ),
                &at(&["primaryKey"], Part::Value),
            )
            .with_help("use a `string`, `integer` or `short` property as the primary key"),
        );
    }
}

fn title_key(object: &ObjectType, at: &At, out: &mut Vec<Diagnostic>) {
    let Some(title) = &object.title_key else {
        return;
    };
    if object.properties.contains_key(title.as_str()) {
        return;
    }
    let d = Diagnostic::error(
        codes::V10,
        format!(
            "titleKey `{title}` is not a property of `{}`",
            object.api_name
        ),
        &at(&["titleKey"], Part::Value),
    );
    out.push(suggest(d, title, object));
}

fn items(object: &ObjectType, at: &At, out: &mut Vec<Diagnostic>) {
    for (name, prop) in &object.properties {
        let name = name.as_str();
        match (prop.base_type, prop.items) {
            (BaseType::Array, None) => out.push(
                Diagnostic::error(
                    codes::V05,
                    format!("array property `{name}` must declare `items`"),
                    &at(&["properties", name, "type"], Part::Value),
                )
                .with_help("add `items: <element type>`, for example `items: string`"),
            ),
            (t, Some(_)) if t != BaseType::Array => out.push(
                Diagnostic::error(
                    codes::V06,
                    format!(
                        "`items` is only allowed on array properties, but `{name}` is `{}`",
                        t.as_str()
                    ),
                    &at(&["properties", name, "items"], Part::Key),
                )
                .with_help("remove `items`, or change the type to `array`"),
            ),
            _ => {}
        }
    }
}

/// `precision` and `scale` belong to `decimal` properties, or to `array` properties
/// whose elements are `decimal`. Their value ranges are lint territory (E13).
fn decimal_arguments(object: &ObjectType, at: &At, out: &mut Vec<Diagnostic>) {
    for (name, prop) in &object.properties {
        let name = name.as_str();
        let takes_arguments = prop.base_type == BaseType::Decimal
            || (prop.base_type == BaseType::Array && prop.items == Some(BaseType::Decimal));
        if takes_arguments {
            continue;
        }
        for (key, present) in [
            ("precision", prop.precision.is_some()),
            ("scale", prop.scale.is_some()),
        ] {
            if present {
                out.push(
                    Diagnostic::error(
                        codes::V06,
                        format!(
                            "`{key}` is only allowed on decimal properties, but `{name}` is `{}`",
                            prop.base_type.as_str()
                        ),
                        &at(&["properties", name, key], Part::Key),
                    )
                    .with_help(format!(
                        "remove `{key}`, or change the type to `decimal` (or an `array` of `decimal`)"
                    )),
                );
            }
        }
    }
}

