    let out = load_from_memory(&[("ontology.yaml", "apiName: demo\n"), ("invoice.yaml", &bad)]);
    assert_eq!(only(&out).code, codes::V06);

    for ok in [
        "amount: { type: decimal, precision: 12, scale: 2 }",
        "amounts: { type: array, items: decimal, precision: 12, scale: 2 }",
        "plain: { type: decimal }",
