#[test]
fn invalid_scope_documents_fail_schema() {
    let scope = validator(&scope_schema());
    let cases = [
        // A misspelled key must not pass: it would silently drop the row filter.
        "kind: Role
apiName: dispatcher
objectTypes:
  Flight:
    properties: [flightId]
    rowfilter: \"true\"
",
        "kind: Role
apiName: dispatcher
toolsets: [sql]
",
        "kind: RoleBinding
role: dispatcher
subjects:
  - users: bob
",
        "kind: RoleBinding
role: Dispatcher
subjects: []
",
        "kind: ObjectType
apiName: Airport
",
