//! `ontoforge` command line library: argument model and orchestration.

use std::io::Write;

pub mod cli;
pub mod dev;
pub mod dev_assets;
pub mod dev_token;
pub mod import;
pub mod lint_cmd;
pub mod mcp;
pub mod migrate;
pub mod online;
