use camino::Utf8Path;
use cli::{Cli, Command, LintArgs, OutputArgs, SchemaCommand, ValidateArgs};
use ontoforge_schema::diag::{Severity, codes};
use ontoforge_schema::{LoadOutput, schema_export};
use render::{ColorChoice, Format};

/// Run the CLI and return the process exit code.
pub fn run(cli: Cli) -> u8 {
    match cli.command {
        Command::Validate(args) => validate(&args),
        Command::Lint(args) => lint(&args),
        Command::Reload(args) => reload::run(&args),
        Command::Migrate(args) => migrate::run(&args),
        Command::Scope(args) => scope::run(&args),
        Command::Import(args) => import::run(&args),
        Command::DevToken(args) => dev_token::run(&args),
        Command::WebhookWorker(args) => webhook_worker::run(&args),
        Command::Serve(args) => serve::run(&args),
        Command::Mcp(args) => mcp::run(&args),
        Command::Schema(args) => match args.command {
            SchemaCommand::Export { out_dir } => export_schemas(&out_dir),
        },
    }
}

/// Write each exported schema into `out_dir`, naming every written file on stderr.
fn export_schemas(out_dir: &Utf8Path) -> u8 {
    let result = std::fs::create_dir_all(out_dir).and_then(|()| {
        for (name, text) in schema_export::rendered_schemas() {
            std::fs::write(out_dir.join(name), text)?;
            eprintln!("{}/{name}", out_dir.as_str().trim_end_matches(['/', '\\']));
        }
        Ok(())
    });
    match result {
        Ok(()) => 0,
        Err(e) => {
            eprintln!("error: cannot write schemas to {out_dir}: {e}");
            1
        }
    }
}

/// Print the diagnostics to stdout and return the exit code.
fn report(out: &LoadOutput, args: &OutputArgs) -> u8 {
    print_diagnostics(out, args);
    render::exit_code(&out.diagnostics, args.deny_warnings)
}

/// Print the diagnostics to stdout.
fn print_diagnostics(out: &LoadOutput, args: &OutputArgs) {
    print_rendered(&out.diagnostics, &out.sources, args);
}

/// Print `diagnostics` to stdout in the format and colors `args` ask for.
fn print_rendered(
    diagnostics: &[ontoforge_schema::diag::Diagnostic],
    sources: &ontoforge_schema::loader::SourceMap,
    args: &OutputArgs,
) {
    let color = match args.color {
        ColorChoice::Always => true,
        ColorChoice::Never => false,
        // NO_COLOR, CLICOLOR, CLICOLOR_FORCE, TERM and the terminal check, per anstream.
        ColorChoice::Auto => {
            anstream::AutoStream::choice(&std::io::stdout()) != anstream::ColorChoice::Never
        }
    };
    let text = render::render(diagnostics, sources, args.format, color);
    let _ = std::io::stdout().write_all(text.as_bytes());
}

fn validate(args: &ValidateArgs) -> u8 {
    if args.online {
        return validate_online(args);
    }
    let checked = pipeline::check_with_profile(&args.dir, args.profile.profile.as_deref());
    let out = &checked.out;
    let code = report(out, &args.output);
    if args.output.format == Format::Human {
        let summary = match &out.ontology {
            Some(ontology) => format!(
                "ok: ontology `{}` with {} object type(s){}",
                ontology.api_name,
                ontology.object_types.len(),
                checked
                    .profile
                    .as_ref()
                    .map_or_else(String::new, |p| format!(", profile `{p}`"))
            ),
            None => format!("{} problem(s) found", out.diagnostics.len()),
        };
        eprintln!("{summary}");
    }
    code
}

/// `validate --online`: exit code 3 when the engine could not answer for some binding.
fn validate_online(args: &ValidateArgs) -> u8 {
    let run = online::run_online(args);
    print_diagnostics(&run.out, &args.output);
    if args.output.format == Format::Human {
        let warnings = run
            .out
            .diagnostics
            .iter()
            .filter(|d| d.severity == Severity::Warning)
            .count();
        let summary = match (&run.out.ontology, &run.profile) {
            _ if run.code == 3 => engine_summary(&run.out),
            (Some(ontology), Some(profile)) if run.code == 0 && warnings > 0 => format!(
                "ontology `{}`, profile `{profile}`, {} binding(s) checked online; {warnings} warning(s) found",
                ontology.api_name, run.bindings
            ),
            (Some(ontology), Some(profile)) if run.code == 0 => format!(
                "ok: ontology `{}`, profile `{profile}`, {} binding(s) checked online",
                ontology.api_name, run.bindings
            ),
            (Some(ontology), None) if run.code == 0 => format!(
                "ok: ontology `{}`, no profile selected, nothing to check online",
                ontology.api_name
            ),
            _ => format!("{} problem(s) found", run.out.diagnostics.len()),
        };
        eprintln!("{summary}");
    }
    run.code
}

fn lint(args: &LintArgs) -> u8 {
    let out = lint_cmd::lint(
        &args.dir,
        args.config.as_deref(),
        args.profile.profile.as_deref(),
    );
    let code = report(&out, &args.output);
    if args.output.format == Format::Human {
        eprintln!("{}", lint_summary(&out));
    }
    code
}

/// The stderr line of a human-format lint run.
fn lint_summary(out: &LoadOutput) -> String {
    let count = |severity| {
        out.diagnostics
            .iter()
            .filter(|d| d.severity == severity)
            .count()
    };
    let is_error = |code: &str| {
        out.diagnostics
            .iter()
            .any(|d| d.severity == Severity::Error && d.code == code)
    };
    if out.diagnostics.iter().any(|d| {
        d.severity == Severity::Error && d.code.starts_with("ONT-V") && d.code != codes::V15
    }) {
        return format!(
            "validation failed, lint skipped: {}",
            plural(count(Severity::Error), "error", "errors")
        );
    }
    if is_error(codes::V15) {
        return "lint configuration is invalid, lint skipped".to_owned();
    }
    if out.diagnostics.is_empty() {
        let name = out.ontology.as_ref().map_or("", |o| o.api_name.as_str());
        return format!("ok: ontology `{name}` has no lint findings");
    }
    format!(
        "{}, {}, {}",
        plural(count(Severity::Error), "error", "errors"),
        plural(count(Severity::Warning), "warning", "warnings"),
        plural(count(Severity::Info), "info", "infos"),
    )
}

fn plural(n: usize, one: &str, many: &str) -> String {
    format!("{n} {}", if n == 1 { one } else { many })
}

/// The stderr line when the engine could not answer: the first ONT-V19 message.
fn engine_summary(out: &LoadOutput) -> String {
    let reason = out
        .diagnostics
        .iter()
        .find(|d| d.code == codes::V19)
        .map_or_else(String::new, |d| render::sanitize(&d.message));
    format!("online check could not complete: {reason}")
}

//! `ontoforge lint` orchestration: validate, then configuration, then rules (D-06).
//!
//! In the library, not the binary, so a later server can lint the same way.

use camino::Utf8Path;
use ontoforge_schema::LoadOutput;
use ontoforge_schema::diag::{has_errors, sort_diagnostics};
use ontoforge_schema::lint;

use crate::pipeline;

/// Check the ontology under `root` for `profile` (see [`pipeline::check_with_profile`]);
/// when it has no errors, load the lint
/// configuration (`config` overrides `<root>/ontoforge.toml`) and run the rules.
///
/// Structural errors (`ONT-V*`) and configuration errors (`ONT-V15`) stop the run
/// before any rule executes; they are returned as the only error diagnostics.
pub fn lint(root: &Utf8Path, config: Option<&Utf8Path>, profile: Option<&str>) -> LoadOutput {
    let mut out = pipeline::check_with_profile(root, profile).out;
    if has_errors(&out.diagnostics) {
        return out;
    }
    let Some(ontology) = out.ontology.as_ref() else {
        return out;
    };
    let (config, config_diags) = lint::load_config(root, config, &mut out.sources);
    let config_failed = has_errors(&config_diags);
    out.diagnostics.extend(config_diags);
    if !config_failed {
        out.diagnostics
            .extend(lint::run(ontology, &out.sources, &config));
    }
    sort_diagnostics(&mut out.diagnostics);
    out
}

use std::process::ExitCode;

use clap::Parser;
use ontoforge::cli::Cli;

/// The pipeline runs on a large stack: debug builds on Windows have a 1 MiB main
/// thread stack, which nested YAML can exhaust.
const STACK_SIZE: usize = 32 << 20;

fn main() -> ExitCode {
    let cli = Cli::parse();
    let handle = std::thread::Builder::new()
        .name("ontoforge-main".into())
        .stack_size(STACK_SIZE)
        .spawn(move || ontoforge::run(cli));
    if let Ok(Ok(code)) = handle.map(std::thread::JoinHandle::join) {
        ExitCode::from(code)
    } else {
        eprintln!("internal error: ontoforge worker thread failed");
        ExitCode::from(101)
    }
}

//! Orchestration shared by the CLI and later by the server.

use camino::Utf8Path;
use ontoforge_schema::LoadOutput;
use ontoforge_schema::diag::{
    Diagnostic, Severity, codes, has_errors, parse_custom_de_error, sort_diagnostics,
};
use ontoforge_schema::ir::{Ontology, ProfileName};
use ontoforge_schema::loader::MANIFEST;
use ontoforge_schema::validate::{ProfileOrigin, check_profile};

/// The result of [`check_with_profile`].
#[derive(Debug)]
pub struct Checked {
    pub out: LoadOutput,
    /// The profile that was checked against; `None` when the load failed or no
    /// profile is selected.
    pub profile: Option<ProfileName>,
}

/// Load and validate the ontology under `root` for the profile chosen by `profile`
/// (`--profile` or `ONTOFORGE_PROFILE`, read by the caller, never here) or else by
/// the manifest's `defaultProfile`: structural checks first, then binding
/// completeness, then the CEL checks of submission criteria (`ONT-V13`, hard errors)
/// once the IR exists.
pub fn check_with_profile(root: &Utf8Path, profile: Option<&str>) -> Checked {
    let mut out = ontoforge_schema::load_dir(root);
    let mut chosen = None;
    if let Some(ontology) = &out.ontology {
        match select_profile(ontology, profile) {
            Ok(selection) => {
                let found = check_profile(
                    ontology,
                    &out.sources,
                    selection.as_ref().map(|(p, origin)| (p, *origin)),
                );
                out.diagnostics.extend(found);
                chosen = selection.map(|(p, _)| p);
            }
            Err(d) => out.diagnostics.push(d),
        }
        out.diagnostics
            .extend(ontoforge_expr::check_ontology(ontology, &out.sources));
        sort_diagnostics(&mut out.diagnostics);
    }
    if has_errors(&out.diagnostics) {
        // `ontology` is `Some` only when no error was found.
        out.ontology = None;
    }
    Checked {
        out,
        profile: chosen,
    }
}

/// [`check_with_profile`] without an explicit profile.
pub fn check(root: &Utf8Path) -> LoadOutput {
    check_with_profile(root, None).out
}

/// `requested` (flag or environment) wins over the manifest's `defaultProfile`. A
/// requested name must be a valid profile name; it is only ever looked up in the
/// loaded bindings, never turned into a path.
fn select_profile(
    ontology: &Ontology,
    requested: Option<&str>,
) -> Result<Option<(ProfileName, ProfileOrigin)>, Diagnostic> {
    match requested {
        Some(raw) => match ProfileName::try_from(raw.to_owned()) {
            Ok(profile) => Ok(Some((profile, ProfileOrigin::Flag))),
            Err(text) => {
                let (message, help) =
                    parse_custom_de_error(&text).map_or((text, None), |c| (c.message, c.help));
                let d =
                    Diagnostic::without_location(codes::V16, Severity::Error, message, MANIFEST);
                Err(match help {
                    Some(h) => d.with_help(h),
                    None => d,
                })
            }
        },
        None => Ok(ontology
            .default_profile
            .clone()
            .map(|profile| (profile, ProfileOrigin::Manifest))),
    }
}

//! Diagnostic output: miette for people, a JSON array for tools.

use clap::ValueEnum;
use miette::{
    GraphicalReportHandler, GraphicalTheme, LabeledSpan, MietteDiagnostic, NamedSource, Report,
    Severity as MietteSeverity,
};
use ontoforge_schema::diag::{Diagnostic, Severity};
use ontoforge_schema::loader::SourceMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum Format {
    Human,
    Json,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum ColorChoice {
    Auto,
    Always,
    Never,
}

/// Render all diagnostics. `color` only matters for [`Format::Human`].
pub fn render(diags: &[Diagnostic], sources: &SourceMap, format: Format, color: bool) -> String {
    match format {
        Format::Json => {
            let mut s = serde_json::to_string_pretty(diags).unwrap_or_else(|_| "[]".to_owned());
            s.push('\n');
            s
        }
        Format::Human => render_human(diags, sources, color),
    }
}

fn render_human(diags: &[Diagnostic], sources: &SourceMap, color: bool) -> String {
    let theme = if color {
        GraphicalTheme::unicode()
    } else {
        GraphicalTheme::unicode_nocolor()
    };
    let handler = GraphicalReportHandler::new_themed(theme).with_width(100);
    let mut out = String::new();
    for d in diags {
        let report = to_report(d, sources);
        // Writing into a String cannot fail.
        let _ = handler.render_report(&mut out, report.as_ref());
        out.push('\n');
    }
    out
}

fn to_report(d: &Diagnostic, sources: &SourceMap) -> Report {
    let severity = match d.severity {
        Severity::Error => MietteSeverity::Error,
        Severity::Warning => MietteSeverity::Warning,
        Severity::Info => MietteSeverity::Advice,
    };
    let text = if d.line == 0 {
        None
    } else {
        sources.text(&d.file)
    };
    let message = match text {
        // A located diagnostic in a file that is not a registered source (the server
        // configuration, whose lines may hold a secret, CR-C01): name the place, print no line.
        None if d.line > 0 => format!(
            "{}\n  at {}:{}:{}",
            sanitize(&d.message),
            sanitize(&d.file),
            d.line,
            d.column
        ),
        _ => sanitize(&d.message),
    };
    let mut diag = MietteDiagnostic::new(message)
        .with_code(sanitize(&d.code))
        .with_severity(severity);
    if let Some(help) = &d.help {
        diag = diag.with_help(sanitize(help));
    }
    let Some(text) = text else {
        return Report::new(diag);
    };
    diag = diag.with_label(LabeledSpan::at(
        d.span.offset..d.span.offset + d.span.length,
        "here",
    ));
    // File names come from the (possibly untrusted) checkout and miette prints them
    // unescaped in the source header (CR-04).
    Report::new(diag).with_source_code(NamedSource::new(sanitize(&d.file), sanitize(text)))
}

/// Replace terminal control characters so a definition file cannot drive the
/// reader's terminal or reorder what it shows. Each replaced character becomes one
/// `?` per UTF-8 byte, so span offsets stay valid. Replaced: C0 controls except tab
/// and newline, a carriage return not followed by a newline (it would move the
/// cursor back over the line, WR-11), DEL, C1 controls, and the bidirectional
/// controls U+061C, U+200E, U+200F, U+202A to U+202E and U+2066 to U+2069.
pub fn sanitize(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        let keep = match c {
            '\t' | '\n' => true,
            '\r' => chars.peek() == Some(&'\n'),
            '\u{0}'..='\u{1f}'
            | '\u{7f}'..='\u{9f}'
            | '\u{61c}'
            | '\u{200e}'
            | '\u{200f}'
            | '\u{202a}'..='\u{202e}'
            | '\u{2066}'..='\u{2069}' => false,
            _ => true,
        };
        if keep {
            out.push(c);
        } else {
            out.extend(std::iter::repeat_n('?', c.len_utf8()));
        }
    }
    out
}

/// 1 when there is an error, or a warning under `--deny-warnings`; otherwise 0.
pub fn exit_code(diags: &[Diagnostic], deny_warnings: bool) -> u8 {
    let failed = diags.iter().any(|d| match d.severity {
        Severity::Error => true,
        Severity::Warning => deny_warnings,
        Severity::Info => false,
    });
    u8::from(failed)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sanitize_preserves_byte_length_and_strips_escapes() {
        let input = "a\u{1b}[31mb\u{9b}c\u{7f}\td\n";
        let out = sanitize(input);
        assert_eq!(out.len(), input.len());
        assert!(!out.contains('\u{1b}') && !out.contains('\u{9b}') && !out.contains('\u{7f}'));
        assert!(out.contains('\t') && out.ends_with('\n'));
    }

    /// WR-11: a lone carriage return and bidirectional controls are replaced; a
    /// `\r\n` line end is kept.
    #[test]
    fn carriage_return_and_bidi_controls_are_replaced() {
        let input = "x\rerror: all good\r\nab\u{202e}cd\u{2066}e\u{200f}f\u{61c}g";
        let out = sanitize(input);
        assert_eq!(out.len(), input.len());
        assert_eq!(out, "x?error: all good\r\nab???cd???e???f??g");
    }

    /// CR-04: the file name reaches the source header, so it is sanitized too.
    #[test]
    fn file_name_cannot_drive_the_terminal() {
        let name = "\u{1b}]52;c;aGk=\u{7}.yaml";
        let mut sources = SourceMap::default();
        sources.add_file(name, "a: 1\n".to_owned());
        let at = ontoforge_schema::diag::SourceLocation {
            file: name.into(),
            line: 1,
            column: 1,
            offset: 0,
            length: 1,
        };
        let out = render(
            &[Diagnostic::error("ONT-V01", "x", &at)],
            &sources,
            Format::Human,
            false,
        );
        assert!(out.contains("?]52;c;aGk=?.yaml"), "{out}");
        assert!(!out.contains('\u{1b}') && !out.contains('\u{7}'), "{out:?}");
    }

    /// CR-C01: a located diagnostic whose file is not a registered source names its place
    /// and prints no line of that file.
    #[test]
    fn located_diagnostic_without_source_names_the_place() {
        let at = ontoforge_schema::diag::SourceLocation {
            file: "cfg/server.toml".into(),
            line: 6,
            column: 1,
            offset: 40,
            length: 8,
        };
        let out = render(
            &[Diagnostic::error("ONT-V20", "plaintext", &at)],
            &SourceMap::default(),
            Format::Human,
            false,
        );
        assert!(out.contains("cfg/server.toml:6:1"), "{out}");
        assert!(!out.contains("╭─["), "no source snippet: {out}");
    }

    #[test]
    fn multibyte_text_is_untouched() {
        assert_eq!(sanitize("航班 Flight"), "航班 Flight");
    }

    #[test]
    fn exit_codes() {
        let at = ontoforge_schema::diag::SourceLocation {
            file: "a".into(),
            line: 1,
            column: 1,
            offset: 0,
            length: 1,
        };
        let err = Diagnostic::error("ONT-V01", "x", &at);
        let warn = Diagnostic::new("ONT-W01", Severity::Warning, "x", &at);
        assert_eq!(exit_code(&[], false), 0);
        assert_eq!(exit_code(std::slice::from_ref(&err), false), 1);
        assert_eq!(exit_code(std::slice::from_ref(&warn), false), 0);
        assert_eq!(exit_code(std::slice::from_ref(&warn), true), 1);
    }
}

