    assert!(stderr.contains("profile `dev`"), "{stderr}");
    let out = ontoforge(&["validate", path, "--color", "never", "--profile", "dev"]);
    let stderr = String::from_utf8_lossy(&out.stderr).into_owned();
    assert!(stderr.contains("profile `dev`"), "{stderr}");
}

