            },
            "properties": {
              "description": "Property values to set. The primary key cannot be set.",
              "type": "object",
              "additionalProperties": false,
              "patternProperties": {
                "^[a-z][A-Za-z0-9]{0,99}$": {
                  "$ref": "#/$defs/ValueSource"
                }
              }
            }
          },
          "additionalProperties": false,
          "required": [
            "kind",
            "object",
            "properties"
          ]
        },
        {
          "description": "Delete an existing object passed as a parameter.",
          "type": "object",
          "properties": {
            "kind": {
              "type": "string",
              "const": "deleteObject"
            },
            "object": {
              "description": "Name of an `objectReference` parameter holding the object to delete.",
              "$ref": "#/$defs/ParameterName"
            }
          },
          "additionalProperties": false,
          "required": [
            "kind",
            "object"
          ]
        },
        {
          "description": "Restore the source view by clearing the edit overlay.",
          "type": "object",
          "properties": {
            "kind": {
              "type": "string",
              "const": "releaseObject"
            },
            "object": {
              "description": "Name of an `objectReference` parameter for a source-backed object.",
              "$ref": "#/$defs/ParameterName"
            }
          },
          "additionalProperties": false,
          "required": [
            "kind",
            "object"
          ]
        },
        {
          "description": "Link two existing objects.",
          "type": "object",
          "properties": {
            "kind": {
              "type": "string",
              "const": "addLink"
            },
            "link": {
              "description": "The link type to edit.",
              "$ref": "#/$defs/LinkTypeName"
            },
            "from": {
              "description": "`objectReference` parameter for the link's `from` object type.",
              "$ref": "#/$defs/ParameterName"
            },
            "to": {
              "description": "`objectReference` parameter for the link's `to` object type.",
              "$ref": "#/$defs/ParameterName"
            }
          },
          "additionalProperties": false,
          "required": [
            "kind",
            "link",
            "from",
            "to"
          ]
        },
        {
          "description": "Unlink two existing objects.",
          "type": "object",
          "properties": {
            "kind": {
              "type": "string",
              "const": "removeLink"
            },
            "link": {
              "description": "The link type to edit.",
              "$ref": "#/$defs/LinkTypeName"
            },
            "from": {
              "description": "`objectReference` parameter for the link's `from` object type.",
              "$ref": "#/$defs/ParameterName"
            },
            "to": {
              "description": "`objectReference` parameter for the link's `to` object type.",
              "$ref": "#/$defs/ParameterName"
            }
          },
          "additionalProperties": false,
          "required": [
            "kind",
            "link",
            "from",
            "to"
          ]
        }
      ]
    },
    "ValueSource": {
      "description": "Where a property value comes from, written as a single-key map.",
      "oneOf": [
        {
          "description": "The value of a parameter: `{ param: name }`.",
          "type": "object",
          "properties": {
            "param": {
              "$ref": "#/$defs/ParameterName"
            }
          },
          "required": [
            "param"
          ],
          "additionalProperties": false
        },
        {
          "description": "A literal: `{ static: value }`. `null` is not allowed.",
          "type": "object",
          "properties": {
            "static": true
          },
          "required": [
            "static"
          ],
          "additionalProperties": false
        },
        {
          "description": "The calling user's id, for string properties: `{ currentUser: {} }`.",
          "type": "object",
          "properties": {
            "currentUser": {
              "$ref": "#/$defs/Empty"
            }
          },
          "required": [
            "currentUser"
          ],
          "additionalProperties": false
        },
        {
          "description": "The time of the call, for timestamp properties: `{ currentTime: {} }`.",
          "type": "object",
          "properties": {
            "currentTime": {
              "$ref": "#/$defs/Empty"
            }
          },
          "required": [
            "currentTime"
          ],
          "additionalProperties": false
        }
      ]
    },
    "ParameterName": {
      "type": "string",
      "pattern": "^[a-z][A-Za-z0-9]{0,99}$"
    },
    "Empty": {
      "description": "The empty mapping `{}`; no fields are accepted.",
      "type": "object",
      "additionalProperties": false
    },
    "SubmissionCriterion": {
      "description": "A condition checked before the rules run.",
      "type": "object",
      "properties": {
        "condition": {
          "description": "A CEL expression over `params`, `user` and `objects` that must be true.",
          "type": "string"
        },
        "failureMessage": {
          "description": "Shown to the caller when the condition is false.",
          "type": "string"
        }
      },
      "additionalProperties": false,
      "required": [
        "condition",
        "failureMessage"
      ]
    },
    "BindingTarget": {
      "description": "What a [`SourceBinding`] binds. Externally tagged so that error paths survive\ndeserialization (ADR-0003).",
      "oneOf": [
        {
          "description": "An object type, by its `PascalCase` apiName.",
          "type": "object",
          "properties": {
            "objectType": {
              "$ref": "#/$defs/ObjectTypeName"
            }
          },
          "required": [
            "objectType"
          ],
          "additionalProperties": false
        },
        {
          "description": "A many-to-many link type, by its `camelCase` apiName.",
          "type": "object",
          "properties": {
            "linkType": {
              "$ref": "#/$defs/LinkTypeName"
            }
          },
          "required": [
            "linkType"
          ],
          "additionalProperties": false
        }
      ]
    },
    "SourceRef": {
      "description": "A physical table or view in the data source.\n\nIt is one table or view. To combine several tables, create a view in Trino and\nbind that (D-04).",
      "type": "object",
      "properties": {
        "catalog": {
          "description": "Trino catalog.",
          "type": "string"
        },
        "schema": {
          "description": "Schema inside the catalog.",
          "type": "string"
        },
        "table": {
          "description": "Table or view name.",
          "type": "string"
        }
      },
      "additionalProperties": false,
      "required": [
        "catalog",
        "schema",
        "table"
      ]
    },
    "ColumnBinding": {
      "description": "How one property (or one link end) maps to a column.",
      "type": "object",
      "properties": {
        "column": {
          "description": "Physical column name. Defaults to the property apiName (D-03).",
          "type": [
            "string",
            "null"
          ]
        },
        "timezone": {
          "description": "IANA time zone name for a timestamp column that carries no zone, for\nexample `Europe/Berlin`; write `aware` when the column already has one\n(ADR-0021).",
          "type": [
            "string",
            "null"
          ]
        },
        "collation": {
          "description": "How string comparison treats case on this column.",
          "anyOf": [
            {
              "$ref": "#/$defs/Collation"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "additionalProperties": false
    },
    "Collation": {
      "description": "String comparison semantics of a column.",
      "oneOf": [
        {
          "description": "Upper and lower case letters differ.",
          "type": "string",
          "const": "caseSensitive"
        },
        {
          "description": "Upper and lower case letters compare equal.",
          "type": "string",
          "const": "caseInsensitive"
        }
      ]
    },
    "FixtureRef": {
      "description": "Sample rows for the stand-in engine.",
      "type": "object",
      "properties": {
        "file": {
          "description": "Path relative to the directory of the binding file. Only `.csv` and `.json`\nfiles inside the ontology directory are accepted.",
          "type": "string"
        }
      },
      "additionalProperties": false,
      "required": [
        "file"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "ontoforge ontology manifest",
  "type": "object",
  "properties": {
    "apiName": {
      "$ref": "#/$defs/OntologyName"
    },
    "displayName": {
      "type": [
        "string",
        "null"
      ]
    },
    "description": {
      "type": [
        "string",
        "null"
      ]
    },
    "include": {
      "type": [
        "array",
        "null"
      ],
      "items": {
        "type": "string"
      }
    },
    "defaultProfile": {
      "description": "Profile used when neither `--profile` nor `ONTOFORGE_PROFILE` selects one: the\nname of a directory under `bindings/` (D-05).",
      "anyOf": [
        {
          "$ref": "#/$defs/ProfileName"
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "additionalProperties": false,
  "required": [
    "apiName"
  ],
  "$defs": {
    "OntologyName": {
      "type": "string",
      "pattern": "^[a-z][A-Za-z0-9]{0,99}$"
    },
    "ProfileName": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_-]{0,31}$"
    }
  },
  "description": "The ontology.yaml manifest naming the ontology and listing definition files."
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "ontoforge scope document",
  "description": "A Role or RoleBinding document (ADR-0018, ADR-0019), selected by its `kind`. Scope documents live in their own directory, apart from the ontology definition and its SourceBinding files; JSON files may hold an array of them.",
  "anyOf": [
    {
      "$ref": "#/$defs/ScopeDefinition"
    },
    {
      "type": "array",
      "items": {
        "$ref": "#/$defs/ScopeDefinition"
      }
    }
  ],
  "$defs": {
    "ScopeDefinition": {
      "description": "One scope document: a Role or a RoleBinding, selected by `kind`.",
      "oneOf": [
        {
          "description": "What one role may do.",
          "type": "object",
          "properties": {
            "kind": {
              "type": "string",
              "const": "Role"
            },
            "apiName": {
              "description": "Role name, `camelCase`; a `RoleBinding` refers to it.",
              "$ref": "#/$defs/RoleName"
            },
            "displayName": {
              "type": [
                "string",
                "null"
              ]
            },
            "description": {
              "type": [
                "string",
                "null"
              ]
            },
            "objectTypes": {
              "description": "Per object type: the readable properties and an optional row filter.",
              "type": "object",
              "additionalProperties": false,
              "patternProperties": {
                "^[A-Z][A-Za-z0-9]{0,99}$": {
                  "$ref": "#/$defs/TypeGrant"
                }
              },
              "default": {}
            },
            "actions": {
              "description": "Action types the role may submit.",
              "type": "array",
              "items": {
                "$ref": "#/$defs/ActionTypeName"
              },
              "default": []
            },
            "sqlLevels": {
              "description": "SQL tiers beyond the implicit L0 (ontology-bound queries).",
              "type": "array",
              "items": {
                "$ref": "#/$defs/SqlLevel"
              },
              "default": []
            },
            "l2": {
              "description": "Trino catalogs and schemas the role may query directly (L2).",
              "$ref": "#/$defs/L2Grant",
              "default": {
                "catalogs": [],
                "schemas": []
              }
            },
            "toolsets": {
              "description": "MCP toolsets the role may use (ADR-0019).",
              "type": "array",
              "items": {
                "$ref": "#/$defs/Toolset"
              },
              "default": []
            }
          },
          "additionalProperties": false,
          "required": [
            "kind",
            "apiName"
          ]
        },
        {
          "description": "Attaches one role to its subjects.",
          "type": "object",
          "properties": {
            "kind": {
              "type": "string",
              "const": "RoleBinding"
            },
            "role": {
              "$ref": "#/$defs/RoleName"
            },
            "subjects": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/Subject"
              }
            }
          },
          "additionalProperties": false,
          "required": [
            "kind",
            "role",
            "subjects"
          ]
        }
      ]
    },
    "RoleName": {
      "type": "string",
      "pattern": "^[a-z][A-Za-z0-9]{0,99}$"
    },
    "TypeGrant": {
      "description": "Access to one object type: which columns, and which rows.",
      "type": "object",
      "properties": {
        "properties": {
          "description": "Property allow-list: the only properties of this type the role can read.",
          "type": "array",
          "items": {
            "$ref": "#/$defs/PropertyName"
          }
        },
        "rowFilter": {
          "description": "CEL over the object's own properties and `principal.attrs`; absent means all\nrows are visible.",
          "type": [
            "string",
            "null"
          ]
        }
      },
      "additionalProperties": false,
      "required": [
        "properties"
      ]
    },
    "PropertyName": {
      "type": "string",
      "pattern": "^[a-z][A-Za-z0-9]{0,99}$"
    },
    "ActionTypeName": {
      "type": "string",
      "pattern": "^[a-z][A-Za-z0-9]{0,99}$"
    },
    "SqlLevel": {
      "description": "A SQL tier a role may use besides the implicit L0.",
      "oneOf": [
        {
          "description": "Raw SQL over the ontology tables.",
          "type": "string",
          "const": "raw"
        },
        {
          "description": "Administrative SQL.",
          "type": "string",
          "const": "admin"
        }
      ]
    },
    "L2Grant": {
      "description": "Trino namespaces a role may query directly.",
      "type": "object",
      "properties": {
        "catalogs": {
          "description": "Whole catalogs.",
          "type": "array",
          "items": {
            "type": "string"
          },
          "default": []
        },
        "schemas": {
          "description": "`catalog.schema` pairs.",
          "type": "array",
          "items": {
            "type": "string"
          },
          "default": []
        }
      },
      "additionalProperties": false
    },
    "Toolset": {
      "description": "A group of MCP tools (ADR-0019).",
      "type": "string",
      "enum": [
        "core",
        "full",
        "sql:raw"
      ]
    },
    "Subject": {
      "description": "Who a role is granted to. Externally tagged so that error paths survive\ndeserialization (ADR-0003).",
      "oneOf": [
        {
          "description": "A principal id, `\"<iss>|<sub>\"` (D-04).",
          "type": "object",
          "properties": {
            "user": {
              "type": "string"
            }
          },
          "required": [
            "user"
          ],
          "additionalProperties": false
        },
        {
          "description": "A group name taken from the token's `groups` claim (D-02). With several\nissuers, `\"<iss>|<group>\"`.",
          "type": "object",
          "properties": {
            "group": {
              "type": "string"
            }
          },
          "required": [
            "group"
          ],
          "additionalProperties": false
        }
      ]
    }
  }
}
